    AacRateControlMode.add_member(:vbr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'VBR', traits: {"smithy.api#enumValue" => "VBR"}))
    AacRawFormat.add_member(:latm_loas, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LATM_LOAS', traits: {"smithy.api#enumValue" => "LATM_LOAS"}))
    AacRawFormat.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
    AacSettings.add_member(:audio_description_broadcaster_mix, Smithy::Schema::Shapes::ShapeRef.new(shape: AacAudioDescriptionBroadcasterMix, location_name: 'AudioDescriptionBroadcasterMix', traits: {"smithy.api#documentation" => "Choose BROADCASTER_MIXED_AD when the input contains pre-mixed main audio + audio description (AD) as a stereo pair. The value for AudioType will be set to 3, which signals to downstream systems that this stream contains \"broadcaster mixed AD\". Note that the input received by the encoder must contain pre-mixed audio; the encoder does not perform the mixing. When you choose BROADCASTER_MIXED_AD, the encoder ignores any values you provide in AudioType and FollowInputAudioType. Choose NORMAL when the input does not contain pre-mixed audio + audio description (AD). In this case, the encoder will use any values you provide for AudioType and FollowInputAudioType.", "smithy.api#jsonName" => "audioDescriptionBroadcasterMix"}))
    AacSettings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin6000max1024000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Specify the average bitrate in bits per second. The set of valid values for this setting is: 6000, 8000, 10000, 12000, 14000, 16000, 20000, 24000, 28000, 32000, 40000, 48000, 56000, 64000, 80000, 96000, 112000, 128000, 160000, 192000, 224000, 256000, 288000, 320000, 384000, 448000, 512000, 576000, 640000, 768000, 896000, 1024000. The value you set is also constrained by the values that you choose for Profile, Bitrate control mode, and Sample rate. Default values depend on Bitrate control mode and Profile.", "smithy.api#jsonName" => "bitrate"}))
    AacSettings.add_member(:codec_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: AacCodecProfile, location_name: 'CodecProfile', traits: {"smithy.api#documentation" => "Specify the AAC profile. For the widest player compatibility and where higher bitrates are acceptable: Keep the default profile, LC (AAC-LC) For improved audio performance at lower bitrates: Choose HEV1 or HEV2. HEV1 (AAC-HE v1) adds spectral band replication to improve speech audio at low bitrates. HEV2 (AAC-HE v2) adds parametric stereo, which optimizes for encoding stereo audio at very low bitrates.", "smithy.api#jsonName" => "codecProfile"}))
    AacSettings.add_member(:coding_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AacCodingMode, location_name: 'CodingMode', traits: {"smithy.api#documentation" => "The Coding mode that you specify determines the number of audio channels and the audio channel layout metadata in your AAC output. Valid coding modes depend on the Rate control mode and Profile that you select. The following list shows the number of audio channels and channel layout for each coding mode. * 1.0 Audio Description (Receiver Mix): One channel, C. Includes audio description data from your stereo input. For more information see ETSI TS 101 154 Annex E. * 1.0 Mono: One channel, C. * 2.0 Stereo: Two channels, L, R. * 5.1 Surround: Six channels, C, L, R, Ls, Rs, LFE.", "smithy.api#jsonName" => "codingMode"}))
    AacSettings.add_member(:loudness_measurement_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AacLoudnessMeasurementMode, location_name: 'LoudnessMeasurementMode', traits: {"smithy.api#documentation" => "Choose the loudness measurement mode for your audio content. For music or advertisements: We recommend that you keep the default value, Program. For speech or other content: We recommend that you choose Anchor. When you do, MediaConvert optimizes the loudness of your output for clarify by applying speech gates.", "smithy.api#jsonName" => "loudnessMeasurementMode"}))
    AacSettings.add_member(:rap_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin2000max30000, location_name: 'RapInterval', traits: {"smithy.api#documentation" => "Specify the RAP (Random Access Point) interval for your xHE-AAC audio output. A RAP allows a decoder to decode audio data mid-stream, without the need to reference previous audio frames, and perform adaptive audio bitrate switching. To specify the RAP interval: Enter an integer from 2000 to 30000, in milliseconds. Smaller values allow for better seeking and more frequent stream switching, while large values improve compression efficiency. To have MediaConvert automatically determine the RAP interval: Leave blank.", "smithy.api#jsonName" => "rapInterval"}))
    AacSettings.add_member(:rate_control_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AacRateControlMode, location_name: 'RateControlMode', traits: {"smithy.api#documentation" => "Specify the AAC rate control mode. For a constant bitrate: Choose CBR. Your AAC output bitrate will be equal to the value that you choose for Bitrate. For a variable bitrate: Choose VBR. Your AAC output bitrate will vary according to your audio content and the value that you choose for Bitrate quality.", "smithy.api#jsonName" => "rateControlMode"}))
    AacSettings.add_member(:raw_format, Smithy::Schema::Shapes::ShapeRef.new(shape: AacRawFormat, location_name: 'RawFormat', traits: {"smithy.api#documentation" => "Enables LATM/LOAS AAC output. Note that if you use LATM/LOAS AAC in an output, you must choose \"No container\" for the output container.", "smithy.api#jsonName" => "rawFormat"}))
    AacSettings.add_member(:sample_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin8000max96000, location_name: 'SampleRate', traits: {"smithy.api#documentation" => "Specify the AAC sample rate in samples per second (Hz). Valid sample rates depend on the AAC profile and Coding mode that you select. For a list of supported sample rates, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/aac-support.html", "smithy.api#jsonName" => "sampleRate"}))
    AacSettings.add_member(:specification, Smithy::Schema::Shapes::ShapeRef.new(shape: AacSpecification, location_name: 'Specification', traits: {"smithy.api#documentation" => "Use MPEG-2 AAC instead of MPEG-4 AAC audio for raw or MPEG-2 Transport Stream containers.", "smithy.api#jsonName" => "specification"}))
    AacSettings.add_member(:target_loudness_range, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin6max16, location_name: 'TargetLoudnessRange', traits: {"smithy.api#documentation" => "Specify the xHE-AAC loudness target. Enter an integer from 6 to 16, representing \"loudness units\". For more information, see the following specification: Supplementary information for R 128 EBU Tech 3342-2023.", "smithy.api#jsonName" => "targetLoudnessRange"}))
    AacSettings.add_member(:vbr_quality, Smithy::Schema::Shapes::ShapeRef.new(shape: AacVbrQuality, location_name: 'VbrQuality', traits: {"smithy.api#documentation" => "Specify the quality of your variable bitrate (VBR) AAC audio. For a list of approximate VBR bitrates, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/aac-support.html#aac_vbr", "smithy.api#jsonName" => "vbrQuality"}))
