    Ac3MetadataControl.add_member(:follow_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FOLLOW_INPUT', traits: {"smithy.api#enumValue" => "FOLLOW_INPUT"}))
    Ac3MetadataControl.add_member(:use_configured, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'USE_CONFIGURED', traits: {"smithy.api#enumValue" => "USE_CONFIGURED"}))
    Ac3Settings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin64000max640000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Specify the average bitrate in bits per second. The bitrate that you specify must be a multiple of 8000 within the allowed minimum and maximum values. Leave blank to use the default bitrate for the coding mode you select according ETSI TS 102 366. Valid bitrates for coding mode 1/0: Default: 96000. Minimum: 64000. Maximum: 128000. Valid bitrates for coding mode 1/1: Default: 192000. Minimum: 128000. Maximum: 384000. Valid bitrates for coding mode 2/0: Default: 192000. Minimum: 128000. Maximum: 384000. Valid bitrates for coding mode 3/2 with FLE: Default: 384000. Minimum: 384000. Maximum: 640000.", "smithy.api#jsonName" => "bitrate"}))
    Ac3Settings.add_member(:bitstream_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3BitstreamMode, location_name: 'BitstreamMode', traits: {"smithy.api#documentation" => "Specify the bitstream mode for the AC-3 stream that the encoder emits. For more information about the AC3 bitstream mode, see ATSC A/52-2012 (Annex E).", "smithy.api#jsonName" => "bitstreamMode"}))
    Ac3Settings.add_member(:coding_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3CodingMode, location_name: 'CodingMode', traits: {"smithy.api#documentation" => "Dolby Digital coding mode. Determines number of channels.", "smithy.api#jsonName" => "codingMode"}))
    Ac3Settings.add_member(:dialnorm, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max31, location_name: 'Dialnorm', traits: {"smithy.api#documentation" => "Sets the dialnorm for the output. If blank and input audio is Dolby Digital, dialnorm will be passed through.", "smithy.api#jsonName" => "dialnorm"}))
    Ac3Settings.add_member(:dynamic_range_compression_line, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3DynamicRangeCompressionLine, location_name: 'DynamicRangeCompressionLine', traits: {"smithy.api#documentation" => "Choose the Dolby Digital dynamic range control (DRC) profile that MediaConvert uses when encoding the metadata in the Dolby Digital stream for the line operating mode. Related setting: When you use this setting, MediaConvert ignores any value you provide for Dynamic range compression profile. For information about the Dolby Digital DRC operating modes and profiles, see the Dynamic Range Control chapter of the Dolby Metadata Guide at https://developer.dolby.com/globalassets/professional/documents/dolby-metadata-guide.pdf.", "smithy.api#jsonName" => "dynamicRangeCompressionLine"}))
    Ac3Settings.add_member(:dynamic_range_compression_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3DynamicRangeCompressionProfile, location_name: 'DynamicRangeCompressionProfile', traits: {"smithy.api#documentation" => "When you want to add Dolby dynamic range compression (DRC) signaling to your output stream, we recommend that you use the mode-specific settings instead of Dynamic range compression profile. The mode-specific settings are Dynamic range compression profile, line mode and Dynamic range compression profile, RF mode. Note that when you specify values for all three settings, MediaConvert ignores the value of this setting in favor of the mode-specific settings. If you do use this setting instead of the mode-specific settings, choose None to leave out DRC signaling. Keep the default Film standard to set the profile to Dolby's film standard profile for all operating modes.", "smithy.api#jsonName" => "dynamicRangeCompressionProfile"}))
    Ac3Settings.add_member(:dynamic_range_compression_rf, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3DynamicRangeCompressionRf, location_name: 'DynamicRangeCompressionRf', traits: {"smithy.api#documentation" => "Choose the Dolby Digital dynamic range control (DRC) profile that MediaConvert uses when encoding the metadata in the Dolby Digital stream for the RF operating mode. Related setting: When you use this setting, MediaConvert ignores any value you provide for Dynamic range compression profile. For information about the Dolby Digital DRC operating modes and profiles, see the Dynamic Range Control chapter of the Dolby Metadata Guide at https://developer.dolby.com/globalassets/professional/documents/dolby-metadata-guide.pdf.", "smithy.api#jsonName" => "dynamicRangeCompressionRf"}))
    Ac3Settings.add_member(:lfe_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3LfeFilter, location_name: 'LfeFilter', traits: {"smithy.api#documentation" => "Applies a 120Hz lowpass filter to the LFE channel prior to encoding. Only valid with 3_2_LFE coding mode.", "smithy.api#jsonName" => "lfeFilter"}))
    Ac3Settings.add_member(:metadata_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3MetadataControl, location_name: 'MetadataControl', traits: {"smithy.api#documentation" => "When set to FOLLOW_INPUT, encoder metadata will be sourced from the DD, DD+, or DolbyE decoder that supplied this audio data. If audio was not supplied from one of these streams, then the static metadata settings will be used.", "smithy.api#jsonName" => "metadataControl"}))
    Ac3Settings.add_member(:sample_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin48000max48000, location_name: 'SampleRate', traits: {"smithy.api#documentation" => "This value is always 48000. It represents the sample rate in Hz.", "smithy.api#jsonName" => "sampleRate"}))
