    AdvancedInputFilter.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    AdvancedInputFilterAddTexture.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    AdvancedInputFilterAddTexture.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    AdvancedInputFilterSettings.add_member(:add_texture, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedInputFilterAddTexture, location_name: 'AddTexture', traits: {"smithy.api#documentation" => "Add texture and detail to areas of your input video content that were lost after applying the Advanced input filter. To adaptively add texture and reduce softness: Choose Enabled. To not add any texture: Keep the default value, Disabled. We recommend that you choose Disabled for input video content that doesn't have texture, including screen recordings, computer graphics, or cartoons.", "smithy.api#jsonName" => "addTexture"}))
    AdvancedInputFilterSettings.add_member(:sharpening, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedInputFilterSharpen, location_name: 'Sharpening', traits: {"smithy.api#documentation" => "Optionally specify the amount of sharpening to apply when you use the Advanced input filter. Sharpening adds contrast to the edges of your video content and can reduce softness. To apply no sharpening: Keep the default value, Off. To apply a minimal amount of sharpening choose Low, or for the maximum choose High.", "smithy.api#jsonName" => "sharpening"}))
