    AudioCodecSettings.add_member(:aac_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AacSettings, location_name: 'AacSettings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value AAC. The service accepts one of two mutually exclusive groups of AAC settings--VBR and CBR. To select one of these modes, set the value of Bitrate control mode to \"VBR\" or \"CBR\". In VBR mode, you control the audio quality with the setting VBR quality. In CBR mode, you use the setting Bitrate. Defaults and valid values depend on the rate control mode.", "smithy.api#jsonName" => "aacSettings"}))
    AudioCodecSettings.add_member(:ac3_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Ac3Settings, location_name: 'Ac3Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value AC3.", "smithy.api#jsonName" => "ac3Settings"}))
    AudioCodecSettings.add_member(:aiff_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AiffSettings, location_name: 'AiffSettings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value AIFF.", "smithy.api#jsonName" => "aiffSettings"}))
    AudioCodecSettings.add_member(:codec, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioCodec, location_name: 'Codec', traits: {"smithy.api#documentation" => "Choose the audio codec for this output. Note that the option Dolby Digital passthrough applies only to Dolby Digital and Dolby Digital Plus audio inputs. Make sure that you choose a codec that's supported with your output container: https://docs.aws.amazon.com/mediaconvert/latest/ug/reference-codecs-containers.html#reference-codecs-containers-output-audio For audio-only outputs, make sure that both your input audio codec and your output audio codec are supported for audio-only workflows. For more information, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/reference-codecs-containers-input.html#reference-codecs-containers-input-audio-only and https://docs.aws.amazon.com/mediaconvert/latest/ug/reference-codecs-containers.html#audio-only-output", "smithy.api#jsonName" => "codec"}))
    AudioCodecSettings.add_member(:eac3_atmos_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosSettings, location_name: 'Eac3AtmosSettings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value EAC3_ATMOS.", "smithy.api#jsonName" => "eac3AtmosSettings"}))
    AudioCodecSettings.add_member(:eac3_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3Settings, location_name: 'Eac3Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value EAC3.", "smithy.api#jsonName" => "eac3Settings"}))
    AudioCodecSettings.add_member(:flac_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: FlacSettings, location_name: 'FlacSettings', traits: {"smithy.api#documentation" => "Required when you set Codec, under AudioDescriptions>CodecSettings, to the value FLAC.", "smithy.api#jsonName" => "flacSettings"}))
    AudioCodecSettings.add_member(:mp2_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Mp2Settings, location_name: 'Mp2Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value MP2.", "smithy.api#jsonName" => "mp2Settings"}))
