    AudioDescription.add_member(:audio_channel_tagging_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioChannelTaggingSettings, location_name: 'AudioChannelTaggingSettings', traits: {"smithy.api#documentation" => "Specify the QuickTime audio channel layout tags for the audio channels in this audio track. When you don't specify a value, MediaConvert labels your track as Center (C) by default. To use Audio layout tagging, your output must be in a QuickTime (MOV) container and your audio codec must be AAC, WAV, or AIFF.", "smithy.api#jsonName" => "audioChannelTaggingSettings"}))
    AudioDescription.add_member(:audio_normalization_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioNormalizationSettings, location_name: 'AudioNormalizationSettings', traits: {"smithy.api#documentation" => "Advanced audio normalization settings. Ignore these settings unless you need to comply with a loudness standard.", "smithy.api#jsonName" => "audioNormalizationSettings"}))
    AudioDescription.add_member(:audio_source_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmax2048, location_name: 'AudioSourceName', traits: {"smithy.api#documentation" => "Specifies which audio data to use from each input. In the simplest case, specify an \"Audio Selector\":#inputs-audio_selector by name based on its order within each input. For example if you specify \"Audio Selector 3\", then the third audio selector will be used from each input. If an input does not have an \"Audio Selector 3\", then the audio selector marked as \"default\" in that input will be used. If there is no audio selector marked as \"default\", silence will be inserted for the duration of that input. Alternatively, an \"Audio Selector Group\":#inputs-audio_selector_group name may be specified, with similar default/silence behavior. If no audio_source_name is specified, then \"Audio Selector 1\" will be chosen automatically.", "smithy.api#jsonName" => "audioSourceName"}))
    AudioDescription.add_member(:audio_type, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'AudioType', traits: {"smithy.api#documentation" => "Applies only if Follow Input Audio Type is unchecked (false). A number between 0 and 255. The following are defined in ISO-IEC 13818-1: 0 = Undefined, 1 = Clean Effects, 2 = Hearing Impaired, 3 = Visually Impaired Commentary, 4-255 = Reserved.", "smithy.api#jsonName" => "audioType"}))
    AudioDescription.add_member(:audio_type_control, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioTypeControl, location_name: 'AudioTypeControl', traits: {"smithy.api#documentation" => "When set to FOLLOW_INPUT, if the input contains an ISO 639 audio_type, then that value is passed through to the output. If the input contains no ISO 639 audio_type, the value in Audio Type is included in the output. Otherwise the value in Audio Type is included in the output. Note that this field and audioType are both ignored if audioDescriptionBroadcasterMix is set to BROADCASTER_MIXED_AD.", "smithy.api#jsonName" => "audioTypeControl"}))
    AudioDescription.add_member(:codec_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioCodecSettings, location_name: 'CodecSettings', traits: {"smithy.api#documentation" => "Settings related to audio encoding. The settings in this group vary depending on the value that you choose for your audio codec.", "smithy.api#jsonName" => "codecSettings"}))
    AudioDescription.add_member(:custom_language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatternazaz23azaz09, location_name: 'CustomLanguageCode', traits: {"smithy.api#documentation" => "Specify the language for this audio output track. The service puts this language code into your output audio track when you set Language code control to Use configured. The service also uses your specified custom language code when you set Language code control to Follow input, but your input file doesn't specify a language code. For all outputs, you can use an ISO 639-2 or ISO 639-3 code. For streaming outputs, you can also use any other code in the full RFC-5646 specification. Streaming outputs are those that are in one of the following output groups: CMAF, DASH ISO, Apple HLS, or Microsoft Smooth Streaming.", "smithy.api#jsonName" => "customLanguageCode"}))
    AudioDescription.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "Indicates the language of the audio output track. The ISO 639 language specified in the 'Language Code' drop down will be used when 'Follow Input Language Code' is not selected or when 'Follow Input Language Code' is selected but there is no ISO 639 language code specified by the input.", "smithy.api#jsonName" => "languageCode"}))
    AudioDescription.add_member(:language_code_control, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioLanguageCodeControl, location_name: 'LanguageCodeControl', traits: {"smithy.api#documentation" => "Specify which source for language code takes precedence for this audio track. When you choose Follow input, the service uses the language code from the input track if it's present. If there's no languge code on the input track, the service uses the code that you specify in the setting Language code. When you choose Use configured, the service uses the language code that you specify.", "smithy.api#jsonName" => "languageCodeControl"}))
    AudioDescription.add_member(:remix_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: RemixSettings, location_name: 'RemixSettings', traits: {"smithy.api#documentation" => "Advanced audio remixing settings.", "smithy.api#jsonName" => "remixSettings"}))
    AudioDescription.add_member(:stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatternws, location_name: 'StreamName', traits: {"smithy.api#documentation" => "Specify a label for this output audio stream. For example, \"English\", \"Director commentary\", or \"track_2\". For streaming outputs, MediaConvert passes this information into destination manifests for display on the end-viewer's player device. For outputs in other output groups, the service ignores this setting.", "smithy.api#jsonName" => "streamName"}))
    AudioDescription.type = Types::AudioDescription
