    AudioNormalizationPeakCalculation.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
    AudioNormalizationSettings.add_member(:algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioNormalizationAlgorithm, location_name: 'Algorithm', traits: {"smithy.api#documentation" => "Choose one of the following audio normalization algorithms: ITU-R BS.1770-1: Ungated loudness. A measurement of ungated average loudness for an entire piece of content, suitable for measurement of short-form content under ATSC recommendation A/85. Supports up to 5.1 audio channels. ITU-R BS.1770-2: Gated loudness. A measurement of gated average loudness compliant with the requirements of EBU-R128. Supports up to 5.1 audio channels. ITU-R BS.1770-3: Modified peak. The same loudness measurement algorithm as 1770-2, with an updated true peak measurement. ITU-R BS.1770-4: Higher channel count. Allows for more audio channels than the other algorithms, including configurations such as 7.1.", "smithy.api#jsonName" => "algorithm"}))
    AudioNormalizationSettings.add_member(:algorithm_control, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioNormalizationAlgorithmControl, location_name: 'AlgorithmControl', traits: {"smithy.api#documentation" => "When enabled the output audio is corrected using the chosen algorithm. If disabled, the audio will be measured but not adjusted.", "smithy.api#jsonName" => "algorithmControl"}))
    AudioNormalizationSettings.add_member(:correction_gate_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative70max0, location_name: 'CorrectionGateLevel', traits: {"smithy.api#documentation" => "Content measuring above this level will be corrected to the target level. Content measuring below this level will not be corrected.", "smithy.api#jsonName" => "correctionGateLevel"}))
    AudioNormalizationSettings.add_member(:loudness_logging, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioNormalizationLoudnessLogging, location_name: 'LoudnessLogging', traits: {"smithy.api#documentation" => "If set to LOG, log each output's audio track loudness to a CSV file.", "smithy.api#jsonName" => "loudnessLogging"}))
    AudioNormalizationSettings.add_member(:peak_calculation, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioNormalizationPeakCalculation, location_name: 'PeakCalculation', traits: {"smithy.api#documentation" => "If set to TRUE_PEAK, calculate and log the TruePeak for each output's audio track loudness.", "smithy.api#jsonName" => "peakCalculation"}))
    AudioNormalizationSettings.add_member(:target_lkfs, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative59max0, location_name: 'TargetLkfs', traits: {"smithy.api#documentation" => "When you use Audio normalization, optionally use this setting to specify a target loudness. If you don't specify a value here, the encoder chooses a value for you, based on the algorithm that you choose for Algorithm. If you choose algorithm 1770-1, the encoder will choose -24 LKFS; otherwise, the encoder will choose -23 LKFS.", "smithy.api#jsonName" => "targetLkfs"}))
    AudioNormalizationSettings.add_member(:true_peak_limiter_threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative8max0, location_name: 'TruePeakLimiterThreshold', traits: {"smithy.api#documentation" => "Specify the True-peak limiter threshold in decibels relative to full scale (dBFS). The peak inter-audio sample loudness in your output will be limited to the value that you specify, without affecting the overall target LKFS. Enter a value from 0 to -8. Leave blank to use the default value 0.", "smithy.api#jsonName" => "truePeakLimiterThreshold"}))
    AudioNormalizationSettings.type = Types::AudioNormalizationSettings
    AudioProperties.add_member(:bit_depth, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'BitDepth', traits: {"smithy.api#documentation" => "The bit depth of the audio track.", "smithy.api#jsonName" => "bitDepth"}))
    AudioProperties.add_member(:bit_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BitRate', traits: {"smithy.api#documentation" => "The bit rate of the audio track, in bits per second.", "smithy.api#jsonName" => "bitRate"}))
    AudioProperties.add_member(:channels, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Channels', traits: {"smithy.api#documentation" => "The number of audio channels in the audio track.", "smithy.api#jsonName" => "channels"}))
    AudioProperties.add_member(:frame_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: FrameRate, location_name: 'FrameRate', traits: {"smithy.api#documentation" => "The frame rate of the video or audio track.", "smithy.api#jsonName" => "frameRate"}))
    AudioProperties.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "The language code of the audio track, in three character ISO 639-3 format.", "smithy.api#jsonName" => "languageCode"}))
    AudioProperties.add_member(:sample_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'SampleRate', traits: {"smithy.api#documentation" => "The sample rate of the audio track.", "smithy.api#jsonName" => "sampleRate"}))
    AudioProperties.type = Types::AudioProperties
    AudioSelector.add_member(:audio_duration_correction, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioDurationCorrection, location_name: 'AudioDurationCorrection', traits: {"smithy.api#documentation" => "Apply audio timing corrections to help synchronize audio and video in your output. To apply timing corrections, your input must meet the following requirements: * Container: MP4, or MOV, with an accurate time-to-sample (STTS) table. * Audio track: AAC. Choose from the following audio timing correction settings: * Disabled (Default): Apply no correction. * Auto: Recommended for most inputs. MediaConvert analyzes the audio timing in your input and determines which correction setting to use, if needed. * Track: Adjust the duration of each audio frame by a constant amount to align the audio track length with STTS duration. Track-level correction does not affect pitch, and is recommended for tonal audio content such as music. * Frame: Adjust the duration of each audio frame by a variable amount to align audio frames with STTS timestamps. No corrections are made to already-aligned frames. Frame-level correction may affect the pitch of corrected frames, and is recommended for atonal audio content such as speech or percussion. * Force: Apply audio duration correction, either Track or Frame depending on your input, regardless of the accuracy of your input's STTS table. Your output audio and video may not be aligned or it may contain audio artifacts.", "smithy.api#jsonName" => "audioDurationCorrection"}))
    AudioSelector.add_member(:custom_language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin3max3patternazaz3, location_name: 'CustomLanguageCode', traits: {"smithy.api#documentation" => "Selects a specific language code from within an audio source, using the ISO 639-2 or ISO 639-3 three-letter language code", "smithy.api#jsonName" => "customLanguageCode"}))
    AudioSelector.add_member(:default_selection, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioDefaultSelection, location_name: 'DefaultSelection', traits: {"smithy.api#documentation" => "Enable this setting on one audio selector to set it as the default for the job. The service uses this default for outputs where it can't find the specified input audio. If you don't set a default, those outputs have no audio.", "smithy.api#jsonName" => "defaultSelection"}))
    AudioSelector.add_member(:external_audio_file_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3https, location_name: 'ExternalAudioFileInput', traits: {"smithy.api#documentation" => "Specify the S3, HTTP, or HTTPS URL for your external audio file input.", "smithy.api#jsonName" => "externalAudioFileInput"}))
    AudioSelector.add_member(:hls_rendition_group_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsRenditionGroupSettings, location_name: 'HlsRenditionGroupSettings', traits: {"smithy.api#documentation" => "Settings specific to audio sources in an HLS alternate rendition group. Specify the properties (renditionGroupId, renditionName or renditionLanguageCode) to identify the unique audio track among the alternative rendition groups present in the HLS manifest. If no unique track is found, or multiple tracks match the properties provided, the job fails. If no properties in hlsRenditionGroupSettings are specified, the default audio track within the video segment is chosen. If there is no audio within video segment, the alternative audio with DEFAULT=YES is chosen instead.", "smithy.api#jsonName" => "hlsRenditionGroupSettings"}))
    AudioSelector.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "Specify the language to select from your audio input. In the MediaConvert console choose from a list of languages. In your JSON job settings choose from an ISO 639-2 three-letter code listed at https://www.loc.gov/standards/iso639-2/php/code_list.php", "smithy.api#jsonName" => "languageCode"}))
    AudioSelector.add_member(:offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'Offset', traits: {"smithy.api#documentation" => "Specify a time delta, in milliseconds, to offset the audio from the input video.\nTo specify no offset: Keep the default value, 0.\nTo specify an offset: Enter an integer from -2147483648 to 2147483647", "smithy.api#jsonName" => "offset"}))
    AudioSelector.add_member(:pids, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofIntegermin1max2147483647, location_name: 'Pids', traits: {"smithy.api#documentation" => "Selects a specific PID from within an audio source (e.g. 257 selects PID 0x101).", "smithy.api#jsonName" => "pids"}))
    AudioSelector.add_member(:program_selection, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max8, location_name: 'ProgramSelection', traits: {"smithy.api#documentation" => "Use this setting for input streams that contain Dolby E, to have the service extract specific program data from the track. To select multiple programs, create multiple selectors with the same Track and different Program numbers. In the console, this setting is visible when you set Selector type to Track. Choose the program number from the dropdown list. If your input file has incorrect metadata, you can choose All channels instead of a program number to have the service ignore the program IDs and include all the programs in the track.", "smithy.api#jsonName" => "programSelection"}))
    AudioSelector.add_member(:remix_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: RemixSettings, location_name: 'RemixSettings', traits: {"smithy.api#documentation" => "Use these settings to reorder the audio channels of one input to match those of another input. This allows you to combine the two files into a single output, one after the other.", "smithy.api#jsonName" => "remixSettings"}))
    AudioSelector.add_member(:selector_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioSelectorType, location_name: 'SelectorType', traits: {"smithy.api#documentation" => "Specify how MediaConvert selects audio content within your input. The default is Track. PID: Select audio by specifying the Packet Identifier (PID) values for MPEG Transport Stream inputs. Use this when you know the exact PID values of your audio streams. Track: Default. Select audio by track number. This is the most common option and works with most input container formats. Language code: Select audio by language using ISO 639-2 or ISO 639-3 three-letter language codes. Use this when your source has embedded language metadata and you want to select tracks based on their language. HLS rendition group: Select audio from an HLS rendition group. Use this when your input is an HLS package with multiple audio renditions and you want to select specific rendition groups. All PCM: Select all uncompressed PCM audio tracks from your input automatically. This is useful when you want to include all PCM audio tracks without specifying individual track numbers.", "smithy.api#jsonName" => "selectorType"}))
    AudioSelector.add_member(:tracks, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofIntegermin1max2147483647, location_name: 'Tracks', traits: {"smithy.api#documentation" => "Identify a track from the input audio to include in this selector by entering the track index number. To include several tracks in a single audio selector, specify multiple tracks as follows. Using the console, enter a comma-separated list. For example, type \"1,2,3\" to include tracks 1 through 3.", "smithy.api#jsonName" => "tracks"}))
    AudioSelector.type = Types::AudioSelector
    AudioSelectorGroup.add_member(:audio_selector_names, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofStringmin1, location_name: 'AudioSelectorNames', traits: {"smithy.api#documentation" => "Name of an Audio Selector within the same input to include in the group. Audio selector names are standardized, based on their order within the input (e.g., \"Audio Selector 1\"). The audio selector name parameter can be repeated to add any number of audio selectors to the group.", "smithy.api#jsonName" => "audioSelectorNames"}))
    AudioSelectorGroup.type = Types::AudioSelectorGroup
    AudioSelectorType.add_member(:pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PID', traits: {"smithy.api#enumValue" => "PID"}))
