    AudioSelectorType.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LANGUAGE_CODE', traits: {"smithy.api#enumValue" => "LANGUAGE_CODE"}))
    AudioSelectorType.add_member(:hls_rendition_group, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HLS_RENDITION_GROUP', traits: {"smithy.api#enumValue" => "HLS_RENDITION_GROUP"}))
    AudioSelectorType.add_member(:all_pcm, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ALL_PCM', traits: {"smithy.api#enumValue" => "ALL_PCM"}))
    AudioTypeControl.add_member(:follow_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FOLLOW_INPUT', traits: {"smithy.api#enumValue" => "FOLLOW_INPUT"}))
    AudioTypeControl.add_member(:use_configured, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'USE_CONFIGURED', traits: {"smithy.api#enumValue" => "USE_CONFIGURED"}))
    AutomatedAbrRule.add_member(:allowed_renditions, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofallowedrenditionsize, location_name: 'AllowedRenditions', traits: {"smithy.api#documentation" => "When customer adds the allowed renditions rule for auto ABR ladder, they are required to add at leat one rendition to allowedRenditions list", "smithy.api#jsonName" => "allowedRenditions"}))
    AutomatedAbrRule.add_member(:force_include_renditions, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofforceincluderenditionsize, location_name: 'ForceIncludeRenditions', traits: {"smithy.api#documentation" => "When customer adds the force include renditions rule for auto ABR ladder, they are required to add at leat one rendition to forceIncludeRenditions list", "smithy.api#jsonName" => "forceIncludeRenditions"}))
    AutomatedAbrRule.add_member(:min_bottom_rendition_size, Smithy::Schema::Shapes::ShapeRef.new(shape: MinBottomRenditionSize, location_name: 'MinBottomRenditionSize', traits: {"smithy.api#documentation" => "Use Min bottom rendition size to specify a minimum size for the lowest resolution in your ABR stack. * The lowest resolution in your ABR stack will be equal to or greater than the value that you enter. For example: If you specify 640x360 the lowest resolution in your ABR stack will be equal to or greater than to 640x360. * If you specify a Min top rendition size rule, the value that you specify for Min bottom rendition size must be less than, or equal to, Min top rendition size.", "smithy.api#jsonName" => "minBottomRenditionSize"}))
    AutomatedAbrRule.add_member(:min_top_rendition_size, Smithy::Schema::Shapes::ShapeRef.new(shape: MinTopRenditionSize, location_name: 'MinTopRenditionSize', traits: {"smithy.api#documentation" => "Use Min top rendition size to specify a minimum size for the highest resolution in your ABR stack. * The highest resolution in your ABR stack will be equal to or greater than the value that you enter. For example: If you specify 1280x720 the highest resolution in your ABR stack will be equal to or greater than 1280x720. * If you specify a value for Max resolution, the value that you specify for Min top rendition size must be less than, or equal to, Max resolution.", "smithy.api#jsonName" => "minTopRenditionSize"}))
    AutomatedAbrRule.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleType, location_name: 'Type', traits: {"smithy.api#documentation" => "Use Min top rendition size to specify a minimum size for the highest resolution in your ABR stack. * The highest resolution in your ABR stack will be equal to or greater than the value that you enter. For example: If you specify 1280x720 the highest resolution in your ABR stack will be equal to or greater than 1280x720. * If you specify a value for Max resolution, the value that you specify for Min top rendition size must be less than, or equal to, Max resolution. Use Min bottom rendition size to specify a minimum size for the lowest resolution in your ABR stack. * The lowest resolution in your ABR stack will be equal to or greater than the value that you enter. For example: If you specify 640x360 the lowest resolution in your ABR stack will be equal to or greater than to 640x360. * If you specify a Min top rendition size rule, the value that you specify for Min bottom rendition size must be less than, or equal to, Min top rendition size. Use Force include renditions to specify one or more resolutions to include your ABR stack. * (Recommended) To optimize automated ABR, specify as few resolutions as possible. * (Required) The number of resolutions that you specify must be equal to, or less than, the Max renditions setting. * If you specify a Min top rendition size rule, specify at least one resolution that is equal to, or greater than, Min top rendition size. * If you specify a Min bottom rendition size rule, only specify resolutions that are equal to, or greater than, Min bottom rendition size. * If you specify a Force include renditions rule, do not specify a separate rule for Allowed renditions. * Note: The ABR stack may include other resolutions that you do not specify here, depending on the Max renditions setting. Use Allowed renditions to specify a list of possible resolutions in your ABR stack. * (Required) The number of resolutions that you specify must be equal to, or greater than, the Max renditions setting. * MediaConvert will create an ABR stack exclusively from the list of resolutions that you specify. * Some resolutions in the Allowed renditions list may not be included, however you can force a resolution to be included by setting Required to ENABLED. * You must specify at least one resolution that is greater than or equal to any resolutions that you specify in Min top rendition size or Min bottom rendition size. * If you specify Allowed renditions, you must not specify a separate rule for Force include renditions.", "smithy.api#jsonName" => "type"}))
    AutomatedAbrRule.type = Types::AutomatedAbrRule
    AutomatedAbrSettings.add_member(:max_abr_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin100000max100000000, location_name: 'MaxAbrBitrate', traits: {"smithy.api#documentation" => "Specify the maximum average bitrate for MediaConvert to use in your automated ABR stack. If you don't specify a value, MediaConvert uses 8,000,000 (8 mb/s) by default. The average bitrate of your highest-quality rendition will be equal to or below this value, depending on the quality, complexity, and resolution of your content. Note that the instantaneous maximum bitrate may vary above the value that you specify.", "smithy.api#jsonName" => "maxAbrBitrate"}))
    AutomatedAbrSettings.add_member(:max_quality_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin1max10, location_name: 'MaxQualityLevel', traits: {"smithy.api#documentation" => "Optional. Specify the QVBR quality level to use for all renditions in your automated ABR stack. To have MediaConvert automatically determine the quality level: Leave blank. To manually specify a quality level: Enter a value from 1 to 10. MediaConvert will use a quality level up to the value that you specify, depending on your source. For more information about QVBR quality levels, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/qvbr-guidelines.html", "smithy.api#jsonName" => "maxQualityLevel"}))
    AutomatedAbrSettings.add_member(:max_renditions, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin3max15, location_name: 'MaxRenditions', traits: {"smithy.api#documentation" => "Optional. The maximum number of renditions that MediaConvert will create in your automated ABR stack. The number of renditions is determined automatically, based on analysis of each job, but will never exceed this limit. When you set this to Auto in the console, which is equivalent to excluding it from your JSON job specification, MediaConvert defaults to a limit of 15.", "smithy.api#jsonName" => "maxRenditions"}))
    AutomatedAbrSettings.add_member(:min_abr_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin100000max100000000, location_name: 'MinAbrBitrate', traits: {"smithy.api#documentation" => "Specify the minimum average bitrate for MediaConvert to use in your automated ABR stack. If you don't specify a value, MediaConvert uses 600,000 (600 kb/s) by default. The average bitrate of your lowest-quality rendition will be near this value. Note that the instantaneous minimum bitrate may vary below the value that you specify.", "smithy.api#jsonName" => "minAbrBitrate"}))
    AutomatedAbrSettings.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofautomatedabrrule, location_name: 'Rules', traits: {"smithy.api#documentation" => "Optional. Use Automated ABR rules to specify restrictions for the rendition sizes MediaConvert will create in your ABR stack. You can use these rules if your ABR workflow has specific rendition size requirements, but you still want MediaConvert to optimize for video quality and overall file size.", "smithy.api#jsonName" => "rules"}))
    AutomatedAbrSettings.type = Types::AutomatedAbrSettings
    AutomatedEncodingSettings.add_member(:abr_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomatedAbrSettings, location_name: 'AbrSettings', traits: {"smithy.api#documentation" => "Use automated ABR to have MediaConvert set up the renditions in your ABR package for you automatically, based on characteristics of your input video. This feature optimizes video quality while minimizing the overall size of your ABR package.", "smithy.api#jsonName" => "abrSettings"}))
    AutomatedEncodingSettings.type = Types::AutomatedEncodingSettings
