    Av1AdaptiveQuantization.add_member(:max, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MAX', traits: {"smithy.api#enumValue" => "MAX"}))
    Av1BitDepth.add_member(:bit_8, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BIT_8', traits: {"smithy.api#enumValue" => "BIT_8"}))
    Av1BitDepth.add_member(:bit_10, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BIT_10', traits: {"smithy.api#enumValue" => "BIT_10"}))
