    Av1FilmGrainSynthesis.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    Av1FramerateControl.add_member(:initialize_from_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INITIALIZE_FROM_SOURCE', traits: {"smithy.api#enumValue" => "INITIALIZE_FROM_SOURCE"}))
    Av1FramerateControl.add_member(:specified, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFIED', traits: {"smithy.api#enumValue" => "SPECIFIED"}))
    Av1FramerateConversionAlgorithm.add_member(:duplicate_drop, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DUPLICATE_DROP', traits: {"smithy.api#enumValue" => "DUPLICATE_DROP"}))
    Av1FramerateConversionAlgorithm.add_member(:interpolate, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTERPOLATE', traits: {"smithy.api#enumValue" => "INTERPOLATE"}))
    Av1FramerateConversionAlgorithm.add_member(:frameformer, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FRAMEFORMER', traits: {"smithy.api#enumValue" => "FRAMEFORMER"}))
    Av1FramerateConversionAlgorithm.add_member(:maintain_frame_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MAINTAIN_FRAME_COUNT', traits: {"smithy.api#enumValue" => "MAINTAIN_FRAME_COUNT"}))
    Av1QvbrSettings.add_member(:qvbr_quality_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max10, location_name: 'QvbrQualityLevel', traits: {"smithy.api#documentation" => "Use this setting only when you set Rate control mode to QVBR. Specify the target quality level for this output. MediaConvert determines the right number of bits to use for each part of the video to maintain the video quality that you specify. When you keep the default value, AUTO, MediaConvert picks a quality level for you, based on characteristics of your input video. If you prefer to specify a quality level, specify a number from 1 through 10. Use higher numbers for greater quality. Level 10 results in nearly lossless compression. The quality level for most broadcast-quality transcodes is between 6 and 9. Optionally, to specify a value between whole numbers, also provide a value for the setting qvbrQualityLevelFineTune. For example, if you want your QVBR quality level to be 7.33, set qvbrQualityLevel to 7 and set qvbrQualityLevelFineTune to .33.", "smithy.api#jsonName" => "qvbrQualityLevel"}))
    Av1QvbrSettings.add_member(:qvbr_quality_level_fine_tune, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0max1, location_name: 'QvbrQualityLevelFineTune', traits: {"smithy.api#documentation" => "Optional. Specify a value here to set the QVBR quality to a level that is between whole numbers. For example, if you want your QVBR quality level to be 7.33, set qvbrQualityLevel to 7 and set qvbrQualityLevelFineTune to .33. MediaConvert rounds your QVBR quality level to the nearest third of a whole number. For example, if you set qvbrQualityLevel to 7 and you set qvbrQualityLevelFineTune to .25, your actual QVBR quality level is 7.33.", "smithy.api#jsonName" => "qvbrQualityLevelFineTune"}))
    Av1QvbrSettings.type = Types::Av1QvbrSettings
    Av1RateControlMode.add_member(:qvbr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'QVBR', traits: {"smithy.api#enumValue" => "QVBR"}))
    Av1Settings.add_member(:adaptive_quantization, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1AdaptiveQuantization, location_name: 'AdaptiveQuantization', traits: {"smithy.api#documentation" => "Specify the strength of any adaptive quantization filters that you enable. The value that you choose here applies to Spatial adaptive quantization.", "smithy.api#jsonName" => "adaptiveQuantization"}))
    Av1Settings.add_member(:bit_depth, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1BitDepth, location_name: 'BitDepth', traits: {"smithy.api#documentation" => "Specify the Bit depth. You can choose 8-bit or 10-bit.", "smithy.api#jsonName" => "bitDepth"}))
    Av1Settings.add_member(:film_grain_synthesis, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1FilmGrainSynthesis, location_name: 'FilmGrainSynthesis', traits: {"smithy.api#documentation" => "Film grain synthesis replaces film grain present in your content with similar quality synthesized AV1 film grain. We recommend that you choose Enabled to reduce the bandwidth of your QVBR quality level 5, 6, 7, or 8 outputs. For QVBR quality level 9 or 10 outputs we recommend that you keep the default value, Disabled. When you include Film grain synthesis, you cannot include the Noise reducer preprocessor.", "smithy.api#jsonName" => "filmGrainSynthesis"}))
    Av1Settings.add_member(:framerate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1FramerateControl, location_name: 'FramerateControl', traits: {"smithy.api#documentation" => "Use the Framerate setting to specify the frame rate for this output. If you want to keep the same frame rate as the input video, choose Follow source. If you want to do frame rate conversion, choose a frame rate from the dropdown list or choose Custom. The framerates shown in the dropdown list are decimal approximations of fractions. If you choose Custom, specify your frame rate as a fraction.", "smithy.api#jsonName" => "framerateControl"}))
    Av1Settings.add_member(:framerate_conversion_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1FramerateConversionAlgorithm, location_name: 'FramerateConversionAlgorithm', traits: {"smithy.api#documentation" => "Choose the method that you want MediaConvert to use when increasing or decreasing your video's frame rate. For numerically simple conversions, such as 60 fps to 30 fps: We recommend that you keep the default value, Drop duplicate. For numerically complex conversions, to avoid stutter: Choose Interpolate. This results in a smooth picture, but might introduce undesirable video artifacts. For complex frame rate conversions, especially if your source video has already been converted from its original cadence: Choose FrameFormer to do motion-compensated interpolation. FrameFormer uses the best conversion method frame by frame. Note that using FrameFormer increases the transcoding time and incurs a significant add-on cost. When you choose FrameFormer, your input video resolution must be at least 128x96. To create an output with the same number of frames as your input: Choose Maintain frame count. When you do, MediaConvert will not drop, interpolate, add, or otherwise change the frame count from your input to your output. Note that since the frame count is maintained, the duration of your output will become shorter at higher frame rates and longer at lower frame rates.", "smithy.api#jsonName" => "framerateConversionAlgorithm"}))
    Av1Settings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'FramerateDenominator', traits: {"smithy.api#documentation" => "When you use the API for transcode jobs that use frame rate conversion, specify the frame rate as a fraction. For example, 24000 / 1001 = 23.976 fps. Use FramerateDenominator to specify the denominator of this fraction. In this example, use 1001 for the value of FramerateDenominator. When you use the console for transcode jobs that use frame rate conversion, provide the value as a decimal number for Framerate. In this example, specify 23.976.", "smithy.api#jsonName" => "framerateDenominator"}))
    Av1Settings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'FramerateNumerator', traits: {"smithy.api#documentation" => "When you use the API for transcode jobs that use frame rate conversion, specify the frame rate as a fraction. For example, 24000 / 1001 = 23.976 fps. Use FramerateNumerator to specify the numerator of this fraction. In this example, use 24000 for the value of FramerateNumerator. When you use the console for transcode jobs that use frame rate conversion, provide the value as a decimal number for Framerate. In this example, specify 23.976.", "smithy.api#jsonName" => "framerateNumerator"}))
    Av1Settings.add_member(:gop_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0, location_name: 'GopSize', traits: {"smithy.api#documentation" => "Specify the GOP length (keyframe interval) in frames. With AV1, MediaConvert doesn't support GOP length in seconds. This value must be greater than zero and preferably equal to 1 + ((numberBFrames + 1) * x), where x is an integer value.", "smithy.api#jsonName" => "gopSize"}))
    Av1Settings.add_member(:max_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1000max1152000000, location_name: 'MaxBitrate', traits: {"smithy.api#documentation" => "Maximum bitrate in bits/second. For example, enter five megabits per second as 5000000. Required when Rate control mode is QVBR.", "smithy.api#jsonName" => "maxBitrate"}))
    Av1Settings.add_member(:number_b_frames_between_reference_frames, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max15, location_name: 'NumberBFramesBetweenReferenceFrames', traits: {"smithy.api#documentation" => "Specify from the number of B-frames, in the range of 0-15. For AV1 encoding, we recommend using 7 or 15. Choose a larger number for a lower bitrate and smaller file size; choose a smaller number for better video quality.", "smithy.api#jsonName" => "numberBFramesBetweenReferenceFrames"}))
    Av1Settings.add_member(:per_frame_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofframemetrictype, location_name: 'PerFrameMetrics', traits: {"smithy.api#documentation" => "Optionally choose one or more per frame metric reports to generate along with your output. You can use these metrics to analyze your video output according to one or more commonly used image quality metrics. You can specify per frame metrics for output groups or for individual outputs. When you do, MediaConvert writes a CSV (Comma-Separated Values) file to your S3 output destination, named after the output name and metric type. For example: videofile_PSNR.csv Jobs that generate per frame metrics will take longer to complete, depending on the resolution and complexity of your output. For example, some 4K jobs might take up to twice as long to complete. Note that when analyzing the video quality of your output, or when comparing the video quality of multiple different outputs, we generally also recommend a detailed visual review in a controlled environment. You can choose from the following per frame metrics: * PSNR: Peak Signal-to-Noise Ratio * SSIM: Structural Similarity Index Measure * MS_SSIM: Multi-Scale Similarity Index Measure * PSNR_HVS: Peak Signal-to-Noise Ratio, Human Visual System * VMAF: Video Multi-Method Assessment Fusion * QVBR: Quality-Defined Variable Bitrate. This option is only available when your output uses the QVBR rate control mode.", "smithy.api#jsonName" => "perFrameMetrics"}))
    Av1Settings.add_member(:qvbr_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1QvbrSettings, location_name: 'QvbrSettings', traits: {"smithy.api#documentation" => "Settings for quality-defined variable bitrate encoding with the H.265 codec. Use these settings only when you set QVBR for Rate control mode.", "smithy.api#jsonName" => "qvbrSettings"}))
    Av1Settings.add_member(:rate_control_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1RateControlMode, location_name: 'RateControlMode', traits: {"smithy.api#documentation" => "'With AV1 outputs, for rate control mode, MediaConvert supports only quality-defined variable bitrate (QVBR). You can''t use CBR or VBR.'", "smithy.api#jsonName" => "rateControlMode"}))
    Av1Settings.add_member(:slices, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max32, location_name: 'Slices', traits: {"smithy.api#documentation" => "Specify the number of slices per picture. This value must be 1, 2, 4, 8, 16, or 32. For progressive pictures, this value must be less than or equal to the number of macroblock rows. For interlaced pictures, this value must be less than or equal to half the number of macroblock rows.", "smithy.api#jsonName" => "slices"}))
    Av1Settings.add_member(:spatial_adaptive_quantization, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1SpatialAdaptiveQuantization, location_name: 'SpatialAdaptiveQuantization', traits: {"smithy.api#documentation" => "Keep the default value, Enabled, to adjust quantization within each frame based on spatial variation of content complexity. When you enable this feature, the encoder uses fewer bits on areas that can sustain more distortion with no noticeable visual degradation and uses more bits on areas where any small distortion will be noticeable. For example, complex textured blocks are encoded with fewer bits and smooth textured blocks are encoded with more bits. Enabling this feature will almost always improve your video quality. Note, though, that this feature doesn't take into account where the viewer's attention is likely to be. If viewers are likely to be focusing their attention on a part of the screen with a lot of complex texture, you might choose to disable this feature. Related setting: When you enable spatial adaptive quantization, set the value for Adaptive quantization depending on your content. For homogeneous content, such as cartoons and video games, set it to Low. For content with a wider variety of textures, set it to High or Higher.", "smithy.api#jsonName" => "spatialAdaptiveQuantization"}))
    Av1Settings.type = Types::Av1Settings
    Av1SpatialAdaptiveQuantization.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    Av1SpatialAdaptiveQuantization.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    AvailBlanking.add_member(:avail_blanking_image, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin14patterns3bmpbmppngpnghttpsbmpbmppngpng, location_name: 'AvailBlankingImage', traits: {"smithy.api#documentation" => "Blanking image to be used. Leave empty for solid black. Only bmp and png images are supported.", "smithy.api#jsonName" => "availBlankingImage"}))
    AvailBlanking.type = Types::AvailBlanking
