    AvcIntraFramerateControl.add_member(:specified, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFIED', traits: {"smithy.api#enumValue" => "SPECIFIED"}))
