    AvcIntraFramerateConversionAlgorithm.add_member(:interpolate, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTERPOLATE', traits: {"smithy.api#enumValue" => "INTERPOLATE"}))
