    AvcIntraInterlaceMode.add_member(:progressive, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROGRESSIVE', traits: {"smithy.api#enumValue" => "PROGRESSIVE"}))
    AvcIntraInterlaceMode.add_member(:top_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TOP_FIELD', traits: {"smithy.api#enumValue" => "TOP_FIELD"}))
    AvcIntraInterlaceMode.add_member(:bottom_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BOTTOM_FIELD', traits: {"smithy.api#enumValue" => "BOTTOM_FIELD"}))
    AvcIntraInterlaceMode.add_member(:follow_top_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FOLLOW_TOP_FIELD', traits: {"smithy.api#enumValue" => "FOLLOW_TOP_FIELD"}))
    AvcIntraInterlaceMode.add_member(:follow_bottom_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FOLLOW_BOTTOM_FIELD', traits: {"smithy.api#enumValue" => "FOLLOW_BOTTOM_FIELD"}))
    AvcIntraScanTypeConversionMode.add_member(:interlaced, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTERLACED', traits: {"smithy.api#enumValue" => "INTERLACED"}))
    AvcIntraScanTypeConversionMode.add_member(:interlaced_optimize, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTERLACED_OPTIMIZE', traits: {"smithy.api#enumValue" => "INTERLACED_OPTIMIZE"}))
    AvcIntraSettings.add_member(:avc_intra_class, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraClass, location_name: 'AvcIntraClass', traits: {"smithy.api#documentation" => "Specify the AVC-Intra class of your output. The AVC-Intra class selection determines the output video bit rate depending on the frame rate of the output. Outputs with higher class values have higher bitrates and improved image quality. Note that for Class 4K/2K, MediaConvert supports only 4:2:2 chroma subsampling.", "smithy.api#jsonName" => "avcIntraClass"}))
    AvcIntraSettings.add_member(:avc_intra_uhd_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraUhdSettings, location_name: 'AvcIntraUhdSettings', traits: {"smithy.api#documentation" => "Optional when you set AVC-Intra class to Class 4K/2K. When you set AVC-Intra class to a different value, this object isn't allowed.", "smithy.api#jsonName" => "avcIntraUhdSettings"}))
    AvcIntraSettings.add_member(:framerate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraFramerateControl, location_name: 'FramerateControl', traits: {"smithy.api#documentation" => "If you are using the console, use the Framerate setting to specify the frame rate for this output. If you want to keep the same frame rate as the input video, choose Follow source. If you want to do frame rate conversion, choose a frame rate from the dropdown list or choose Custom. The framerates shown in the dropdown list are decimal approximations of fractions. If you choose Custom, specify your frame rate as a fraction.", "smithy.api#jsonName" => "framerateControl"}))
    AvcIntraSettings.add_member(:framerate_conversion_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraFramerateConversionAlgorithm, location_name: 'FramerateConversionAlgorithm', traits: {"smithy.api#documentation" => "Choose the method that you want MediaConvert to use when increasing or decreasing your video's frame rate. For numerically simple conversions, such as 60 fps to 30 fps: We recommend that you keep the default value, Drop duplicate. For numerically complex conversions, to avoid stutter: Choose Interpolate. This results in a smooth picture, but might introduce undesirable video artifacts. For complex frame rate conversions, especially if your source video has already been converted from its original cadence: Choose FrameFormer to do motion-compensated interpolation. FrameFormer uses the best conversion method frame by frame. Note that using FrameFormer increases the transcoding time and incurs a significant add-on cost. When you choose FrameFormer, your input video resolution must be at least 128x96. To create an output with the same number of frames as your input: Choose Maintain frame count. When you do, MediaConvert will not drop, interpolate, add, or otherwise change the frame count from your input to your output. Note that since the frame count is maintained, the duration of your output will become shorter at higher frame rates and longer at lower frame rates.", "smithy.api#jsonName" => "framerateConversionAlgorithm"}))
    AvcIntraSettings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max1001, location_name: 'FramerateDenominator', traits: {"smithy.api#documentation" => "When you use the API for transcode jobs that use frame rate conversion, specify the frame rate as a fraction. For example, 24000 / 1001 = 23.976 fps. Use FramerateDenominator to specify the denominator of this fraction. In this example, use 1001 for the value of FramerateDenominator. When you use the console for transcode jobs that use frame rate conversion, provide the value as a decimal number for Framerate. In this example, specify 23.976.", "smithy.api#jsonName" => "framerateDenominator"}))
    AvcIntraSettings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin24max60000, location_name: 'FramerateNumerator', traits: {"smithy.api#documentation" => "When you use the API for transcode jobs that use frame rate conversion, specify the frame rate as a fraction. For example, 24000 / 1001 = 23.976 fps. Use FramerateNumerator to specify the numerator of this fraction. In this example, use 24000 for the value of FramerateNumerator. When you use the console for transcode jobs that use frame rate conversion, provide the value as a decimal number for Framerate. In this example, specify 23.976.", "smithy.api#jsonName" => "framerateNumerator"}))
    AvcIntraSettings.add_member(:interlace_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraInterlaceMode, location_name: 'InterlaceMode', traits: {"smithy.api#documentation" => "Choose the scan line type for the output. Keep the default value, Progressive to create a progressive output, regardless of the scan type of your input. Use Top field first or Bottom field first to create an output that's interlaced with the same field polarity throughout. Use Follow, default top or Follow, default bottom to produce outputs with the same field polarity as the source. For jobs that have multiple inputs, the output field polarity might change over the course of the output. Follow behavior depends on the input scan type. If the source is interlaced, the output will be interlaced with the same polarity as the source. If the source is progressive, the output will be interlaced with top field bottom field first, depending on which of the Follow options you choose.", "smithy.api#jsonName" => "interlaceMode"}))
    AvcIntraSettings.add_member(:per_frame_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofframemetrictype, location_name: 'PerFrameMetrics', traits: {"smithy.api#documentation" => "Optionally choose one or more per frame metric reports to generate along with your output. You can use these metrics to analyze your video output according to one or more commonly used image quality metrics. You can specify per frame metrics for output groups or for individual outputs. When you do, MediaConvert writes a CSV (Comma-Separated Values) file to your S3 output destination, named after the output name and metric type. For example: videofile_PSNR.csv Jobs that generate per frame metrics will take longer to complete, depending on the resolution and complexity of your output. For example, some 4K jobs might take up to twice as long to complete. Note that when analyzing the video quality of your output, or when comparing the video quality of multiple different outputs, we generally also recommend a detailed visual review in a controlled environment. You can choose from the following per frame metrics: * PSNR: Peak Signal-to-Noise Ratio * SSIM: Structural Similarity Index Measure * MS_SSIM: Multi-Scale Similarity Index Measure * PSNR_HVS: Peak Signal-to-Noise Ratio, Human Visual System * VMAF: Video Multi-Method Assessment Fusion * QVBR: Quality-Defined Variable Bitrate. This option is only available when your output uses the QVBR rate control mode.", "smithy.api#jsonName" => "perFrameMetrics"}))
    AvcIntraSettings.add_member(:scan_type_conversion_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraScanTypeConversionMode, location_name: 'ScanTypeConversionMode', traits: {"smithy.api#documentation" => "Use this setting for interlaced outputs, when your output frame rate is half of your input frame rate. In this situation, choose Optimized interlacing to create a better quality interlaced output. In this case, each progressive frame from the input corresponds to an interlaced field in the output. Keep the default value, Basic interlacing, for all other output frame rates. With basic interlacing, MediaConvert performs any frame rate conversion first and then interlaces the frames. When you choose Optimized interlacing and you set your output frame rate to a value that isn't suitable for optimized interlacing, MediaConvert automatically falls back to basic interlacing. Required settings: To use optimized interlacing, you must set Telecine to None or Soft. You can't use optimized interlacing for hard telecine outputs. You must also set Interlace mode to a value other than Progressive.", "smithy.api#jsonName" => "scanTypeConversionMode"}))
    AvcIntraSettings.add_member(:slow_pal, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraSlowPal, location_name: 'SlowPal', traits: {"smithy.api#documentation" => "Ignore this setting unless your input frame rate is 23.976 or 24 frames per second (fps). Enable slow PAL to create a 25 fps output. When you enable slow PAL, MediaConvert relabels the video frames to 25 fps and resamples your audio to keep it synchronized with the video. Note that enabling this setting will slightly reduce the duration of your video. Required settings: You must also set Framerate to 25.", "smithy.api#jsonName" => "slowPal"}))
    AvcIntraSettings.add_member(:telecine, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraTelecine, location_name: 'Telecine', traits: {"smithy.api#documentation" => "When you do frame rate conversion from 23.976 frames per second (fps) to 29.97 fps, and your output scan type is interlaced, you can optionally enable hard telecine to create a smoother picture. When you keep the default value, None, MediaConvert does a standard frame rate conversion to 29.97 without doing anything with the field polarity to create a smoother picture.", "smithy.api#jsonName" => "telecine"}))
    AvcIntraSettings.type = Types::AvcIntraSettings
    AvcIntraSlowPal.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    AvcIntraSlowPal.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    AvcIntraTelecine.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
