    BandwidthReductionFilter.add_member(:sharpening, Smithy::Schema::Shapes::ShapeRef.new(shape: BandwidthReductionFilterSharpening, location_name: 'Sharpening', traits: {"smithy.api#documentation" => "Optionally specify the level of sharpening to apply when you use the Bandwidth reduction filter. Sharpening adds contrast to the edges of your video content and can reduce softness. Keep the default value Off to apply no sharpening. Set Sharpening strength to Low to apply a minimal amount of sharpening, or High to apply a maximum amount of sharpening.", "smithy.api#jsonName" => "sharpening"}))
    BandwidthReductionFilter.add_member(:strength, Smithy::Schema::Shapes::ShapeRef.new(shape: BandwidthReductionFilterStrength, location_name: 'Strength', traits: {"smithy.api#documentation" => "Specify the strength of the Bandwidth reduction filter. For most workflows, we recommend that you choose Auto to reduce the bandwidth of your output with little to no perceptual decrease in video quality. For high quality and high bitrate outputs, choose Low. For the most bandwidth reduction, choose High. We recommend that you choose High for low bitrate outputs. Note that High may incur a slight increase in the softness of your output.", "smithy.api#jsonName" => "strength"}))
    BandwidthReductionFilter.type = Types::BandwidthReductionFilter
