    BurninDestinationSettings.add_member(:alignment, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleAlignment, location_name: 'Alignment', traits: {"smithy.api#documentation" => "Specify the alignment of your captions. If no explicit x_position is provided, setting alignment to centered will placethe captions at the bottom center of the output. Similarly, setting a left alignment willalign captions to the bottom left of the output. If x and y positions are given in conjunction with the alignment parameter, the font will be justified (either left or centered) relative to those coordinates.", "smithy.api#jsonName" => "alignment"}))
    BurninDestinationSettings.add_member(:apply_font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleApplyFontColor, location_name: 'ApplyFontColor', traits: {"smithy.api#documentation" => "Ignore this setting unless Style passthrough is set to Enabled and Font color set to Black, Yellow, Red, Green, Blue, or Hex. Use Apply font color for additional font color controls. When you choose White text only, or leave blank, your font color setting only applies to white text in your input captions. For example, if your font color setting is Yellow, and your input captions have red and white text, your output captions will have red and yellow text. When you choose ALL_TEXT, your font color setting applies to all of your output captions text.", "smithy.api#jsonName" => "applyFontColor"}))
    BurninDestinationSettings.add_member(:background_color, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleBackgroundColor, location_name: 'BackgroundColor', traits: {"smithy.api#documentation" => "Specify the color of the rectangle behind the captions. Leave background color blank and set Style passthrough to enabled to use the background color data from your input captions, if present.", "smithy.api#jsonName" => "backgroundColor"}))
    BurninDestinationSettings.add_member(:background_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'BackgroundOpacity', traits: {"smithy.api#documentation" => "Specify the opacity of the background rectangle. Enter a value from 0 to 255, where 0 is transparent and 255 is opaque. If Style passthrough is set to enabled, leave blank to pass through the background style information in your input captions to your output captions. If Style passthrough is set to disabled, leave blank to use a value of 0 and remove all backgrounds from your output captions.", "smithy.api#jsonName" => "backgroundOpacity"}))
    BurninDestinationSettings.add_member(:fallback_font, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleFallbackFont, location_name: 'FallbackFont', traits: {"smithy.api#documentation" => "Specify the font that you want the service to use for your burn in captions when your input captions specify a font that MediaConvert doesn't support. When you set Fallback font to best match, or leave blank, MediaConvert uses a supported font that most closely matches the font that your input captions specify. When there are multiple unsupported fonts in your input captions, MediaConvert matches each font with the supported font that matches best. When you explicitly choose a replacement font, MediaConvert uses that font to replace all unsupported fonts from your input.", "smithy.api#jsonName" => "fallbackFont"}))
    BurninDestinationSettings.add_member(:font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleFontColor, location_name: 'FontColor', traits: {"smithy.api#documentation" => "Specify the color of the burned-in captions text. Leave Font color blank and set Style passthrough to enabled to use the font color data from your input captions, if present.", "smithy.api#jsonName" => "fontColor"}))
    BurninDestinationSettings.add_member(:font_file_bold, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileBold', traits: {"smithy.api#documentation" => "Specify a bold TrueType font file to use when rendering your output captions. Enter an S3, HTTP, or HTTPS URL. When you do, you must also separately specify a regular, an italic, and a bold italic font file.", "smithy.api#jsonName" => "fontFileBold"}))
    BurninDestinationSettings.add_member(:font_file_bold_italic, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'FontFileBoldItalic', traits: {"smithy.api#documentation" => "Specify a bold italic TrueType font file to use when rendering your output captions.\nEnter an S3, HTTP, or HTTPS URL.\nWhen you do, you must also separately specify a regular, a bold, and an italic font file.", "smithy.api#jsonName" => "fontFileBoldItalic"}))
    BurninDestinationSettings.add_member(:font_file_italic, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileItalic', traits: {"smithy.api#documentation" => "Specify an italic TrueType font file to use when rendering your output captions. Enter an S3, HTTP, or HTTPS URL. When you do, you must also separately specify a regular, a bold, and a bold italic font file.", "smithy.api#jsonName" => "fontFileItalic"}))
    BurninDestinationSettings.add_member(:font_file_regular, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileRegular', traits: {"smithy.api#documentation" => "Specify a regular TrueType font file to use when rendering your output captions. Enter an S3, HTTP, or HTTPS URL. When you do, you must also separately specify a bold, an italic, and a bold italic font file.", "smithy.api#jsonName" => "fontFileRegular"}))
    BurninDestinationSettings.add_member(:font_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'FontOpacity', traits: {"smithy.api#documentation" => "Specify the opacity of the burned-in captions. 255 is opaque; 0 is transparent.", "smithy.api#jsonName" => "fontOpacity"}))
    BurninDestinationSettings.add_member(:font_resolution, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin96max600, location_name: 'FontResolution', traits: {"smithy.api#documentation" => "Specify the Font resolution in DPI (dots per inch).", "smithy.api#jsonName" => "fontResolution"}))
    BurninDestinationSettings.add_member(:font_script, Smithy::Schema::Shapes::ShapeRef.new(shape: FontScript, location_name: 'FontScript', traits: {"smithy.api#documentation" => "Set Font script to Automatically determined, or leave blank, to automatically determine the font script in your input captions. Otherwise, set to Simplified Chinese (HANS) or Traditional Chinese (HANT) if your input font script uses Simplified or Traditional Chinese.", "smithy.api#jsonName" => "fontScript"}))
    BurninDestinationSettings.add_member(:font_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max96, location_name: 'FontSize', traits: {"smithy.api#documentation" => "Specify the Font size in pixels. Must be a positive integer. Set to 0, or leave blank, for automatic font size.", "smithy.api#jsonName" => "fontSize"}))
    BurninDestinationSettings.add_member(:hex_font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin6max8pattern09afaf609afaf2, location_name: 'HexFontColor', traits: {"smithy.api#documentation" => "Ignore this setting unless your Font color is set to Hex. Enter either six or eight hexidecimal digits, representing red, green, and blue, with two optional extra digits for alpha. For example a value of 1122AABB is a red value of 0x11, a green value of 0x22, a blue value of 0xAA, and an alpha value of 0xBB.", "smithy.api#jsonName" => "hexFontColor"}))
    BurninDestinationSettings.add_member(:outline_color, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleOutlineColor, location_name: 'OutlineColor', traits: {"smithy.api#documentation" => "Specify font outline color. Leave Outline color blank and set Style passthrough to enabled to use the font outline color data from your input captions, if present.", "smithy.api#jsonName" => "outlineColor"}))
    BurninDestinationSettings.add_member(:outline_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max10, location_name: 'OutlineSize', traits: {"smithy.api#documentation" => "Specify the Outline size of the caption text, in pixels. Leave Outline size blank and set Style passthrough to enabled to use the outline size data from your input captions, if present.", "smithy.api#jsonName" => "outlineSize"}))
    BurninDestinationSettings.add_member(:remove_ruby_reserve_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: RemoveRubyReserveAttributes, location_name: 'RemoveRubyReserveAttributes', traits: {"smithy.api#documentation" => "Optionally remove any tts:rubyReserve attributes present in your input, that do   not have a tts:ruby attribute in the same element, from your output. Use if your vertical Japanese output captions have alignment issues. To remove ruby reserve attributes when present: Choose Enabled. To not remove any ruby reserve attributes: Keep the default value, Disabled.", "smithy.api#jsonName" => "removeRubyReserveAttributes"}))
    BurninDestinationSettings.add_member(:shadow_color, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleShadowColor, location_name: 'ShadowColor', traits: {"smithy.api#documentation" => "Specify the color of the shadow cast by the captions. Leave Shadow color blank and set Style passthrough to enabled to use the shadow color data from your input captions, if present.", "smithy.api#jsonName" => "shadowColor"}))
    BurninDestinationSettings.add_member(:shadow_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'ShadowOpacity', traits: {"smithy.api#documentation" => "Specify the opacity of the shadow. Enter a value from 0 to 255, where 0 is transparent and 255 is opaque. If Style passthrough is set to Enabled, leave Shadow opacity blank to pass through the shadow style information in your input captions to your output captions. If Style passthrough is set to disabled, leave blank to use a value of 0 and remove all shadows from your output captions.", "smithy.api#jsonName" => "shadowOpacity"}))
    BurninDestinationSettings.add_member(:shadow_x_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'ShadowXOffset', traits: {"smithy.api#documentation" => "Specify the horizontal offset of the shadow, relative to the captions in pixels. A value of -2 would result in a shadow offset 2 pixels to the left.", "smithy.api#jsonName" => "shadowXOffset"}))
    BurninDestinationSettings.add_member(:shadow_y_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'ShadowYOffset', traits: {"smithy.api#documentation" => "Specify the vertical offset of the shadow relative to the captions in pixels. A value of -2 would result in a shadow offset 2 pixels above the text. Leave Shadow y-offset blank and set Style passthrough to enabled to use the shadow y-offset data from your input captions, if present.", "smithy.api#jsonName" => "shadowYOffset"}))
    BurninDestinationSettings.add_member(:style_passthrough, Smithy::Schema::Shapes::ShapeRef.new(shape: BurnInSubtitleStylePassthrough, location_name: 'StylePassthrough', traits: {"smithy.api#documentation" => "To use the available style, color, and position information from your input captions: Set Style passthrough to Enabled. Note that MediaConvert uses default settings for any missing style or position information in your input captions To ignore the style and position information from your input captions and use default settings: Leave blank or keep the default value, Disabled. Default settings include white text with black outlining, bottom-center positioning, and automatic sizing. Whether you set Style passthrough to enabled or not, you can also choose to manually override any of the individual style and position settings. You can also override any fonts by manually specifying custom font files.", "smithy.api#jsonName" => "stylePassthrough"}))
    BurninDestinationSettings.add_member(:teletext_spacing, Smithy::Schema::Shapes::ShapeRef.new(shape: BurninSubtitleTeletextSpacing, location_name: 'TeletextSpacing', traits: {"smithy.api#documentation" => "Specify whether the text spacing in your captions is set by the captions grid, or varies depending on letter width. Choose fixed grid to conform to the spacing specified in the captions file more accurately. Choose proportional to make the text easier to read for closed captions.", "smithy.api#jsonName" => "teletextSpacing"}))
    BurninDestinationSettings.add_member(:x_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'XPosition', traits: {"smithy.api#documentation" => "Specify the horizontal position of the captions, relative to the left side of the output in pixels. A value of 10 would result in the captions starting 10 pixels from the left of the output. If no explicit x_position is provided, the horizontal caption position will be determined by the alignment parameter.", "smithy.api#jsonName" => "xPosition"}))
    BurninDestinationSettings.add_member(:y_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'YPosition', traits: {"smithy.api#documentation" => "Specify the vertical position of the captions, relative to the top of the output in pixels. A value of 10 would result in the captions starting 10 pixels from the top of the output. If no explicit y_position is provided, the caption will be positioned towards the bottom of the output.", "smithy.api#jsonName" => "yPosition"}))
