    ClipLimits.add_member(:maximum_rgb_tolerance, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin90max105, location_name: 'MaximumRGBTolerance', traits: {"smithy.api#documentation" => "Specify the Maximum RGB color sample range tolerance for your output. MediaConvert corrects any YUV values that, when converted to RGB, would be outside the upper tolerance that you specify. Enter an integer from 90 to 105 as an offset percentage to the maximum possible value. Leave blank to use the default value 100. When you specify a value for Maximum RGB tolerance, you must set Sample range conversion to Limited range clip.", "smithy.api#jsonName" => "maximumRGBTolerance"}))
    ClipLimits.add_member(:maximum_yuv, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin920max1023, location_name: 'MaximumYUV', traits: {"smithy.api#documentation" => "Specify the Maximum YUV color sample limit. MediaConvert conforms any pixels in your input above the value that you specify to typical limited range bounds. Enter an integer from 920 to 1023. Leave blank to use the default value 940. The value that you enter applies to 10-bit ranges. For 8-bit ranges, MediaConvert automatically scales this value down. When you specify a value for Maximum YUV, you must set Sample range conversion to Limited range clip.", "smithy.api#jsonName" => "maximumYUV"}))
    ClipLimits.add_member(:minimum_rgb_tolerance, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative5max10, location_name: 'MinimumRGBTolerance', traits: {"smithy.api#documentation" => "Specify the Minimum RGB color sample range tolerance for your output. MediaConvert corrects any YUV values that, when converted to RGB, would be outside the lower tolerance that you specify. Enter an integer from -5 to 10 as an offset percentage to the minimum possible value. Leave blank to use the default value 0. When you specify a value for Minimum RGB tolerance, you must set Sample range conversion to Limited range clip.", "smithy.api#jsonName" => "minimumRGBTolerance"}))
    ClipLimits.add_member(:minimum_yuv, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max128, location_name: 'MinimumYUV', traits: {"smithy.api#documentation" => "Specify the Minimum YUV color sample limit. MediaConvert conforms any pixels in your input below the value that you specify to typical limited range bounds. Enter an integer from 0 to 128. Leave blank to use the default value 64. The value that you enter applies to 10-bit ranges. For 8-bit ranges, MediaConvert automatically scales this value down. When you specify a value for Minumum YUV, you must set Sample range conversion to Limited range clip.", "smithy.api#jsonName" => "minimumYUV"}))
    ClipLimits.type = Types::ClipLimits
    CmafAdditionalManifest.add_member(:manifest_name_modifier, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1, location_name: 'ManifestNameModifier', traits: {"smithy.api#documentation" => "Specify a name modifier that the service adds to the name of this manifest to make it different from the file names of the other main manifests in the output group. For example, say that the default main manifest for your HLS group is film-name.m3u8. If you enter \"-no-premium\" for this setting, then the file name the service generates for this top-level manifest is film-name-no-premium.m3u8. For HLS output groups, specify a manifestNameModifier that is different from the nameModifier of the output. The service uses the output name modifier to create unique names for the individual variant manifests.", "smithy.api#jsonName" => "manifestNameModifier"}))
    CmafAdditionalManifest.add_member(:selected_outputs, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofStringmin1, location_name: 'SelectedOutputs', traits: {"smithy.api#documentation" => "Specify the outputs that you want this additional top-level manifest to reference.", "smithy.api#jsonName" => "selectedOutputs"}))
    CmafAdditionalManifest.type = Types::CmafAdditionalManifest
    CmafClientCache.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    CmafClientCache.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    CmafCodecSpecification.add_member(:rfc_6381, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RFC_6381', traits: {"smithy.api#enumValue" => "RFC_6381"}))
    CmafCodecSpecification.add_member(:rfc_4281, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RFC_4281', traits: {"smithy.api#enumValue" => "RFC_4281"}))
    CmafEncryptionSettings.add_member(:constant_initialization_vector, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin32max32pattern09afaf32, location_name: 'ConstantInitializationVector', traits: {"smithy.api#documentation" => "This is a 128-bit, 16-byte hex value represented by a 32-character text string. If this parameter is not set then the Initialization Vector will follow the segment number by default.", "smithy.api#jsonName" => "constantInitializationVector"}))
    CmafEncryptionSettings.add_member(:encryption_method, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafEncryptionType, location_name: 'EncryptionMethod', traits: {"smithy.api#documentation" => "Specify the encryption scheme that you want the service to use when encrypting your CMAF segments. Choose AES-CBC subsample or AES_CTR.", "smithy.api#jsonName" => "encryptionMethod"}))
    CmafEncryptionSettings.add_member(:initialization_vector_in_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafInitializationVectorInManifest, location_name: 'InitializationVectorInManifest', traits: {"smithy.api#documentation" => "When you use DRM with CMAF outputs, choose whether the service writes the 128-bit encryption initialization vector in the HLS and DASH manifests.", "smithy.api#jsonName" => "initializationVectorInManifest"}))
    CmafEncryptionSettings.add_member(:speke_key_provider, Smithy::Schema::Shapes::ShapeRef.new(shape: SpekeKeyProviderCmaf, location_name: 'SpekeKeyProvider', traits: {"smithy.api#documentation" => "If your output group type is CMAF, use these settings when doing DRM encryption with a SPEKE-compliant key provider. If your output group type is HLS, DASH, or Microsoft Smooth, use the SpekeKeyProvider settings instead.", "smithy.api#jsonName" => "spekeKeyProvider"}))
    CmafEncryptionSettings.add_member(:static_key_provider, Smithy::Schema::Shapes::ShapeRef.new(shape: StaticKeyProvider, location_name: 'StaticKeyProvider', traits: {"smithy.api#documentation" => "Use these settings to set up encryption with a static key provider.", "smithy.api#jsonName" => "staticKeyProvider"}))
    CmafEncryptionSettings.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafKeyProviderType, location_name: 'Type', traits: {"smithy.api#documentation" => "Specify whether your DRM encryption key is static or from a key provider that follows the SPEKE standard. For more information about SPEKE, see https://docs.aws.amazon.com/speke/latest/documentation/what-is-speke.html.", "smithy.api#jsonName" => "type"}))
    CmafEncryptionSettings.type = Types::CmafEncryptionSettings
    CmafEncryptionType.add_member(:sample_aes, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SAMPLE_AES', traits: {"smithy.api#enumValue" => "SAMPLE_AES"}))
    CmafEncryptionType.add_member(:aes_ctr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AES_CTR', traits: {"smithy.api#enumValue" => "AES_CTR"}))
    CmafGroupSettings.add_member(:additional_manifests, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofcmafadditionalmanifest, location_name: 'AdditionalManifests', traits: {"smithy.api#documentation" => "By default, the service creates one top-level .m3u8 HLS manifest and one top -level .mpd DASH manifest for each CMAF output group in your job. These default manifests reference every output in the output group. To create additional top-level manifests that reference a subset of the outputs in the output group, specify a list of them here. For each additional manifest that you specify, the service creates one HLS manifest and one DASH manifest.", "smithy.api#jsonName" => "additionalManifests"}))
    CmafGroupSettings.add_member(:base_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BaseUrl', traits: {"smithy.api#documentation" => "A partial URI prefix that will be put in the manifest file at the top level BaseURL element. Can be used if streams are delivered from a different URL than the manifest file.", "smithy.api#jsonName" => "baseUrl"}))
    CmafGroupSettings.add_member(:client_cache, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafClientCache, location_name: 'ClientCache', traits: {"smithy.api#documentation" => "Disable this setting only when your workflow requires the #EXT-X-ALLOW-CACHE:no tag. Otherwise, keep the default value Enabled and control caching in your video distribution set up. For example, use the Cache-Control http header.", "smithy.api#jsonName" => "clientCache"}))
    CmafGroupSettings.add_member(:codec_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafCodecSpecification, location_name: 'CodecSpecification', traits: {"smithy.api#documentation" => "Specification to use (RFC-6381 or the default RFC-4281) during m3u8 playlist generation.", "smithy.api#jsonName" => "codecSpecification"}))
    CmafGroupSettings.add_member(:dash_i_frame_trick_play_name_modifier, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max256, location_name: 'DashIFrameTrickPlayNameModifier', traits: {"smithy.api#documentation" => "Specify whether MediaConvert generates I-frame only video segments for DASH trick play, also known as trick mode. When specified, the I-frame only video segments are included within an additional AdaptationSet in your DASH output manifest. To generate I-frame only video segments: Enter a name as a text string, up to 256 character long. This name is appended to the end of this output group's base filename, that you specify as part of your destination URI, and used for the I-frame only video segment files. You may also include format identifiers. For more information, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/using-variables-in-your-job-settings.html#using-settings-variables-with-streaming-outputs To not generate I-frame only video segments: Leave blank.", "smithy.api#jsonName" => "dashIFrameTrickPlayNameModifier"}))
    CmafGroupSettings.add_member(:dash_manifest_style, Smithy::Schema::Shapes::ShapeRef.new(shape: DashManifestStyle, location_name: 'DashManifestStyle', traits: {"smithy.api#documentation" => "Specify how MediaConvert writes SegmentTimeline in your output DASH manifest. To write a SegmentTimeline in each video Representation: Keep the default value, Basic. To write a common SegmentTimeline in the video AdaptationSet: Choose Compact. Note that MediaConvert will still write a SegmentTimeline in any Representation that does not share a common timeline. To write a video AdaptationSet for each different output framerate, and a common SegmentTimeline in each AdaptationSet: Choose Distinct.", "smithy.api#jsonName" => "dashManifestStyle"}))
    CmafGroupSettings.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3, location_name: 'Destination', traits: {"smithy.api#documentation" => "Use Destination to specify the S3 output location and the output filename base. Destination accepts format identifiers. If you do not specify the base filename in the URI, the service will use the filename of the input file. If your job has multiple inputs, the service uses the filename of the first input file.", "smithy.api#jsonName" => "destination"}))
    CmafGroupSettings.add_member(:destination_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DestinationSettings, location_name: 'DestinationSettings', traits: {"smithy.api#documentation" => "Settings associated with the destination. Will vary based on the type of destination", "smithy.api#jsonName" => "destinationSettings"}))
    CmafGroupSettings.add_member(:encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafEncryptionSettings, location_name: 'Encryption', traits: {"smithy.api#documentation" => "DRM settings.", "smithy.api#jsonName" => "encryption"}))
    CmafGroupSettings.add_member(:fragment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'FragmentLength', traits: {"smithy.api#documentation" => "Specify the length, in whole seconds, of the mp4 fragments. When you don't specify a value, MediaConvert defaults to 2. Related setting: Use Fragment length control to specify whether the encoder enforces this value strictly.", "smithy.api#jsonName" => "fragmentLength"}))
    CmafGroupSettings.add_member(:image_based_trick_play, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafImageBasedTrickPlay, location_name: 'ImageBasedTrickPlay', traits: {"smithy.api#documentation" => "Specify whether MediaConvert generates images for trick play. Keep the default value, None, to not generate any images. Choose Thumbnail to generate tiled thumbnails. Choose Thumbnail and full frame to generate tiled thumbnails and full-resolution images of single frames. When you enable Write HLS manifest, MediaConvert creates a child manifest for each set of images that you generate and adds corresponding entries to the parent manifest. When you enable Write DASH manifest, MediaConvert adds an entry in the .mpd manifest for each set of images that you generate. A common application for these images is Roku trick mode. The thumbnails and full-frame images that MediaConvert creates with this feature are compatible with this Roku specification: https://developer.roku.com/docs/developer-program/media-playback/trick-mode/hls-and-dash.md", "smithy.api#jsonName" => "imageBasedTrickPlay"}))
    CmafGroupSettings.add_member(:image_based_trick_play_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafImageBasedTrickPlaySettings, location_name: 'ImageBasedTrickPlaySettings', traits: {"smithy.api#documentation" => "Tile and thumbnail settings applicable when imageBasedTrickPlay is ADVANCED", "smithy.api#jsonName" => "imageBasedTrickPlaySettings"}))
    CmafGroupSettings.add_member(:manifest_compression, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafManifestCompression, location_name: 'ManifestCompression', traits: {"smithy.api#documentation" => "When set to GZIP, compresses HLS playlist.", "smithy.api#jsonName" => "manifestCompression"}))
    CmafGroupSettings.add_member(:manifest_duration_format, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafManifestDurationFormat, location_name: 'ManifestDurationFormat', traits: {"smithy.api#documentation" => "Indicates whether the output manifest should use floating point values for segment duration.", "smithy.api#jsonName" => "manifestDurationFormat"}))
    CmafGroupSettings.add_member(:min_buffer_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'MinBufferTime', traits: {"smithy.api#documentation" => "Minimum time of initially buffered media that is needed to ensure smooth playout.", "smithy.api#jsonName" => "minBufferTime"}))
    CmafGroupSettings.add_member(:min_final_segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0max2147483647, location_name: 'MinFinalSegmentLength', traits: {"smithy.api#documentation" => "Keep this setting at the default value of 0, unless you are troubleshooting a problem with how devices play back the end of your video asset. If you know that player devices are hanging on the final segment of your video because the length of your final segment is too short, use this setting to specify a minimum final segment length, in seconds. Choose a value that is greater than or equal to 1 and less than your segment length. When you specify a value for this setting, the encoder will combine any final segment that is shorter than the length that you specify with the previous segment. For example, your segment length is 3 seconds and your final segment is .5 seconds without a minimum final segment length; when you set the minimum final segment length to 1, your final segment is 3.5 seconds.", "smithy.api#jsonName" => "minFinalSegmentLength"}))
    CmafGroupSettings.add_member(:mpd_manifest_bandwidth_type, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafMpdManifestBandwidthType, location_name: 'MpdManifestBandwidthType', traits: {"smithy.api#documentation" => "Specify how the value for bandwidth is determined for each video Representation in your output MPD manifest. We recommend that you choose a MPD manifest bandwidth type that is compatible with your downstream player configuration. Max: Use the same value that you specify for Max bitrate in the video output, in bits per second. Average: Use the calculated average bitrate of the encoded video output, in bits per second.", "smithy.api#jsonName" => "mpdManifestBandwidthType"}))
    CmafGroupSettings.add_member(:mpd_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafMpdProfile, location_name: 'MpdProfile', traits: {"smithy.api#documentation" => "Specify whether your DASH profile is on-demand or main. When you choose Main profile, the service signals urn:mpeg:dash:profile:isoff-main:2011 in your .mpd DASH manifest. When you choose On-demand, the service signals urn:mpeg:dash:profile:isoff-on-demand:2011 in your .mpd. When you choose On-demand, you must also set the output group setting Segment control to Single file.", "smithy.api#jsonName" => "mpdProfile"}))
    CmafGroupSettings.add_member(:pts_offset_handling_for_b_frames, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafPtsOffsetHandlingForBFrames, location_name: 'PtsOffsetHandlingForBFrames', traits: {"smithy.api#documentation" => "Use this setting only when your output video stream has B-frames, which causes the initial presentation time stamp (PTS) to be offset from the initial decode time stamp (DTS). Specify how MediaConvert handles PTS when writing time stamps in output DASH manifests. Choose Match initial PTS when you want MediaConvert to use the initial PTS as the first time stamp in the manifest. Choose Zero-based to have MediaConvert ignore the initial PTS in the video stream and instead write the initial time stamp as zero in the manifest. For outputs that don't have B-frames, the time stamps in your DASH manifests start at zero regardless of your choice here.", "smithy.api#jsonName" => "ptsOffsetHandlingForBFrames"}))
    CmafGroupSettings.add_member(:segment_control, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafSegmentControl, location_name: 'SegmentControl', traits: {"smithy.api#documentation" => "When set to SINGLE_FILE, a single output file is generated, which is internally segmented using the Fragment Length and Segment Length. When set to SEGMENTED_FILES, separate segment files will be created.", "smithy.api#jsonName" => "segmentControl"}))
    CmafGroupSettings.add_member(:segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'SegmentLength', traits: {"smithy.api#documentation" => "Specify the length, in whole seconds, of each segment. When you don't specify a value, MediaConvert defaults to 10. Related settings: Use Segment length control to specify whether the encoder enforces this value strictly. Use Segment control to specify whether MediaConvert creates separate segment files or one content file that has metadata to mark the segment boundaries.", "smithy.api#jsonName" => "segmentLength"}))
    CmafGroupSettings.add_member(:segment_length_control, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafSegmentLengthControl, location_name: 'SegmentLengthControl', traits: {"smithy.api#documentation" => "Specify how you want MediaConvert to determine segment lengths in this output group. To use the exact value that you specify under Segment length: Choose Exact. Note that this might result in additional I-frames in the output GOP. To create segment lengths that are a multiple of the GOP: Choose Multiple of GOP. MediaConvert will round up the segment lengths to match the next GOP boundary. To have MediaConvert automatically determine a segment duration that is a multiple of both the audio packets and the frame rates: Choose Match. When you do, also specify a target segment duration under Segment length. This is useful for some ad-insertion or segment replacement workflows. Note that Match has the following requirements: - Output containers: Include at least one video output and at least one audio output. Audio-only outputs are not supported. - Output frame rate: Follow source is not supported. - Multiple output frame rates: When you specify multiple outputs, we recommend they share a similar frame rate (as in X/3, X/2, X, or 2X). For example: 5, 15, 30 and 60. Or: 25 and 50. (Outputs must share an integer multiple.) - Output audio codec: Specify Advanced Audio Coding (AAC). - Output sample rate: Choose 48kHz.", "smithy.api#jsonName" => "segmentLengthControl"}))
    CmafGroupSettings.add_member(:stream_inf_resolution, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafStreamInfResolution, location_name: 'StreamInfResolution', traits: {"smithy.api#documentation" => "Include or exclude RESOLUTION attribute for video in EXT-X-STREAM-INF tag of variant manifest.", "smithy.api#jsonName" => "streamInfResolution"}))
    CmafGroupSettings.add_member(:target_duration_compatibility_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafTargetDurationCompatibilityMode, location_name: 'TargetDurationCompatibilityMode', traits: {"smithy.api#documentation" => "When set to LEGACY, the segment target duration is always rounded up to the nearest integer value above its current value in seconds. When set to SPEC\\\\_COMPLIANT, the segment target duration is rounded up to the nearest integer value if fraction seconds are greater than or equal to 0.5 (>= 0.5) and rounded down if less than 0.5 (< 0.5). You may need to use LEGACY if your client needs to ensure that the target duration is always longer than the actual duration of the segment. Some older players may experience interrupted playback when the actual duration of a track in a segment is longer than the target duration.", "smithy.api#jsonName" => "targetDurationCompatibilityMode"}))
    CmafGroupSettings.add_member(:video_composition_offsets, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafVideoCompositionOffsets, location_name: 'VideoCompositionOffsets', traits: {"smithy.api#documentation" => "Specify the video sample composition time offset mode in the output fMP4 TRUN box. For wider player compatibility, set Video composition offsets to Unsigned or leave blank. The earliest presentation time may be greater than zero, and sample composition time offsets will increment using unsigned integers. For strict fMP4 video and audio timing, set Video composition offsets to Signed. The earliest presentation time will be equal to zero, and sample composition time offsets will increment using signed integers.", "smithy.api#jsonName" => "videoCompositionOffsets"}))
    CmafGroupSettings.add_member(:write_dash_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafWriteDASHManifest, location_name: 'WriteDashManifest', traits: {"smithy.api#documentation" => "When set to ENABLED, a DASH MPD manifest will be generated for this output.", "smithy.api#jsonName" => "writeDashManifest"}))
    CmafGroupSettings.add_member(:write_hls_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafWriteHLSManifest, location_name: 'WriteHlsManifest', traits: {"smithy.api#documentation" => "When set to ENABLED, an Apple HLS manifest will be generated for this output.", "smithy.api#jsonName" => "writeHlsManifest"}))
    CmafGroupSettings.add_member(:write_segment_timeline_in_representation, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafWriteSegmentTimelineInRepresentation, location_name: 'WriteSegmentTimelineInRepresentation', traits: {"smithy.api#documentation" => "When you enable Precise segment duration in DASH manifests, your DASH manifest shows precise segment durations. The segment duration information appears inside the SegmentTimeline element, inside SegmentTemplate at the Representation level. When this feature isn't enabled, the segment durations in your DASH manifest are approximate. The segment duration information appears in the duration attribute of the SegmentTemplate element.", "smithy.api#jsonName" => "writeSegmentTimelineInRepresentation"}))
    CmafGroupSettings.type = Types::CmafGroupSettings
    CmafImageBasedTrickPlay.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
    CmafImageBasedTrickPlay.add_member(:thumbnail, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'THUMBNAIL', traits: {"smithy.api#enumValue" => "THUMBNAIL"}))
    CmafImageBasedTrickPlay.add_member(:thumbnail_and_fullframe, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'THUMBNAIL_AND_FULLFRAME', traits: {"smithy.api#enumValue" => "THUMBNAIL_AND_FULLFRAME"}))
    CmafImageBasedTrickPlay.add_member(:advanced, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ADVANCED', traits: {"smithy.api#enumValue" => "ADVANCED"}))
    CmafImageBasedTrickPlaySettings.add_member(:interval_cadence, Smithy::Schema::Shapes::ShapeRef.new(shape: CmafIntervalCadence, location_name: 'IntervalCadence', traits: {"smithy.api#documentation" => "The cadence MediaConvert follows for generating thumbnails. If set to FOLLOW_IFRAME, MediaConvert generates thumbnails for each IDR frame in the output (matching the GOP cadence). If set to FOLLOW_CUSTOM, MediaConvert generates thumbnails according to the interval you specify in thumbnailInterval.", "smithy.api#jsonName" => "intervalCadence"}))
    CmafImageBasedTrickPlaySettings.add_member(:thumbnail_height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin2max4096, location_name: 'ThumbnailHeight', traits: {"smithy.api#documentation" => "Height of each thumbnail within each tile image, in pixels. Leave blank to maintain aspect ratio with thumbnail width. If following the aspect ratio would lead to a total tile height greater than 4096, then the job will be rejected. Must be divisible by 2.", "smithy.api#jsonName" => "thumbnailHeight"}))
    CmafImageBasedTrickPlaySettings.add_member(:thumbnail_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0max2147483647, location_name: 'ThumbnailInterval', traits: {"smithy.api#documentation" => "Enter the interval, in seconds, that MediaConvert uses to generate thumbnails. If the interval you enter doesn't align with the output frame rate, MediaConvert automatically rounds the interval to align with the output frame rate. For example, if the output frame rate is 29.97 frames per second and you enter 5, MediaConvert uses a 150 frame interval to generate thumbnails.", "smithy.api#jsonName" => "thumbnailInterval"}))
    CmafImageBasedTrickPlaySettings.add_member(:thumbnail_width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin8max4096, location_name: 'ThumbnailWidth', traits: {"smithy.api#documentation" => "Width of each thumbnail within each tile image, in pixels. Default is 312. Must be divisible by 8.", "smithy.api#jsonName" => "thumbnailWidth"}))
    CmafImageBasedTrickPlaySettings.add_member(:tile_height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2048, location_name: 'TileHeight', traits: {"smithy.api#documentation" => "Number of thumbnails in each column of a tile image. Set a value between 2 and 2048. Must be divisible by 2.", "smithy.api#jsonName" => "tileHeight"}))
    CmafImageBasedTrickPlaySettings.add_member(:tile_width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max512, location_name: 'TileWidth', traits: {"smithy.api#documentation" => "Number of thumbnails in each row of a tile image. Set a value between 1 and 512.", "smithy.api#jsonName" => "tileWidth"}))
    CmafImageBasedTrickPlaySettings.type = Types::CmafImageBasedTrickPlaySettings
    CmafInitializationVectorInManifest.add_member(:include, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INCLUDE', traits: {"smithy.api#enumValue" => "INCLUDE"}))
    CmafInitializationVectorInManifest.add_member(:exclude, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EXCLUDE', traits: {"smithy.api#enumValue" => "EXCLUDE"}))
