    ColorConversion3DLUTSetting.add_member(:file_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin14patterns3cubecubehttpscubecube, location_name: 'FileInput', traits: {"smithy.api#documentation" => "Specify the input file S3, HTTP, or HTTPS URL for your 3D LUT .cube file. Note that MediaConvert accepts 3D LUT files up to 8MB in size.", "smithy.api#jsonName" => "fileInput"}))
    ColorConversion3DLUTSetting.add_member(:input_color_space, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorSpace, location_name: 'InputColorSpace', traits: {"smithy.api#documentation" => "Specify which inputs use this 3D LUT, according to their color space.", "smithy.api#jsonName" => "inputColorSpace"}))
    ColorConversion3DLUTSetting.add_member(:input_mastering_luminance, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'InputMasteringLuminance', traits: {"smithy.api#documentation" => "Specify which inputs use this 3D LUT, according to their luminance. To apply this 3D LUT to HDR10 or P3D65 (HDR) inputs with a specific mastering luminance: Enter an integer from 0 to 2147483647, corresponding to the input's Maximum luminance value. To apply this 3D LUT to any input regardless of its luminance: Leave blank, or enter 0.", "smithy.api#jsonName" => "inputMasteringLuminance"}))
    ColorConversion3DLUTSetting.add_member(:output_color_space, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorSpace, location_name: 'OutputColorSpace', traits: {"smithy.api#documentation" => "Specify which outputs use this 3D LUT, according to their color space.", "smithy.api#jsonName" => "outputColorSpace"}))
    ColorConversion3DLUTSetting.add_member(:output_mastering_luminance, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'OutputMasteringLuminance', traits: {"smithy.api#documentation" => "Specify which outputs use this 3D LUT, according to their luminance. To apply this 3D LUT to HDR10 or P3D65 (HDR) outputs with a specific luminance: Enter an integer from 0 to 2147483647, corresponding to the output's luminance. To apply this 3D LUT to any output regardless of its luminance: Leave blank, or enter 0.", "smithy.api#jsonName" => "outputMasteringLuminance"}))
