    ContainerSettings.add_member(:container, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerType, location_name: 'Container', traits: {"smithy.api#documentation" => "Container for this output. Some containers require a container settings object. If not specified, the default object will be created.", "smithy.api#jsonName" => "container"}))
    ContainerSettings.add_member(:f4v_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: F4vSettings, location_name: 'F4vSettings', traits: {"smithy.api#documentation" => "Settings for F4v container", "smithy.api#jsonName" => "f4vSettings"}))
    ContainerSettings.add_member(:m2ts_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsSettings, location_name: 'M2tsSettings', traits: {"smithy.api#documentation" => "MPEG-2 TS container settings. These apply to outputs in a File output group when the output's container is MPEG-2 Transport Stream (M2TS). In these assets, data is organized by the program map table (PMT). Each transport stream program contains subsets of data, including audio, video, and metadata. Each of these subsets of data has a numerical label called a packet identifier (PID). Each transport stream program corresponds to one MediaConvert output. The PMT lists the types of data in a program along with their PID. Downstream systems and players use the program map table to look up the PID for each type of data it accesses and then uses the PIDs to locate specific data within the asset.", "smithy.api#jsonName" => "m2tsSettings"}))
    ContainerSettings.add_member(:m3u8_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: M3u8Settings, location_name: 'M3u8Settings', traits: {"smithy.api#documentation" => "These settings relate to the MPEG-2 transport stream (MPEG2-TS) container for the MPEG2-TS segments in your HLS outputs.", "smithy.api#jsonName" => "m3u8Settings"}))
    ContainerSettings.add_member(:mov_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: MovSettings, location_name: 'MovSettings', traits: {"smithy.api#documentation" => "These settings relate to your QuickTime MOV output container.", "smithy.api#jsonName" => "movSettings"}))
    ContainerSettings.add_member(:mp4_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Mp4Settings, location_name: 'Mp4Settings', traits: {"smithy.api#documentation" => "These settings relate to your MP4 output container. You can create audio only outputs with this container. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/supported-codecs-containers-audio-only.html#output-codecs-and-containers-supported-for-audio-only.", "smithy.api#jsonName" => "mp4Settings"}))
    ContainerSettings.add_member(:mpd_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdSettings, location_name: 'MpdSettings', traits: {"smithy.api#documentation" => "These settings relate to the fragmented MP4 container for the segments in your DASH outputs.", "smithy.api#jsonName" => "mpdSettings"}))
