    CreateJobRequest.add_member(:job_template, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'JobTemplate', traits: {"smithy.api#documentation" => "Optional. When you create a job, you can either specify a job template or specify the transcoding settings individually.", "smithy.api#jsonName" => "jobTemplate"}))
    CreateJobRequest.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative50max50, location_name: 'Priority', traits: {"smithy.api#documentation" => "Optional. Specify the relative priority for this job. In any given queue, the service begins processing the job with the highest value first. When more than one job has the same priority, the service begins processing the job that you submitted first. If you don't specify a priority, the service uses the default value 0.", "smithy.api#jsonName" => "priority"}))
    CreateJobRequest.add_member(:queue, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Queue', traits: {"smithy.api#documentation" => "Optional. When you create a job, you can specify a queue to send it to. If you don't specify, the job will go to the default queue. For more about queues, see the User Guide topic at https://docs.aws.amazon.com/mediaconvert/latest/ug/what-is.html.", "smithy.api#jsonName" => "queue"}))
    CreateJobRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Role', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "Required. The IAM role you use for creating this job. For details about permissions, see the User Guide topic at the User Guide at https://docs.aws.amazon.com/mediaconvert/latest/ug/iam-role.html.", "smithy.api#jsonName" => "role", "smithy.api#required" => {}}))
    CreateJobRequest.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: JobSettings, location_name: 'Settings', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "JobSettings contains all the transcode settings for a job.", "smithy.api#jsonName" => "settings", "smithy.api#required" => {}}))
    CreateJobRequest.add_member(:simulate_reserved_queue, Smithy::Schema::Shapes::ShapeRef.new(shape: SimulateReservedQueue, location_name: 'SimulateReservedQueue', traits: {"smithy.api#documentation" => "Optional. Enable this setting when you run a test job to estimate how many reserved transcoding slots (RTS) you need. When this is enabled, MediaConvert runs your job from an on-demand queue with similar performance to what you will see with one RTS in a reserved queue. This setting is disabled by default.", "smithy.api#jsonName" => "simulateReservedQueue"}))
    CreateJobRequest.add_member(:status_update_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusUpdateInterval, location_name: 'StatusUpdateInterval', traits: {"smithy.api#documentation" => "Optional. Specify how often MediaConvert sends STATUS_UPDATE events to Amazon CloudWatch Events. Set the interval, in seconds, between status updates. MediaConvert sends an update at this interval from the time the service begins processing your job to the time it completes the transcode or encounters an error.", "smithy.api#jsonName" => "statusUpdateInterval"}))
    CreateJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: MapofString, location_name: 'Tags', traits: {"smithy.api#documentation" => "Optional. The tags that you want to add to the resource. You can tag resources with a key-value pair or with only a key.  Use standard AWS tags on your job for automatic integration with AWS services and for custom integrations and workflows.", "smithy.api#jsonName" => "tags"}))
    CreateJobRequest.add_member(:user_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: MapofString, location_name: 'UserMetadata', traits: {"smithy.api#documentation" => "Optional. User-defined metadata that you want to associate with an MediaConvert job. You specify metadata in key/value pairs.  Use only for existing integrations or workflows that rely on job metadata tags. Otherwise, we recommend that you use standard AWS tags.", "smithy.api#jsonName" => "userMetadata"}))
