    CreateQueueRequest.add_member(:concurrent_jobs, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ConcurrentJobs', traits: {"smithy.api#documentation" => "Specify the maximum number of jobs your queue can process concurrently. For on-demand queues, the value you enter is constrained by your service quotas for Maximum concurrent jobs, per on-demand queue and Maximum concurrent jobs, per account. For reserved queues, specify the number of jobs you can process concurrently in your reservation plan instead.", "smithy.api#jsonName" => "concurrentJobs"}))
    CreateQueueRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "Optional. A description of the queue that you are creating.", "smithy.api#jsonName" => "description"}))
    CreateQueueRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "The name of the queue that you are creating.", "smithy.api#jsonName" => "name", "smithy.api#required" => {}}))
    CreateQueueRequest.add_member(:pricing_plan, Smithy::Schema::Shapes::ShapeRef.new(shape: PricingPlan, location_name: 'PricingPlan', traits: {"smithy.api#documentation" => "Specifies whether the pricing plan for the queue is on-demand or reserved. For on-demand, you pay per minute, billed in increments of .01 minute. For reserved, you pay for the transcoding capacity of the entire queue, regardless of how much or how little you use it. Reserved pricing requires a 12-month commitment. When you use the API to create a queue, the default is on-demand.", "smithy.api#jsonName" => "pricingPlan"}))
    CreateQueueRequest.add_member(:reservation_plan_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ReservationPlanSettings, location_name: 'ReservationPlanSettings', traits: {"smithy.api#documentation" => "Details about the pricing plan for your reserved queue. Required for reserved queues and not applicable to on-demand queues.", "smithy.api#jsonName" => "reservationPlanSettings"}))
    CreateQueueRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "Initial state of the queue. If you create a paused queue, then jobs in that queue won't begin.", "smithy.api#jsonName" => "status"}))
    CreateQueueRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: MapofString, location_name: 'Tags', traits: {"smithy.api#documentation" => "The tags that you want to add to the resource. You can tag resources with a key-value pair or with only a key.", "smithy.api#jsonName" => "tags"}))
    CreateQueueRequest.type = Types::CreateQueueRequest
    CreateQueueResponse.add_member(:queue, Smithy::Schema::Shapes::ShapeRef.new(shape: Queue, location_name: 'Queue', traits: {"smithy.api#documentation" => "You can use queues to manage the resources that are available to your AWS account for running multiple transcoding jobs at the same time. If you don't specify a queue, the service sends all jobs through the default queue. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/working-with-queues.html.", "smithy.api#jsonName" => "queue"}))
    CreateQueueResponse.type = Types::CreateQueueResponse
    DashAdditionalManifest.add_member(:manifest_name_modifier, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1, location_name: 'ManifestNameModifier', traits: {"smithy.api#documentation" => "Specify a name modifier that the service adds to the name of this manifest to make it different from the file names of the other main manifests in the output group. For example, say that the default main manifest for your DASH group is film-name.mpd. If you enter \"-no-premium\" for this setting, then the file name the service generates for this top-level manifest is film-name-no-premium.mpd.", "smithy.api#jsonName" => "manifestNameModifier"}))
    DashAdditionalManifest.add_member(:selected_outputs, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofStringmin1, location_name: 'SelectedOutputs', traits: {"smithy.api#documentation" => "Specify the outputs that you want this additional top-level manifest to reference.", "smithy.api#jsonName" => "selectedOutputs"}))
    DashAdditionalManifest.type = Types::DashAdditionalManifest
    DashIsoEncryptionSettings.add_member(:playback_device_compatibility, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoPlaybackDeviceCompatibility, location_name: 'PlaybackDeviceCompatibility', traits: {"smithy.api#documentation" => "This setting can improve the compatibility of your output with video players on obsolete devices. It applies only to DASH H.264 outputs with DRM encryption. Choose Unencrypted SEI only to correct problems with playback on older devices. Otherwise, keep the default setting CENC v1. If you choose Unencrypted SEI, for that output, the service will exclude the access unit delimiter and will leave the SEI NAL units unencrypted.", "smithy.api#jsonName" => "playbackDeviceCompatibility"}))
    DashIsoEncryptionSettings.add_member(:speke_key_provider, Smithy::Schema::Shapes::ShapeRef.new(shape: SpekeKeyProvider, location_name: 'SpekeKeyProvider', traits: {"smithy.api#documentation" => "If your output group type is HLS, DASH, or Microsoft Smooth, use these settings when doing DRM encryption with a SPEKE-compliant key provider. If your output group type is CMAF, use the SpekeKeyProviderCmaf settings instead.", "smithy.api#jsonName" => "spekeKeyProvider"}))
    DashIsoEncryptionSettings.type = Types::DashIsoEncryptionSettings
    DashIsoGroupAudioChannelConfigSchemeIdUri.add_member(:mpeg_channel_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MPEG_CHANNEL_CONFIGURATION', traits: {"smithy.api#enumValue" => "MPEG_CHANNEL_CONFIGURATION"}))
    DashIsoGroupAudioChannelConfigSchemeIdUri.add_member(:dolby_channel_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DOLBY_CHANNEL_CONFIGURATION', traits: {"smithy.api#enumValue" => "DOLBY_CHANNEL_CONFIGURATION"}))
    DashIsoGroupSettings.add_member(:additional_manifests, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofdashadditionalmanifest, location_name: 'AdditionalManifests', traits: {"smithy.api#documentation" => "By default, the service creates one .mpd DASH manifest for each DASH ISO output group in your job. This default manifest references every output in the output group. To create additional DASH manifests that reference a subset of the outputs in the output group, specify a list of them here.", "smithy.api#jsonName" => "additionalManifests"}))
    DashIsoGroupSettings.add_member(:audio_channel_config_scheme_id_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoGroupAudioChannelConfigSchemeIdUri, location_name: 'AudioChannelConfigSchemeIdUri', traits: {"smithy.api#documentation" => "Use this setting only when your audio codec is a Dolby one (AC3, EAC3, or Atmos) and your downstream workflow requires that your DASH manifest use the Dolby channel configuration tag, rather than the MPEG one. For example, you might need to use this to make dynamic ad insertion work. Specify which audio channel configuration scheme ID URI MediaConvert writes in your DASH manifest. Keep the default value, MPEG channel configuration, to have MediaConvert write this: urn:mpeg:mpegB:cicp:ChannelConfiguration. Choose Dolby channel configuration to have MediaConvert write this instead: tag:dolby.com,2014:dash:audio_channel_configuration:2011.", "smithy.api#jsonName" => "audioChannelConfigSchemeIdUri"}))
    DashIsoGroupSettings.add_member(:base_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BaseUrl', traits: {"smithy.api#documentation" => "A partial URI prefix that will be put in the manifest (.mpd) file at the top level BaseURL element. Can be used if streams are delivered from a different URL than the manifest file.", "smithy.api#jsonName" => "baseUrl"}))
    DashIsoGroupSettings.add_member(:dash_i_frame_trick_play_name_modifier, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max256, location_name: 'DashIFrameTrickPlayNameModifier', traits: {"smithy.api#documentation" => "Specify whether MediaConvert generates I-frame only video segments for DASH trick play, also known as trick mode. When specified, the I-frame only video segments are included within an additional AdaptationSet in your DASH output manifest. To generate I-frame only video segments: Enter a name as a text string, up to 256 character long. This name is appended to the end of this output group's base filename, that you specify as part of your destination URI, and used for the I-frame only video segment files. You may also include format identifiers. For more information, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/using-variables-in-your-job-settings.html#using-settings-variables-with-streaming-outputs To not generate I-frame only video segments: Leave blank.", "smithy.api#jsonName" => "dashIFrameTrickPlayNameModifier"}))
    DashIsoGroupSettings.add_member(:dash_manifest_style, Smithy::Schema::Shapes::ShapeRef.new(shape: DashManifestStyle, location_name: 'DashManifestStyle', traits: {"smithy.api#documentation" => "Specify how MediaConvert writes SegmentTimeline in your output DASH manifest. To write a SegmentTimeline in each video Representation: Keep the default value, Basic. To write a common SegmentTimeline in the video AdaptationSet: Choose Compact. Note that MediaConvert will still write a SegmentTimeline in any Representation that does not share a common timeline. To write a video AdaptationSet for each different output framerate, and a common SegmentTimeline in each AdaptationSet: Choose Distinct.", "smithy.api#jsonName" => "dashManifestStyle"}))
    DashIsoGroupSettings.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3, location_name: 'Destination', traits: {"smithy.api#documentation" => "Use Destination to specify the S3 output location and the output filename base. Destination accepts format identifiers. If you do not specify the base filename in the URI, the service will use the filename of the input file. If your job has multiple inputs, the service uses the filename of the first input file.", "smithy.api#jsonName" => "destination"}))
    DashIsoGroupSettings.add_member(:destination_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DestinationSettings, location_name: 'DestinationSettings', traits: {"smithy.api#documentation" => "Settings associated with the destination. Will vary based on the type of destination", "smithy.api#jsonName" => "destinationSettings"}))
    DashIsoGroupSettings.add_member(:encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoEncryptionSettings, location_name: 'Encryption', traits: {"smithy.api#documentation" => "DRM settings.", "smithy.api#jsonName" => "encryption"}))
    DashIsoGroupSettings.add_member(:fragment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'FragmentLength', traits: {"smithy.api#documentation" => "Length of fragments to generate (in seconds). Fragment length must be compatible with GOP size and Framerate. Note that fragments will end on the next keyframe after this number of seconds, so actual fragment length may be longer. When Emit Single File is checked, the fragmentation is internal to a single output file and it does not cause the creation of many output files as in other output types.", "smithy.api#jsonName" => "fragmentLength"}))
    DashIsoGroupSettings.add_member(:hbbtv_compliance, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoHbbtvCompliance, location_name: 'HbbtvCompliance', traits: {"smithy.api#documentation" => "Supports HbbTV specification as indicated", "smithy.api#jsonName" => "hbbtvCompliance"}))
    DashIsoGroupSettings.add_member(:image_based_trick_play, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoImageBasedTrickPlay, location_name: 'ImageBasedTrickPlay', traits: {"smithy.api#documentation" => "Specify whether MediaConvert generates images for trick play. Keep the default value, None, to not generate any images. Choose Thumbnail to generate tiled thumbnails. Choose Thumbnail and full frame to generate tiled thumbnails and full-resolution images of single frames. MediaConvert adds an entry in the .mpd manifest for each set of images that you generate. A common application for these images is Roku trick mode. The thumbnails and full-frame images that MediaConvert creates with this feature are compatible with this Roku specification: https://developer.roku.com/docs/developer-program/media-playback/trick-mode/hls-and-dash.md", "smithy.api#jsonName" => "imageBasedTrickPlay"}))
    DashIsoGroupSettings.add_member(:image_based_trick_play_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoImageBasedTrickPlaySettings, location_name: 'ImageBasedTrickPlaySettings', traits: {"smithy.api#documentation" => "Tile and thumbnail settings applicable when imageBasedTrickPlay is ADVANCED", "smithy.api#jsonName" => "imageBasedTrickPlaySettings"}))
    DashIsoGroupSettings.add_member(:min_buffer_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'MinBufferTime', traits: {"smithy.api#documentation" => "Minimum time of initially buffered media that is needed to ensure smooth playout.", "smithy.api#jsonName" => "minBufferTime"}))
    DashIsoGroupSettings.add_member(:min_final_segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0max2147483647, location_name: 'MinFinalSegmentLength', traits: {"smithy.api#documentation" => "Keep this setting at the default value of 0, unless you are troubleshooting a problem with how devices play back the end of your video asset. If you know that player devices are hanging on the final segment of your video because the length of your final segment is too short, use this setting to specify a minimum final segment length, in seconds. Choose a value that is greater than or equal to 1 and less than your segment length. When you specify a value for this setting, the encoder will combine any final segment that is shorter than the length that you specify with the previous segment. For example, your segment length is 3 seconds and your final segment is .5 seconds without a minimum final segment length; when you set the minimum final segment length to 1, your final segment is 3.5 seconds.", "smithy.api#jsonName" => "minFinalSegmentLength"}))
    DashIsoGroupSettings.add_member(:mpd_manifest_bandwidth_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoMpdManifestBandwidthType, location_name: 'MpdManifestBandwidthType', traits: {"smithy.api#documentation" => "Specify how the value for bandwidth is determined for each video Representation in your output MPD manifest. We recommend that you choose a MPD manifest bandwidth type that is compatible with your downstream player configuration. Max: Use the same value that you specify for Max bitrate in the video output, in bits per second. Average: Use the calculated average bitrate of the encoded video output, in bits per second.", "smithy.api#jsonName" => "mpdManifestBandwidthType"}))
    DashIsoGroupSettings.add_member(:mpd_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoMpdProfile, location_name: 'MpdProfile', traits: {"smithy.api#documentation" => "Specify whether your DASH profile is on-demand or main. When you choose Main profile, the service signals urn:mpeg:dash:profile:isoff-main:2011 in your .mpd DASH manifest. When you choose On-demand, the service signals urn:mpeg:dash:profile:isoff-on-demand:2011 in your .mpd. When you choose On-demand, you must also set the output group setting Segment control to Single file.", "smithy.api#jsonName" => "mpdProfile"}))
    DashIsoGroupSettings.add_member(:pts_offset_handling_for_b_frames, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoPtsOffsetHandlingForBFrames, location_name: 'PtsOffsetHandlingForBFrames', traits: {"smithy.api#documentation" => "Use this setting only when your output video stream has B-frames, which causes the initial presentation time stamp (PTS) to be offset from the initial decode time stamp (DTS). Specify how MediaConvert handles PTS when writing time stamps in output DASH manifests. Choose Match initial PTS when you want MediaConvert to use the initial PTS as the first time stamp in the manifest. Choose Zero-based to have MediaConvert ignore the initial PTS in the video stream and instead write the initial time stamp as zero in the manifest. For outputs that don't have B-frames, the time stamps in your DASH manifests start at zero regardless of your choice here.", "smithy.api#jsonName" => "ptsOffsetHandlingForBFrames"}))
    DashIsoGroupSettings.add_member(:segment_control, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoSegmentControl, location_name: 'SegmentControl', traits: {"smithy.api#documentation" => "When set to SINGLE_FILE, a single output file is generated, which is internally segmented using the Fragment Length and Segment Length. When set to SEGMENTED_FILES, separate segment files will be created.", "smithy.api#jsonName" => "segmentControl"}))
    DashIsoGroupSettings.add_member(:segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'SegmentLength', traits: {"smithy.api#documentation" => "Specify the length, in whole seconds, of each segment. When you don't specify a value, MediaConvert defaults to 30. Related settings: Use Segment length control to specify whether the encoder enforces this value strictly. Use Segment control to specify whether MediaConvert creates separate segment files or one content file that has metadata to mark the segment boundaries.", "smithy.api#jsonName" => "segmentLength"}))
    DashIsoGroupSettings.add_member(:segment_length_control, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoSegmentLengthControl, location_name: 'SegmentLengthControl', traits: {"smithy.api#documentation" => "Specify how you want MediaConvert to determine segment lengths in this output group. To use the exact value that you specify under Segment length: Choose Exact. Note that this might result in additional I-frames in the output GOP. To create segment lengths that are a multiple of the GOP: Choose Multiple of GOP. MediaConvert will round up the segment lengths to match the next GOP boundary. To have MediaConvert automatically determine a segment duration that is a multiple of both the audio packets and the frame rates: Choose Match. When you do, also specify a target segment duration under Segment length. This is useful for some ad-insertion or segment replacement workflows. Note that Match has the following requirements: - Output containers: Include at least one video output and at least one audio output. Audio-only outputs are not supported. - Output frame rate: Follow source is not supported. - Multiple output frame rates: When you specify multiple outputs, we recommend they share a similar frame rate (as in X/3, X/2, X, or 2X). For example: 5, 15, 30 and 60. Or: 25 and 50. (Outputs must share an integer multiple.) - Output audio codec: Specify Advanced Audio Coding (AAC). - Output sample rate: Choose 48kHz.", "smithy.api#jsonName" => "segmentLengthControl"}))
    DashIsoGroupSettings.add_member(:video_composition_offsets, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoVideoCompositionOffsets, location_name: 'VideoCompositionOffsets', traits: {"smithy.api#documentation" => "Specify the video sample composition time offset mode in the output fMP4 TRUN box. For wider player compatibility, set Video composition offsets to Unsigned or leave blank. The earliest presentation time may be greater than zero, and sample composition time offsets will increment using unsigned integers. For strict fMP4 video and audio timing, set Video composition offsets to Signed. The earliest presentation time will be equal to zero, and sample composition time offsets will increment using signed integers.", "smithy.api#jsonName" => "videoCompositionOffsets"}))
    DashIsoGroupSettings.add_member(:write_segment_timeline_in_representation, Smithy::Schema::Shapes::ShapeRef.new(shape: DashIsoWriteSegmentTimelineInRepresentation, location_name: 'WriteSegmentTimelineInRepresentation', traits: {"smithy.api#documentation" => "If you get an HTTP error in the 400 range when you play back your DASH output, enable this setting and run your transcoding job again. When you enable this setting, the service writes precise segment durations in the DASH manifest. The segment duration information appears inside the SegmentTimeline element, inside SegmentTemplate at the Representation level. When you don't enable this setting, the service writes approximate segment durations in your DASH manifest.", "smithy.api#jsonName" => "writeSegmentTimelineInRepresentation"}))
    DashIsoGroupSettings.type = Types::DashIsoGroupSettings
    DashIsoHbbtvCompliance.add_member(:hbbtv_1_5, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HBBTV_1_5', traits: {"smithy.api#enumValue" => "HBBTV_1_5"}))
