    DescribeEndpointsRequest.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DescribeEndpointsMode, location_name: 'Mode', traits: {"smithy.api#documentation" => "Optional field, defaults to DEFAULT. Specify DEFAULT for this operation to return your endpoints if any exist, or to create an endpoint for you and return it if one doesn't already exist. Specify GET_ONLY to return your endpoints if any exist, or an empty list if none exist.", "smithy.api#jsonName" => "mode"}))
