    DolbyVision.add_member(:l6_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DolbyVisionLevel6Mode, location_name: 'L6Mode', traits: {"smithy.api#documentation" => "Use Dolby Vision Mode to choose how the service will handle Dolby Vision MaxCLL and MaxFALL properies.", "smithy.api#jsonName" => "l6Mode"}))
    DolbyVision.add_member(:mapping, Smithy::Schema::Shapes::ShapeRef.new(shape: DolbyVisionMapping, location_name: 'Mapping', traits: {"smithy.api#documentation" => "Required when you set Dolby Vision Profile to Profile 8.1. When you set Content mapping to None, content mapping is not applied to the HDR10-compatible signal. Depending on the source peak nit level, clipping might occur on HDR devices without Dolby Vision. When you set Content mapping to HDR10 1000, the transcoder creates a 1,000 nits peak HDR10-compatible signal by applying static content mapping to the source. This mode is speed-optimized for PQ10 sources with metadata that is created from analysis. For graded Dolby Vision content, be aware that creative intent might not be guaranteed with extreme 1,000 nits trims.", "smithy.api#jsonName" => "mapping"}))
    DolbyVision.add_member(:profile, Smithy::Schema::Shapes::ShapeRef.new(shape: DolbyVisionProfile, location_name: 'Profile', traits: {"smithy.api#documentation" => "Required when you enable Dolby Vision. Use Profile 5 to include frame-interleaved Dolby Vision metadata in your output. Your input must include Dolby Vision metadata or an HDR10 YUV color space. Use Profile 8.1 to include frame-interleaved Dolby Vision metadata and HDR10 metadata in your output. Your input must include Dolby Vision metadata.", "smithy.api#jsonName" => "profile"}))
    DolbyVision.type = Types::DolbyVision
    DolbyVisionLevel6Metadata.add_member(:max_cll, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65535, location_name: 'MaxCll', traits: {"smithy.api#documentation" => "Maximum Content Light Level. Static HDR metadata that corresponds to the brightest pixel in the entire stream. Measured in nits.", "smithy.api#jsonName" => "maxCll"}))
    DolbyVisionLevel6Metadata.add_member(:max_fall, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65535, location_name: 'MaxFall', traits: {"smithy.api#documentation" => "Maximum Frame-Average Light Level. Static HDR metadata that corresponds to the highest frame-average brightness in the entire stream. Measured in nits.", "smithy.api#jsonName" => "maxFall"}))
    DolbyVisionLevel6Metadata.type = Types::DolbyVisionLevel6Metadata
    DolbyVisionLevel6Mode.add_member(:passthrough, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PASSTHROUGH', traits: {"smithy.api#enumValue" => "PASSTHROUGH"}))
    DolbyVisionLevel6Mode.add_member(:recalculate, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RECALCULATE', traits: {"smithy.api#enumValue" => "RECALCULATE"}))
    DolbyVisionLevel6Mode.add_member(:specify, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFY', traits: {"smithy.api#enumValue" => "SPECIFY"}))
    DolbyVisionMapping.add_member(:hdr10_nomap, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HDR10_NOMAP', traits: {"smithy.api#enumValue" => "HDR10_NOMAP"}))
    DolbyVisionMapping.add_member(:hdr10_1000, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HDR10_1000', traits: {"smithy.api#enumValue" => "HDR10_1000"}))
    DolbyVisionProfile.add_member(:profile_5, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROFILE_5', traits: {"smithy.api#enumValue" => "PROFILE_5"}))
    DolbyVisionProfile.add_member(:profile_8_1, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROFILE_8_1', traits: {"smithy.api#enumValue" => "PROFILE_8_1"}))
    DropFrameTimecode.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    DropFrameTimecode.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    DvbNitSettings.add_member(:network_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65535, location_name: 'NetworkId', traits: {"smithy.api#documentation" => "The numeric value placed in the Network Information Table (NIT).", "smithy.api#jsonName" => "networkId"}))
    DvbNitSettings.add_member(:network_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max256, location_name: 'NetworkName', traits: {"smithy.api#documentation" => "The network name text placed in the network_name_descriptor inside the Network Information Table. Maximum length is 256 characters.", "smithy.api#jsonName" => "networkName"}))
    DvbNitSettings.add_member(:nit_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin25max10000, location_name: 'NitInterval', traits: {"smithy.api#documentation" => "The number of milliseconds between instances of this table in the output transport stream.", "smithy.api#jsonName" => "nitInterval"}))
    DvbNitSettings.type = Types::DvbNitSettings
    DvbSdtSettings.add_member(:output_sdt, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputSdt, location_name: 'OutputSdt', traits: {"smithy.api#documentation" => "Selects method of inserting SDT information into output stream. \"Follow input SDT\" copies SDT information from input stream to output stream. \"Follow input SDT if present\" copies SDT information from input stream to output stream if SDT information is present in the input, otherwise it will fall back on the user-defined values. Enter \"SDT Manually\" means user will enter the SDT information. \"No SDT\" means output stream will not contain SDT information.", "smithy.api#jsonName" => "outputSdt"}))
    DvbSdtSettings.add_member(:sdt_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin25max2000, location_name: 'SdtInterval', traits: {"smithy.api#documentation" => "The number of milliseconds between instances of this table in the output transport stream.", "smithy.api#jsonName" => "sdtInterval"}))
    DvbSdtSettings.add_member(:service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max256, location_name: 'ServiceName', traits: {"smithy.api#documentation" => "The service name placed in the service_descriptor in the Service Description Table. Maximum length is 256 characters.", "smithy.api#jsonName" => "serviceName"}))
    DvbSdtSettings.add_member(:service_provider_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max256, location_name: 'ServiceProviderName', traits: {"smithy.api#documentation" => "The service provider name placed in the service_descriptor in the Service Description Table. Maximum length is 256 characters.", "smithy.api#jsonName" => "serviceProviderName"}))
    DvbSdtSettings.type = Types::DvbSdtSettings
    DvbSubDestinationSettings.add_member(:alignment, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleAlignment, location_name: 'Alignment', traits: {"smithy.api#documentation" => "Specify the alignment of your captions. If no explicit x_position is provided, setting alignment to centered will placethe captions at the bottom center of the output. Similarly, setting a left alignment willalign captions to the bottom left of the output. If x and y positions are given in conjunction with the alignment parameter, the font will be justified (either left or centered) relative to those coordinates. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "alignment"}))
    DvbSubDestinationSettings.add_member(:apply_font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleApplyFontColor, location_name: 'ApplyFontColor', traits: {"smithy.api#documentation" => "Ignore this setting unless Style Passthrough is set to Enabled and Font color set to Black, Yellow, Red, Green, Blue, or Hex. Use Apply font color for additional font color controls. When you choose White text only, or leave blank, your font color setting only applies to white text in your input captions. For example, if your font color setting is Yellow, and your input captions have red and white text, your output captions will have red and yellow text. When you choose ALL_TEXT, your font color setting applies to all of your output captions text.", "smithy.api#jsonName" => "applyFontColor"}))
    DvbSubDestinationSettings.add_member(:background_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleBackgroundColor, location_name: 'BackgroundColor', traits: {"smithy.api#documentation" => "Specify the color of the rectangle behind the captions. Leave background color blank and set Style passthrough to enabled to use the background color data from your input captions, if present.", "smithy.api#jsonName" => "backgroundColor"}))
    DvbSubDestinationSettings.add_member(:background_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'BackgroundOpacity', traits: {"smithy.api#documentation" => "Specify the opacity of the background rectangle. Enter a value from 0 to 255, where 0 is transparent and 255 is opaque. If Style passthrough is set to enabled, leave blank to pass through the background style information in your input captions to your output captions. If Style passthrough is set to disabled, leave blank to use a value of 0 and remove all backgrounds from your output captions. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "backgroundOpacity"}))
    DvbSubDestinationSettings.add_member(:dds_handling, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbddsHandling, location_name: 'DdsHandling', traits: {"smithy.api#documentation" => "Specify how MediaConvert handles the display definition segment (DDS). To exclude the DDS from this set of captions: Keep the default, None. To include the DDS: Choose Specified. When you do, also specify the offset coordinates of the display window with DDS x-coordinate and DDS y-coordinate. To include the DDS, but not include display window data: Choose No display window. When you do, you can write position metadata to the page composition segment (PCS) with DDS x-coordinate and DDS y-coordinate. For video resolutions with a height of 576 pixels or less, MediaConvert doesn't include the DDS, regardless of the value you choose for DDS handling. All burn-in and DVB-Sub font settings must match. To include the DDS, with optimized subtitle placement and reduced data overhead: We recommend that you choose Specified (optimal). This option provides the same visual positioning as Specified while using less bandwidth. This also supports resolutions higher than 1080p while maintaining full DVB-Sub compatibility. When you do, also specify the offset coordinates of the display window with DDS x-coordinate and DDS y-coordinate.", "smithy.api#jsonName" => "ddsHandling"}))
    DvbSubDestinationSettings.add_member(:dds_x_coordinate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'DdsXCoordinate', traits: {"smithy.api#documentation" => "Use this setting, along with DDS y-coordinate, to specify the upper left corner of the display definition segment (DDS) display window. With this setting, specify the distance, in pixels, between the left side of the frame and the left side of the DDS display window. Keep the default value, 0, to have MediaConvert automatically choose this offset. Related setting: When you use this setting, you must set DDS handling to a value other than None. MediaConvert uses these values to determine whether to write page position data to the DDS or to the page composition segment. All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "ddsXCoordinate"}))
    DvbSubDestinationSettings.add_member(:dds_y_coordinate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'DdsYCoordinate', traits: {"smithy.api#documentation" => "Use this setting, along with DDS x-coordinate, to specify the upper left corner of the display definition segment (DDS) display window. With this setting, specify the distance, in pixels, between the top of the frame and the top of the DDS display window. Keep the default value, 0, to have MediaConvert automatically choose this offset. Related setting: When you use this setting, you must set DDS handling to a value other than None. MediaConvert uses these values to determine whether to write page position data to the DDS or to the page composition segment (PCS). All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "ddsYCoordinate"}))
    DvbSubDestinationSettings.add_member(:fallback_font, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubSubtitleFallbackFont, location_name: 'FallbackFont', traits: {"smithy.api#documentation" => "Specify the font that you want the service to use for your burn in captions when your input captions specify a font that MediaConvert doesn't support. When you set Fallback font to best match, or leave blank, MediaConvert uses a supported font that most closely matches the font that your input captions specify. When there are multiple unsupported fonts in your input captions, MediaConvert matches each font with the supported font that matches best. When you explicitly choose a replacement font, MediaConvert uses that font to replace all unsupported fonts from your input.", "smithy.api#jsonName" => "fallbackFont"}))
    DvbSubDestinationSettings.add_member(:font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleFontColor, location_name: 'FontColor', traits: {"smithy.api#documentation" => "Specify the color of the captions text. Leave Font color blank and set Style passthrough to enabled to use the font color data from your input captions, if present. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "fontColor"}))
    DvbSubDestinationSettings.add_member(:font_file_bold, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileBold', traits: {"smithy.api#documentation" => "Specify a bold TrueType font file to use when rendering your output captions. Enter an S3, HTTP, or HTTPS URL. When you do, you must also separately specify a regular, an italic, and a bold italic font file.", "smithy.api#jsonName" => "fontFileBold"}))
    DvbSubDestinationSettings.add_member(:font_file_bold_italic, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileBoldItalic', traits: {"smithy.api#documentation" => "Specify a bold italic TrueType font file to use when rendering your output captions.\nEnter an S3, HTTP, or HTTPS URL.\nWhen you do, you must also separately specify a regular, a bold, and an italic font file.", "smithy.api#jsonName" => "fontFileBoldItalic"}))
    DvbSubDestinationSettings.add_member(:font_file_italic, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileItalic', traits: {"smithy.api#documentation" => "Specify an italic TrueType font file to use when rendering your output captions. Enter an S3, HTTP, or HTTPS URL. When you do, you must also separately specify a regular, a bold, and a bold italic font file.", "smithy.api#jsonName" => "fontFileItalic"}))
    DvbSubDestinationSettings.add_member(:font_file_regular, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3ttfhttpsttf, location_name: 'FontFileRegular', traits: {"smithy.api#documentation" => "Specify a regular TrueType font file to use when rendering your output captions. Enter an S3, HTTP, or HTTPS URL. When you do, you must also separately specify a bold, an italic, and a bold italic font file.", "smithy.api#jsonName" => "fontFileRegular"}))
    DvbSubDestinationSettings.add_member(:font_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'FontOpacity', traits: {"smithy.api#documentation" => "Specify the opacity of the burned-in captions. 255 is opaque; 0 is transparent.\nWithin your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "fontOpacity"}))
    DvbSubDestinationSettings.add_member(:font_resolution, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin96max600, location_name: 'FontResolution', traits: {"smithy.api#documentation" => "Specify the Font resolution in DPI (dots per inch).\nWithin your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "fontResolution"}))
    DvbSubDestinationSettings.add_member(:font_script, Smithy::Schema::Shapes::ShapeRef.new(shape: FontScript, location_name: 'FontScript', traits: {"smithy.api#documentation" => "Set Font script to Automatically determined, or leave blank, to automatically determine the font script in your input captions. Otherwise, set to Simplified Chinese (HANS) or Traditional Chinese (HANT) if your input font script uses Simplified or Traditional Chinese. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "fontScript"}))
    DvbSubDestinationSettings.add_member(:font_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max96, location_name: 'FontSize', traits: {"smithy.api#documentation" => "Specify the Font size in pixels. Must be a positive integer. Set to 0, or leave blank, for automatic font size. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "fontSize"}))
    DvbSubDestinationSettings.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'Height', traits: {"smithy.api#documentation" => "Specify the height, in pixels, of this set of DVB-Sub captions. The default value is 576 pixels. Related setting: When you use this setting, you must set DDS handling to a value other than None. All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "height"}))
    DvbSubDestinationSettings.add_member(:hex_font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin6max8pattern09afaf609afaf2, location_name: 'HexFontColor', traits: {"smithy.api#documentation" => "Ignore this setting unless your Font color is set to Hex. Enter either six or eight hexidecimal digits, representing red, green, and blue, with two optional extra digits for alpha. For example a value of 1122AABB is a red value of 0x11, a green value of 0x22, a blue value of 0xAA, and an alpha value of 0xBB.", "smithy.api#jsonName" => "hexFontColor"}))
    DvbSubDestinationSettings.add_member(:outline_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleOutlineColor, location_name: 'OutlineColor', traits: {"smithy.api#documentation" => "Specify font outline color. Leave Outline color blank and set Style passthrough to enabled to use the font outline color data from your input captions, if present. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "outlineColor"}))
    DvbSubDestinationSettings.add_member(:outline_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max10, location_name: 'OutlineSize', traits: {"smithy.api#documentation" => "Specify the Outline size of the caption text, in pixels. Leave Outline size blank and set Style passthrough to enabled to use the outline size data from your input captions, if present. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "outlineSize"}))
    DvbSubDestinationSettings.add_member(:shadow_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleShadowColor, location_name: 'ShadowColor', traits: {"smithy.api#documentation" => "Specify the color of the shadow cast by the captions. Leave Shadow color blank and set Style passthrough to enabled to use the shadow color data from your input captions, if present. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "shadowColor"}))
    DvbSubDestinationSettings.add_member(:shadow_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'ShadowOpacity', traits: {"smithy.api#documentation" => "Specify the opacity of the shadow. Enter a value from 0 to 255, where 0 is transparent and 255 is opaque. If Style passthrough is set to Enabled, leave Shadow opacity blank to pass through the shadow style information in your input captions to your output captions. If Style passthrough is set to disabled, leave blank to use a value of 0 and remove all shadows from your output captions. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "shadowOpacity"}))
    DvbSubDestinationSettings.add_member(:shadow_x_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'ShadowXOffset', traits: {"smithy.api#documentation" => "Specify the horizontal offset of the shadow, relative to the captions in pixels. A value of -2 would result in a shadow offset 2 pixels to the left. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "shadowXOffset"}))
    DvbSubDestinationSettings.add_member(:shadow_y_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'ShadowYOffset', traits: {"smithy.api#documentation" => "Specify the vertical offset of the shadow relative to the captions in pixels. A value of -2 would result in a shadow offset 2 pixels above the text. Leave Shadow y-offset blank and set Style passthrough to enabled to use the shadow y-offset data from your input captions, if present. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "shadowYOffset"}))
    DvbSubDestinationSettings.add_member(:style_passthrough, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleStylePassthrough, location_name: 'StylePassthrough', traits: {"smithy.api#documentation" => "To use the available style, color, and position information from your input captions: Set Style passthrough to Enabled. Note that MediaConvert uses default settings for any missing style or position information in your input captions To ignore the style and position information from your input captions and use default settings: Leave blank or keep the default value, Disabled. Default settings include white text with black outlining, bottom-center positioning, and automatic sizing. Whether you set Style passthrough to enabled or not, you can also choose to manually override any of the individual style and position settings. You can also override any fonts by manually specifying custom font files.", "smithy.api#jsonName" => "stylePassthrough"}))
    DvbSubDestinationSettings.add_member(:subtitling_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitlingType, location_name: 'SubtitlingType', traits: {"smithy.api#documentation" => "Specify whether your DVB subtitles are standard or for hearing impaired. Choose hearing impaired if your subtitles include audio descriptions and dialogue. Choose standard if your subtitles include only dialogue.", "smithy.api#jsonName" => "subtitlingType"}))
    DvbSubDestinationSettings.add_member(:teletext_spacing, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubtitleTeletextSpacing, location_name: 'TeletextSpacing', traits: {"smithy.api#documentation" => "Specify whether the Text spacing in your captions is set by the captions grid, or varies depending on letter width. Choose fixed grid to conform to the spacing specified in the captions file more accurately. Choose proportional to make the text easier to read for closed captions. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "teletextSpacing"}))
    DvbSubDestinationSettings.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'Width', traits: {"smithy.api#documentation" => "Specify the width, in pixels, of this set of DVB-Sub captions. The default value is 720 pixels. Related setting: When you use this setting, you must set DDS handling to a value other than None. All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "width"}))
    DvbSubDestinationSettings.add_member(:x_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'XPosition', traits: {"smithy.api#documentation" => "Specify the horizontal position of the captions, relative to the left side of the output in pixels. A value of 10 would result in the captions starting 10 pixels from the left of the output. If no explicit x_position is provided, the horizontal caption position will be determined by the alignment parameter. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "xPosition"}))
    DvbSubDestinationSettings.add_member(:y_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'YPosition', traits: {"smithy.api#documentation" => "Specify the vertical position of the captions, relative to the top of the output in pixels. A value of 10 would result in the captions starting 10 pixels from the top of the output. If no explicit y_position is provided, the caption will be positioned towards the bottom of the output. Within your job settings, all of your DVB-Sub settings must be identical.", "smithy.api#jsonName" => "yPosition"}))
    DvbSubDestinationSettings.type = Types::DvbSubDestinationSettings
    DvbSubSourceSettings.add_member(:pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'Pid', traits: {"smithy.api#documentation" => "When using DVB-Sub with Burn-in, use this PID for the source content. Unused for DVB-Sub passthrough. All DVB-Sub content is passed through, regardless of selectors.", "smithy.api#jsonName" => "pid"}))
    DvbSubSourceSettings.type = Types::DvbSubSourceSettings
    DvbSubSubtitleFallbackFont.add_member(:best_match, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BEST_MATCH', traits: {"smithy.api#enumValue" => "BEST_MATCH"}))
    DvbSubSubtitleFallbackFont.add_member(:monospaced_sansserif, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MONOSPACED_SANSSERIF', traits: {"smithy.api#enumValue" => "MONOSPACED_SANSSERIF"}))
    DvbSubSubtitleFallbackFont.add_member(:monospaced_serif, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MONOSPACED_SERIF', traits: {"smithy.api#enumValue" => "MONOSPACED_SERIF"}))
    DvbSubSubtitleFallbackFont.add_member(:proportional_sansserif, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROPORTIONAL_SANSSERIF', traits: {"smithy.api#enumValue" => "PROPORTIONAL_SANSSERIF"}))
    DvbSubSubtitleFallbackFont.add_member(:proportional_serif, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROPORTIONAL_SERIF', traits: {"smithy.api#enumValue" => "PROPORTIONAL_SERIF"}))
    DvbSubtitleAlignment.add_member(:centered, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CENTERED', traits: {"smithy.api#enumValue" => "CENTERED"}))
    DvbSubtitleAlignment.add_member(:left, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LEFT', traits: {"smithy.api#enumValue" => "LEFT"}))
    DvbSubtitleAlignment.add_member(:auto, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AUTO', traits: {"smithy.api#enumValue" => "AUTO"}))
