    Eac3AtmosSettings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin384000max1024000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Specify the average bitrate for this output in bits per second. Valid values: 384k, 448k, 576k, 640k, 768k, 1024k Default value: 448k Note that MediaConvert supports 384k only with channel-based immersive (CBI) 7.1.4 and 5.1.4 inputs. For CBI 9.1.6 and other input types, MediaConvert automatically increases your output bitrate to 448k.", "smithy.api#jsonName" => "bitrate"}))
    Eac3AtmosSettings.add_member(:bitstream_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosBitstreamMode, location_name: 'BitstreamMode', traits: {"smithy.api#documentation" => "Specify the bitstream mode for the E-AC-3 stream that the encoder emits. For more information about the EAC3 bitstream mode, see ATSC A/52-2012 (Annex E).", "smithy.api#jsonName" => "bitstreamMode"}))
    Eac3AtmosSettings.add_member(:coding_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosCodingMode, location_name: 'CodingMode', traits: {"smithy.api#documentation" => "The coding mode for Dolby Digital Plus JOC (Atmos).", "smithy.api#jsonName" => "codingMode"}))
    Eac3AtmosSettings.add_member(:dialogue_intelligence, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosDialogueIntelligence, location_name: 'DialogueIntelligence', traits: {"smithy.api#documentation" => "Enable Dolby Dialogue Intelligence to adjust loudness based on dialogue analysis.", "smithy.api#jsonName" => "dialogueIntelligence"}))
    Eac3AtmosSettings.add_member(:downmix_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosDownmixControl, location_name: 'DownmixControl', traits: {"smithy.api#documentation" => "Specify whether MediaConvert should use any downmix metadata from your input file. Keep the default value, Custom to provide downmix values in your job settings. Choose Follow source to use the metadata from your input. Related settings--Use these settings to specify your downmix values: Left only/Right only surround, Left total/Right total surround, Left total/Right total center, Left only/Right only center, and Stereo downmix. When you keep Custom for Downmix control and you don't specify values for the related settings, MediaConvert uses default values for those settings.", "smithy.api#jsonName" => "downmixControl"}))
    Eac3AtmosSettings.add_member(:dynamic_range_compression_line, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosDynamicRangeCompressionLine, location_name: 'DynamicRangeCompressionLine', traits: {"smithy.api#documentation" => "Choose the Dolby dynamic range control (DRC) profile that MediaConvert uses when encoding the metadata in the Dolby stream for the line operating mode. Default value: Film light Related setting: To have MediaConvert use the value you specify here, keep the default value, Custom for the setting Dynamic range control. Otherwise, MediaConvert ignores Dynamic range compression line. For information about the Dolby DRC operating modes and profiles, see the Dynamic Range Control chapter of the Dolby Metadata Guide at https://developer.dolby.com/globalassets/professional/documents/dolby-metadata-guide.pdf.", "smithy.api#jsonName" => "dynamicRangeCompressionLine"}))
    Eac3AtmosSettings.add_member(:dynamic_range_compression_rf, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosDynamicRangeCompressionRf, location_name: 'DynamicRangeCompressionRf', traits: {"smithy.api#documentation" => "Choose the Dolby dynamic range control (DRC) profile that MediaConvert uses when encoding the metadata in the Dolby stream for the RF operating mode. Default value: Film light Related setting: To have MediaConvert use the value you specify here, keep the default value, Custom for the setting Dynamic range control. Otherwise, MediaConvert ignores Dynamic range compression RF. For information about the Dolby DRC operating modes and profiles, see the Dynamic Range Control chapter of the Dolby Metadata Guide at https://developer.dolby.com/globalassets/professional/documents/dolby-metadata-guide.pdf.", "smithy.api#jsonName" => "dynamicRangeCompressionRf"}))
    Eac3AtmosSettings.add_member(:dynamic_range_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AtmosDynamicRangeControl, location_name: 'DynamicRangeControl', traits: {"smithy.api#documentation" => "Specify whether MediaConvert should use any dynamic range control metadata from your input file. Keep the default value, Custom, to provide dynamic range control values in your job settings. Choose Follow source to use the metadata from your input. Related settings--Use these settings to specify your dynamic range control values: Dynamic range compression line and Dynamic range compression RF. When you keep the value Custom for Dynamic range control and you don't specify values for the related settings, MediaConvert uses default values for those settings.", "smithy.api#jsonName" => "dynamicRangeControl"}))
    Eac3AtmosSettings.add_member(:lo_ro_center_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative6max3, location_name: 'LoRoCenterMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Atmos setting: Left only/Right only center mix (Lo/Ro center). MediaConvert uses this value for downmixing. Default value: -3 dB. Valid values: 3.0, 1.5, 0.0, -1.5, -3.0, -4.5, and -6.0. Related setting: How the service uses this value depends on the value that you choose for Stereo downmix. Related setting: To have MediaConvert use this value, keep the default value, Custom for the setting Downmix control. Otherwise, MediaConvert ignores Left only/Right only center.", "smithy.api#jsonName" => "loRoCenterMixLevel"}))
    Eac3AtmosSettings.add_member(:lo_ro_surround_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative60maxnegative1, location_name: 'LoRoSurroundMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Atmos setting: Left only/Right only. MediaConvert uses this value for downmixing. Default value: -3 dB. Valid values: -1.5, -3.0, -4.5, -6.0, and -60. The value -60 mutes the channel. Related setting: How the service uses this value depends on the value that you choose for Stereo downmix. Related setting: To have MediaConvert use this value, keep the default value, Custom for the setting Downmix control. Otherwise, MediaConvert ignores Left only/Right only surround.", "smithy.api#jsonName" => "loRoSurroundMixLevel"}))
    Eac3AtmosSettings.add_member(:lt_rt_center_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative6max3, location_name: 'LtRtCenterMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Atmos setting: Left total/Right total center mix (Lt/Rt center). MediaConvert uses this value for downmixing. Default value: -3 dB Valid values: 3.0, 1.5, 0.0, -1.5, -3.0, -4.5, and -6.0. Related setting: How the service uses this value depends on the value that you choose for Stereo downmix. Related setting: To have MediaConvert use this value, keep the default value, Custom for the setting Downmix control. Otherwise, MediaConvert ignores Left total/Right total center.", "smithy.api#jsonName" => "ltRtCenterMixLevel"}))
    Eac3AtmosSettings.add_member(:lt_rt_surround_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative60maxnegative1, location_name: 'LtRtSurroundMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Atmos setting: Left total/Right total surround mix (Lt/Rt surround). MediaConvert uses this value for downmixing. Default value: -3 dB Valid values: -1.5, -3.0, -4.5, -6.0, and -60. The value -60 mutes the channel. Related setting: How the service uses this value depends on the value that you choose for Stereo downmix. Related setting: To have MediaConvert use this value, keep the default value, Custom for the setting Downmix control. Otherwise, the service ignores Left total/Right total surround.", "smithy.api#jsonName" => "ltRtSurroundMixLevel"}))
