    Eac3AtmosSettings.add_member(:speech_threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max100, location_name: 'SpeechThreshold', traits: {"smithy.api#documentation" => "Specify the percentage of audio content, from 0% to 100%, that must be speech in order for the encoder to use the measured speech loudness as the overall program loudness. Default value: 15%", "smithy.api#jsonName" => "speechThreshold"}))
