    Eac3Settings.add_member(:attenuation_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3AttenuationControl, location_name: 'AttenuationControl', traits: {"smithy.api#documentation" => "If set to ATTENUATE_3_DB, applies a 3 dB attenuation to the surround channels. Only used for 3/2 coding mode.", "smithy.api#jsonName" => "attenuationControl"}))
    Eac3Settings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32000max3024000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Specify the average bitrate in bits per second. The bitrate that you specify must be a multiple of 8000 within the allowed minimum and maximum values. Leave blank to use the default bitrate for the coding mode you select according ETSI TS 102 366. Valid bitrates for coding mode 1/0: Default: 96000. Minimum: 32000. Maximum: 3024000. Valid bitrates for coding mode 2/0: Default: 192000. Minimum: 96000. Maximum: 3024000. Valid bitrates for coding mode 3/2: Default: 384000. Minimum: 192000. Maximum: 3024000.", "smithy.api#jsonName" => "bitrate"}))
    Eac3Settings.add_member(:bitstream_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3BitstreamMode, location_name: 'BitstreamMode', traits: {"smithy.api#documentation" => "Specify the bitstream mode for the E-AC-3 stream that the encoder emits. For more information about the EAC3 bitstream mode, see ATSC A/52-2012 (Annex E).", "smithy.api#jsonName" => "bitstreamMode"}))
    Eac3Settings.add_member(:coding_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3CodingMode, location_name: 'CodingMode', traits: {"smithy.api#documentation" => "Dolby Digital Plus coding mode. Determines number of channels.", "smithy.api#jsonName" => "codingMode"}))
    Eac3Settings.add_member(:dc_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3DcFilter, location_name: 'DcFilter', traits: {"smithy.api#documentation" => "Activates a DC highpass filter for all input channels.", "smithy.api#jsonName" => "dcFilter"}))
    Eac3Settings.add_member(:dialnorm, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max31, location_name: 'Dialnorm', traits: {"smithy.api#documentation" => "Sets the dialnorm for the output. If blank and input audio is Dolby Digital Plus, dialnorm will be passed through.", "smithy.api#jsonName" => "dialnorm"}))
    Eac3Settings.add_member(:dynamic_range_compression_line, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3DynamicRangeCompressionLine, location_name: 'DynamicRangeCompressionLine', traits: {"smithy.api#documentation" => "Choose the Dolby Digital dynamic range control (DRC) profile that MediaConvert uses when encoding the metadata in the Dolby Digital stream for the line operating mode. Related setting: When you use this setting, MediaConvert ignores any value you provide for Dynamic range compression profile. For information about the Dolby Digital DRC operating modes and profiles, see the Dynamic Range Control chapter of the Dolby Metadata Guide at https://developer.dolby.com/globalassets/professional/documents/dolby-metadata-guide.pdf.", "smithy.api#jsonName" => "dynamicRangeCompressionLine"}))
    Eac3Settings.add_member(:dynamic_range_compression_rf, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3DynamicRangeCompressionRf, location_name: 'DynamicRangeCompressionRf', traits: {"smithy.api#documentation" => "Choose the Dolby Digital dynamic range control (DRC) profile that MediaConvert uses when encoding the metadata in the Dolby Digital stream for the RF operating mode. Related setting: When you use this setting, MediaConvert ignores any value you provide for Dynamic range compression profile. For information about the Dolby Digital DRC operating modes and profiles, see the Dynamic Range Control chapter of the Dolby Metadata Guide at https://developer.dolby.com/globalassets/professional/documents/dolby-metadata-guide.pdf.", "smithy.api#jsonName" => "dynamicRangeCompressionRf"}))
    Eac3Settings.add_member(:lfe_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3LfeControl, location_name: 'LfeControl', traits: {"smithy.api#documentation" => "When encoding 3/2 audio, controls whether the LFE channel is enabled", "smithy.api#jsonName" => "lfeControl"}))
    Eac3Settings.add_member(:lfe_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3LfeFilter, location_name: 'LfeFilter', traits: {"smithy.api#documentation" => "Applies a 120Hz lowpass filter to the LFE channel prior to encoding. Only valid with 3_2_LFE coding mode.", "smithy.api#jsonName" => "lfeFilter"}))
    Eac3Settings.add_member(:lo_ro_center_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative60max3, location_name: 'LoRoCenterMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Digital Plus setting: Left only/Right only center mix. MediaConvert uses this value for downmixing. How the service uses this value depends on the value that you choose for Stereo downmix. Valid values: 3.0, 1.5, 0.0, -1.5, -3.0, -4.5, -6.0, and -60. The value -60 mutes the channel. This setting applies only if you keep the default value of 3/2 - L, R, C, Ls, Rs for the setting Coding mode. If you choose a different value for Coding mode, the service ignores Left only/Right only center.", "smithy.api#jsonName" => "loRoCenterMixLevel"}))
    Eac3Settings.add_member(:lo_ro_surround_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative60maxnegative1, location_name: 'LoRoSurroundMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Digital Plus setting: Left only/Right only. MediaConvert uses this value for downmixing. How the service uses this value depends on the value that you choose for Stereo downmix. Valid values: -1.5, -3.0, -4.5, -6.0, and -60. The value -60 mutes the channel. This setting applies only if you keep the default value of 3/2 - L, R, C, Ls, Rs for the setting Coding mode. If you choose a different value for Coding mode, the service ignores Left only/Right only surround.", "smithy.api#jsonName" => "loRoSurroundMixLevel"}))
    Eac3Settings.add_member(:lt_rt_center_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative60max3, location_name: 'LtRtCenterMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Digital Plus setting: Left total/Right total center mix. MediaConvert uses this value for downmixing. How the service uses this value depends on the value that you choose for Stereo downmix. Valid values: 3.0, 1.5, 0.0, -1.5, -3.0, -4.5, -6.0, and -60. The value -60 mutes the channel. This setting applies only if you keep the default value of 3/2 - L, R, C, Ls, Rs for the setting Coding mode. If you choose a different value for Coding mode, the service ignores Left total/Right total center.", "smithy.api#jsonName" => "ltRtCenterMixLevel"}))
    Eac3Settings.add_member(:lt_rt_surround_mix_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Doubleminnegative60maxnegative1, location_name: 'LtRtSurroundMixLevel', traits: {"smithy.api#documentation" => "Specify a value for the following Dolby Digital Plus setting: Left total/Right total surround mix. MediaConvert uses this value for downmixing. How the service uses this value depends on the value that you choose for Stereo downmix. Valid values: -1.5, -3.0, -4.5, -6.0, and -60. The value -60 mutes the channel. This setting applies only if you keep the default value of 3/2 - L, R, C, Ls, Rs for the setting Coding mode. If you choose a different value for Coding mode, the service ignores Left total/Right total surround.", "smithy.api#jsonName" => "ltRtSurroundMixLevel"}))
    Eac3Settings.add_member(:metadata_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3MetadataControl, location_name: 'MetadataControl', traits: {"smithy.api#documentation" => "When set to FOLLOW_INPUT, encoder metadata will be sourced from the DD, DD+, or DolbyE decoder that supplied this audio data. If audio was not supplied from one of these streams, then the static metadata settings will be used.", "smithy.api#jsonName" => "metadataControl"}))
    Eac3Settings.add_member(:passthrough_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3PassthroughControl, location_name: 'PassthroughControl', traits: {"smithy.api#documentation" => "When set to WHEN_POSSIBLE, input DD+ audio will be passed through if it is present on the input. this detection is dynamic over the life of the transcode. Inputs that alternate between DD+ and non-DD+ content will have a consistent DD+ output as the system alternates between passthrough and encoding.", "smithy.api#jsonName" => "passthroughControl"}))
    Eac3Settings.add_member(:phase_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3PhaseControl, location_name: 'PhaseControl', traits: {"smithy.api#documentation" => "Controls the amount of phase-shift applied to the surround channels. Only used for 3/2 coding mode.", "smithy.api#jsonName" => "phaseControl"}))
    Eac3Settings.add_member(:sample_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin48000max48000, location_name: 'SampleRate', traits: {"smithy.api#documentation" => "This value is always 48000. It represents the sample rate in Hz.", "smithy.api#jsonName" => "sampleRate"}))
    Eac3Settings.add_member(:stereo_downmix, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3StereoDownmix, location_name: 'StereoDownmix', traits: {"smithy.api#documentation" => "Choose how the service does stereo downmixing. This setting only applies if you keep the default value of 3/2 - L, R, C, Ls, Rs for the setting Coding mode. If you choose a different value for Coding mode, the service ignores Stereo downmix.", "smithy.api#jsonName" => "stereoDownmix"}))
    Eac3Settings.add_member(:surround_ex_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3SurroundExMode, location_name: 'SurroundExMode', traits: {"smithy.api#documentation" => "When encoding 3/2 audio, sets whether an extra center back surround channel is matrix encoded into the left and right surround channels.", "smithy.api#jsonName" => "surroundExMode"}))
    Eac3Settings.add_member(:surround_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Eac3SurroundMode, location_name: 'SurroundMode', traits: {"smithy.api#documentation" => "When encoding 2/0 audio, sets whether Dolby Surround is matrix encoded into the two channels.", "smithy.api#jsonName" => "surroundMode"}))
