    EmbeddedSourceSettings.add_member(:source608_track_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max1, location_name: 'Source608TrackNumber', traits: {"smithy.api#documentation" => "Specifies the video track index used for extracting captions. The system only supports one input video track, so this should always be set to '1'.", "smithy.api#jsonName" => "source608TrackNumber"}))
