    FileSourceSettings.add_member(:byte_rate_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptionSourceByteRateLimit, location_name: 'ByteRateLimit', traits: {"smithy.api#documentation" => "Choose whether to limit the byte rate at which your SCC input captions are inserted into your output. To not limit the caption rate: We recommend that you keep the default value, Disabled. MediaConvert inserts captions in your output according to the byte rates listed in the EIA-608 specification, typically 2 or 3 caption bytes per frame depending on your output frame rate. To limit your output caption rate: Choose Enabled. Choose this option if your downstream systems require a maximum of 2 caption bytes per frame. Note that this setting has no effect when your output frame rate is 30 or 60.", "smithy.api#jsonName" => "byteRateLimit"}))
    FileSourceSettings.add_member(:convert608_to708, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSourceConvert608To708, location_name: 'Convert608To708', traits: {"smithy.api#documentation" => "Specify whether this set of input captions appears in your outputs in both 608 and 708 format. If you choose Upconvert, MediaConvert includes the captions data in two ways: it passes the 608 data through using the 608 compatibility bytes fields of the 708 wrapper, and it also translates the 608 data into 708.", "smithy.api#jsonName" => "convert608To708"}))
    FileSourceSettings.add_member(:convert_paint_to_pop, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptionSourceConvertPaintOnToPopOn, location_name: 'ConvertPaintToPop', traits: {"smithy.api#documentation" => "Choose the presentation style of your input SCC captions. To use the same presentation style as your input: Keep the default value, Disabled. To convert paint-on captions to pop-on: Choose Enabled. We also recommend that you choose Enabled if you notice additional repeated lines in your output captions.", "smithy.api#jsonName" => "convertPaintToPop"}))
    FileSourceSettings.add_member(:framerate, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptionSourceFramerate, location_name: 'Framerate', traits: {"smithy.api#documentation" => "Ignore this setting unless your input captions format is SCC. To have the service compensate for differing frame rates between your input captions and input video, specify the frame rate of the captions file. Specify this value as a fraction. For example, you might specify 24 / 1 for 24 fps, 25 / 1 for 25 fps, 24000 / 1001 for 23.976 fps, or 30000 / 1001 for 29.97 fps.", "smithy.api#jsonName" => "framerate"}))
    FileSourceSettings.add_member(:source_file, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin14patterns3sccsccttmlttmldfxpdfxpstlstlsrtsrtxmlxmlsmismivttvttwebvttwebvtthttpssccsccttmlttmldfxpdfxpstlstlsrtsrtxmlxmlsmismivttvttwebvttwebvtt, location_name: 'SourceFile', traits: {"smithy.api#documentation" => "External caption file used for loading captions. Accepted file extensions are 'scc', 'ttml', 'dfxp', 'stl', 'srt', 'xml', 'smi', 'webvtt', and 'vtt'.", "smithy.api#jsonName" => "sourceFile"}))
    FileSourceSettings.add_member(:time_delta, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'TimeDelta', traits: {"smithy.api#documentation" => "Optional. Use this setting when you need to adjust the sync between your sidecar captions and your video. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/time-delta-use-cases.html. Enter a positive or negative number to modify the times in the captions file. For example, type 15 to add 15 seconds to all the times in the captions file. Type -5 to subtract 5 seconds from the times in the captions file. You can optionally specify your time delta in milliseconds instead of seconds. When you do so, set the related setting, Time delta units to Milliseconds. Note that, when you specify a time delta for timecode-based caption sources, such as SCC and STL, and your time delta isn't a multiple of the input frame rate, MediaConvert snaps the captions to the nearest frame. For example, when your input video frame rate is 25 fps and you specify 1010ms for time delta, MediaConvert delays your captions by 1000 ms.", "smithy.api#jsonName" => "timeDelta"}))
    FileSourceSettings.add_member(:time_delta_units, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSourceTimeDeltaUnits, location_name: 'TimeDeltaUnits', traits: {"smithy.api#documentation" => "When you use the setting Time delta to adjust the sync between your sidecar captions and your video, use this setting to specify the units for the delta that you specify. When you don't specify a value for Time delta units, MediaConvert uses seconds by default.", "smithy.api#jsonName" => "timeDeltaUnits"}))
    FileSourceSettings.add_member(:upconvert_stl_to_teletext, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptionSourceUpconvertSTLToTeletext, location_name: 'UpconvertSTLToTeletext', traits: {"smithy.api#documentation" => "Specify whether this set of input captions appears in your outputs in both STL and Teletext format. If you choose Upconvert, MediaConvert includes the captions data in two ways: it passes the STL data through using the Teletext compatibility bytes fields of the Teletext wrapper, and it also translates the STL data into Teletext.", "smithy.api#jsonName" => "upconvertSTLToTeletext"}))
