    HlsGroupSettings.add_member(:additional_manifests, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofhlsadditionalmanifest, location_name: 'AdditionalManifests', traits: {"smithy.api#documentation" => "By default, the service creates one top-level .m3u8 HLS manifest for each HLS output group in your job. This default manifest references every output in the output group. To create additional top-level manifests that reference a subset of the outputs in the output group, specify a list of them here.", "smithy.api#jsonName" => "additionalManifests"}))
