    HlsGroupSettings.add_member(:caption_language_setting, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsCaptionLanguageSetting, location_name: 'CaptionLanguageSetting', traits: {"smithy.api#documentation" => "Applies only to 608 Embedded output captions. Insert: Include CLOSED-CAPTIONS lines in the manifest. Specify at least one language in the CC1 Language Code field. One CLOSED-CAPTION line is added for each Language Code you specify. Make sure to specify the languages in the order in which they appear in the original source (if the source is embedded format) or the order of the caption selectors (if the source is other than embedded). Otherwise, languages in the manifest will not match up properly with the output captions. None: Include CLOSED-CAPTIONS=NONE line in the manifest. Omit: Omit any CLOSED-CAPTIONS line from the manifest.", "smithy.api#jsonName" => "captionLanguageSetting"}))
    HlsGroupSettings.add_member(:caption_segment_length_control, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsCaptionSegmentLengthControl, location_name: 'CaptionSegmentLengthControl', traits: {"smithy.api#documentation" => "Set Caption segment length control to Match video to create caption segments that align with the video segments from the first video output in this output group. For example, if the video segments are 2 seconds long, your WebVTT segments will also be 2 seconds long. Keep the default setting, Large segments to create caption segments that are 300 seconds long.", "smithy.api#jsonName" => "captionSegmentLengthControl"}))
