    HlsGroupSettings.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3, location_name: 'Destination', traits: {"smithy.api#documentation" => "Use Destination to specify the S3 output location and the output filename base. Destination accepts format identifiers. If you do not specify the base filename in the URI, the service will use the filename of the input file. If your job has multiple inputs, the service uses the filename of the first input file.", "smithy.api#jsonName" => "destination"}))
    HlsGroupSettings.add_member(:destination_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DestinationSettings, location_name: 'DestinationSettings', traits: {"smithy.api#documentation" => "Settings associated with the destination. Will vary based on the type of destination", "smithy.api#jsonName" => "destinationSettings"}))
    HlsGroupSettings.add_member(:directory_structure, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsDirectoryStructure, location_name: 'DirectoryStructure', traits: {"smithy.api#documentation" => "Indicates whether segments should be placed in subdirectories.", "smithy.api#jsonName" => "directoryStructure"}))
    HlsGroupSettings.add_member(:encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsEncryptionSettings, location_name: 'Encryption', traits: {"smithy.api#documentation" => "DRM settings.", "smithy.api#jsonName" => "encryption"}))
    HlsGroupSettings.add_member(:image_based_trick_play, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsImageBasedTrickPlay, location_name: 'ImageBasedTrickPlay', traits: {"smithy.api#documentation" => "Specify whether MediaConvert generates images for trick play. Keep the default value, None, to not generate any images. Choose Thumbnail to generate tiled thumbnails. Choose Thumbnail and full frame to generate tiled thumbnails and full-resolution images of single frames. MediaConvert creates a child manifest for each set of images that you generate and adds corresponding entries to the parent manifest. A common application for these images is Roku trick mode. The thumbnails and full-frame images that MediaConvert creates with this feature are compatible with this Roku specification: https://developer.roku.com/docs/developer-program/media-playback/trick-mode/hls-and-dash.md", "smithy.api#jsonName" => "imageBasedTrickPlay"}))
    HlsGroupSettings.add_member(:image_based_trick_play_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsImageBasedTrickPlaySettings, location_name: 'ImageBasedTrickPlaySettings', traits: {"smithy.api#documentation" => "Tile and thumbnail settings applicable when imageBasedTrickPlay is ADVANCED", "smithy.api#jsonName" => "imageBasedTrickPlaySettings"}))
    HlsGroupSettings.add_member(:manifest_compression, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsManifestCompression, location_name: 'ManifestCompression', traits: {"smithy.api#documentation" => "When set to GZIP, compresses HLS playlist.", "smithy.api#jsonName" => "manifestCompression"}))
    HlsGroupSettings.add_member(:manifest_duration_format, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsManifestDurationFormat, location_name: 'ManifestDurationFormat', traits: {"smithy.api#documentation" => "Indicates whether the output manifest should use floating point values for segment duration.", "smithy.api#jsonName" => "manifestDurationFormat"}))
    HlsGroupSettings.add_member(:min_final_segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0max2147483647, location_name: 'MinFinalSegmentLength', traits: {"smithy.api#documentation" => "Keep this setting at the default value of 0, unless you are troubleshooting a problem with how devices play back the end of your video asset. If you know that player devices are hanging on the final segment of your video because the length of your final segment is too short, use this setting to specify a minimum final segment length, in seconds. Choose a value that is greater than or equal to 1 and less than your segment length. When you specify a value for this setting, the encoder will combine any final segment that is shorter than the length that you specify with the previous segment. For example, your segment length is 3 seconds and your final segment is .5 seconds without a minimum final segment length; when you set the minimum final segment length to 1, your final segment is 3.5 seconds.", "smithy.api#jsonName" => "minFinalSegmentLength"}))
    HlsGroupSettings.add_member(:min_segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'MinSegmentLength', traits: {"smithy.api#documentation" => "When set, Minimum Segment Size is enforced by looking ahead and back within the specified range for a nearby avail and extending the segment size if needed.", "smithy.api#jsonName" => "minSegmentLength"}))
    HlsGroupSettings.add_member(:output_selection, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsOutputSelection, location_name: 'OutputSelection', traits: {"smithy.api#documentation" => "Indicates whether the .m3u8 manifest file should be generated for this HLS output group.", "smithy.api#jsonName" => "outputSelection"}))
    HlsGroupSettings.add_member(:program_date_time, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsProgramDateTime, location_name: 'ProgramDateTime', traits: {"smithy.api#documentation" => "Includes or excludes EXT-X-PROGRAM-DATE-TIME tag in .m3u8 manifest files. The value is calculated as follows: either the program date and time are initialized using the input timecode source, or the time is initialized using the input timecode source and the date is initialized using the timestamp_offset.", "smithy.api#jsonName" => "programDateTime"}))
    HlsGroupSettings.add_member(:program_date_time_period, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max3600, location_name: 'ProgramDateTimePeriod', traits: {"smithy.api#documentation" => "Period of insertion of EXT-X-PROGRAM-DATE-TIME entry, in seconds.", "smithy.api#jsonName" => "programDateTimePeriod"}))
    HlsGroupSettings.add_member(:progressive_write_hls_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsProgressiveWriteHlsManifest, location_name: 'ProgressiveWriteHlsManifest', traits: {"smithy.api#documentation" => "Specify whether MediaConvert generates HLS manifests while your job is running or when your job is complete. To generate HLS manifests while your job is running: Choose Enabled. Use if you want to play back your content as soon as it's available. MediaConvert writes the parent and child manifests after the first three media segments are written to your destination S3 bucket. It then writes new updated manifests after each additional segment is written. The parent manifest includes the latest BANDWIDTH and AVERAGE-BANDWIDTH attributes, and child manifests include the latest available media segment. When your job completes, the final child playlists include an EXT-X-ENDLIST tag. To generate HLS manifests only when your job completes: Choose Disabled.", "smithy.api#jsonName" => "progressiveWriteHlsManifest"}))
    HlsGroupSettings.add_member(:segment_control, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsSegmentControl, location_name: 'SegmentControl', traits: {"smithy.api#documentation" => "When set to SINGLE_FILE, emits program as a single media resource (.ts) file, uses #EXT-X-BYTERANGE tags to index segment for playback.", "smithy.api#jsonName" => "segmentControl"}))
    HlsGroupSettings.add_member(:segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'SegmentLength', traits: {"smithy.api#documentation" => "Specify the length, in whole seconds, of each segment. When you don't specify a value, MediaConvert defaults to 10. Related settings: Use Segment length control to specify whether the encoder enforces this value strictly. Use Segment control to specify whether MediaConvert creates separate segment files or one content file that has metadata to mark the segment boundaries.", "smithy.api#jsonName" => "segmentLength"}))
    HlsGroupSettings.add_member(:segment_length_control, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsSegmentLengthControl, location_name: 'SegmentLengthControl', traits: {"smithy.api#documentation" => "Specify how you want MediaConvert to determine segment lengths in this output group. To use the exact value that you specify under Segment length: Choose Exact. Note that this might result in additional I-frames in the output GOP. To create segment lengths that are a multiple of the GOP: Choose Multiple of GOP. MediaConvert will round up the segment lengths to match the next GOP boundary. To have MediaConvert automatically determine a segment duration that is a multiple of both the audio packets and the frame rates: Choose Match. When you do, also specify a target segment duration under Segment length. This is useful for some ad-insertion or segment replacement workflows. Note that Match has the following requirements: - Output containers: Include at least one video output and at least one audio output. Audio-only outputs are not supported. - Output frame rate: Follow source is not supported. - Multiple output frame rates: When you specify multiple outputs, we recommend they share a similar frame rate (as in X/3, X/2, X, or 2X). For example: 5, 15, 30 and 60. Or: 25 and 50. (Outputs must share an integer multiple.) - Output audio codec: Specify Advanced Audio Coding (AAC). - Output sample rate: Choose 48kHz.", "smithy.api#jsonName" => "segmentLengthControl"}))
    HlsGroupSettings.add_member(:segments_per_subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'SegmentsPerSubdirectory', traits: {"smithy.api#documentation" => "Specify the number of segments to write to a subdirectory before starting a new one. You must also set Directory structure to Subdirectory per stream for this setting to have an effect.", "smithy.api#jsonName" => "segmentsPerSubdirectory"}))
    HlsGroupSettings.add_member(:stream_inf_resolution, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsStreamInfResolution, location_name: 'StreamInfResolution', traits: {"smithy.api#documentation" => "Include or exclude RESOLUTION attribute for video in EXT-X-STREAM-INF tag of variant manifest.", "smithy.api#jsonName" => "streamInfResolution"}))
    HlsGroupSettings.add_member(:target_duration_compatibility_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsTargetDurationCompatibilityMode, location_name: 'TargetDurationCompatibilityMode', traits: {"smithy.api#documentation" => "When set to LEGACY, the segment target duration is always rounded up to the nearest integer value above its current value in seconds. When set to SPEC\\\\_COMPLIANT, the segment target duration is rounded up to the nearest integer value if fraction seconds are greater than or equal to 0.5 (>= 0.5) and rounded down if less than 0.5 (< 0.5). You may need to use LEGACY if your client needs to ensure that the target duration is always longer than the actual duration of the segment. Some older players may experience interrupted playback when the actual duration of a track in a segment is longer than the target duration.", "smithy.api#jsonName" => "targetDurationCompatibilityMode"}))
    HlsGroupSettings.add_member(:timed_metadata_id3_frame, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsTimedMetadataId3Frame, location_name: 'TimedMetadataId3Frame', traits: {"smithy.api#documentation" => "Specify the type of the ID3 frame to use for ID3 timestamps in your output. To include ID3 timestamps: Specify PRIV or TDRL and set ID3 metadata to Passthrough. To exclude ID3 timestamps: Set ID3 timestamp frame type to None.", "smithy.api#jsonName" => "timedMetadataId3Frame"}))
    HlsGroupSettings.add_member(:timed_metadata_id3_period, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'TimedMetadataId3Period', traits: {"smithy.api#documentation" => "Specify the interval in seconds to write ID3 timestamps in your output. The first timestamp starts at the output timecode and date, and increases incrementally with each ID3 timestamp. To use the default interval of 10 seconds: Leave blank. To include this metadata in your output: Set ID3 timestamp frame type to PRIV or TDRL, and set ID3 metadata to Passthrough.", "smithy.api#jsonName" => "timedMetadataId3Period"}))
    HlsGroupSettings.add_member(:timestamp_delta_milliseconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'TimestampDeltaMilliseconds', traits: {"smithy.api#documentation" => "Provides an extra millisecond delta offset to fine tune the timestamps.", "smithy.api#jsonName" => "timestampDeltaMilliseconds"}))
