    HlsImageBasedTrickPlay.add_member(:thumbnail, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'THUMBNAIL', traits: {"smithy.api#enumValue" => "THUMBNAIL"}))
    HlsImageBasedTrickPlay.add_member(:thumbnail_and_fullframe, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'THUMBNAIL_AND_FULLFRAME', traits: {"smithy.api#enumValue" => "THUMBNAIL_AND_FULLFRAME"}))
    HlsImageBasedTrickPlay.add_member(:advanced, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ADVANCED', traits: {"smithy.api#enumValue" => "ADVANCED"}))
    HlsImageBasedTrickPlaySettings.add_member(:interval_cadence, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsIntervalCadence, location_name: 'IntervalCadence', traits: {"smithy.api#documentation" => "The cadence MediaConvert follows for generating thumbnails. If set to FOLLOW_IFRAME, MediaConvert generates thumbnails for each IDR frame in the output (matching the GOP cadence). If set to FOLLOW_CUSTOM, MediaConvert generates thumbnails according to the interval you specify in thumbnailInterval.", "smithy.api#jsonName" => "intervalCadence"}))
    HlsImageBasedTrickPlaySettings.add_member(:thumbnail_height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin2max4096, location_name: 'ThumbnailHeight', traits: {"smithy.api#documentation" => "Height of each thumbnail within each tile image, in pixels. Leave blank to maintain aspect ratio with thumbnail width. If following the aspect ratio would lead to a total tile height greater than 4096, then the job will be rejected. Must be divisible by 2.", "smithy.api#jsonName" => "thumbnailHeight"}))
    HlsImageBasedTrickPlaySettings.add_member(:thumbnail_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0max2147483647, location_name: 'ThumbnailInterval', traits: {"smithy.api#documentation" => "Enter the interval, in seconds, that MediaConvert uses to generate thumbnails. If the interval you enter doesn't align with the output frame rate, MediaConvert automatically rounds the interval to align with the output frame rate. For example, if the output frame rate is 29.97 frames per second and you enter 5, MediaConvert uses a 150 frame interval to generate thumbnails.", "smithy.api#jsonName" => "thumbnailInterval"}))
    HlsImageBasedTrickPlaySettings.add_member(:thumbnail_width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin8max4096, location_name: 'ThumbnailWidth', traits: {"smithy.api#documentation" => "Width of each thumbnail within each tile image, in pixels. Default is 312. Must be divisible by 8.", "smithy.api#jsonName" => "thumbnailWidth"}))
    HlsImageBasedTrickPlaySettings.add_member(:tile_height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2048, location_name: 'TileHeight', traits: {"smithy.api#documentation" => "Number of thumbnails in each column of a tile image. Set a value between 2 and 2048. Must be divisible by 2.", "smithy.api#jsonName" => "tileHeight"}))
    HlsImageBasedTrickPlaySettings.add_member(:tile_width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max512, location_name: 'TileWidth', traits: {"smithy.api#documentation" => "Number of thumbnails in each row of a tile image. Set a value between 1 and 512.", "smithy.api#jsonName" => "tileWidth"}))
    HlsImageBasedTrickPlaySettings.type = Types::HlsImageBasedTrickPlaySettings
