    HlsRenditionGroupSettings.add_member(:rendition_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RenditionGroupId', traits: {"smithy.api#documentation" => "Optional. Specify alternative group ID", "smithy.api#jsonName" => "renditionGroupId"}))
    HlsRenditionGroupSettings.add_member(:rendition_language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'RenditionLanguageCode', traits: {"smithy.api#documentation" => "Optional. Specify ISO 639-2 or ISO 639-3 code in the language property", "smithy.api#jsonName" => "renditionLanguageCode"}))
    HlsRenditionGroupSettings.add_member(:rendition_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RenditionName', traits: {"smithy.api#documentation" => "Optional. Specify media name", "smithy.api#jsonName" => "renditionName"}))
