    HlsSegmentLengthControl.add_member(:match, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MATCH', traits: {"smithy.api#enumValue" => "MATCH"}))
    HlsSettings.add_member(:audio_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AudioGroupId', traits: {"smithy.api#documentation" => "Specifies the group to which the audio rendition belongs.", "smithy.api#jsonName" => "audioGroupId"}))
    HlsSettings.add_member(:audio_only_container, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsAudioOnlyContainer, location_name: 'AudioOnlyContainer', traits: {"smithy.api#documentation" => "Use this setting only in audio-only outputs. Choose MPEG-2 Transport Stream (M2TS) to create a file in an MPEG2-TS container. Keep the default value Automatic to create an audio-only file in a raw container. Regardless of the value that you specify here, if this output has video, the service will place the output into an MPEG2-TS container.", "smithy.api#jsonName" => "audioOnlyContainer"}))
    HlsSettings.add_member(:audio_rendition_sets, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AudioRenditionSets', traits: {"smithy.api#documentation" => "List all the audio groups that are used with the video output stream. Input all the audio GROUP-IDs that are associated to the video, separate by ','.", "smithy.api#jsonName" => "audioRenditionSets"}))
    HlsSettings.add_member(:audio_track_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsAudioTrackType, location_name: 'AudioTrackType', traits: {"smithy.api#documentation" => "Four types of audio-only tracks are supported: Audio-Only Variant Stream The client can play back this audio-only stream instead of video in low-bandwidth scenarios. Represented as an EXT-X-STREAM-INF in the HLS manifest. Alternate Audio, Auto Select, Default Alternate rendition that the client should try to play back by default. Represented as an EXT-X-MEDIA in the HLS manifest with DEFAULT=YES, AUTOSELECT=YES Alternate Audio, Auto Select, Not Default Alternate rendition that the client may try to play back by default. Represented as an EXT-X-MEDIA in the HLS manifest with DEFAULT=NO, AUTOSELECT=YES Alternate Audio, not Auto Select Alternate rendition that the client will not try to play back by default. Represented as an EXT-X-MEDIA in the HLS manifest with DEFAULT=NO, AUTOSELECT=NO", "smithy.api#jsonName" => "audioTrackType"}))
    HlsSettings.add_member(:descriptive_video_service_flag, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsDescriptiveVideoServiceFlag, location_name: 'DescriptiveVideoServiceFlag', traits: {"smithy.api#documentation" => "Specify whether to flag this audio track as descriptive video service (DVS) in your HLS parent manifest. When you choose Flag, MediaConvert includes the parameter CHARACTERISTICS=\"public.accessibility.describes-video\" in the EXT-X-MEDIA entry for this track. When you keep the default choice, Don't flag, MediaConvert leaves this parameter out. The DVS flag can help with accessibility on Apple devices. For more information, see the Apple documentation.", "smithy.api#jsonName" => "descriptiveVideoServiceFlag"}))
    HlsSettings.add_member(:i_frame_only_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsIFrameOnlyManifest, location_name: 'IFrameOnlyManifest', traits: {"smithy.api#documentation" => "Choose Include to have MediaConvert generate a child manifest that lists only the I-frames for this rendition, in addition to your regular manifest for this rendition. You might use this manifest as part of a workflow that creates preview functions for your video. MediaConvert adds both the I-frame only child manifest and the regular child manifest to the parent manifest. When you don't need the I-frame only child manifest, keep the default value Exclude.", "smithy.api#jsonName" => "iFrameOnlyManifest"}))
    HlsSettings.add_member(:segment_modifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SegmentModifier', traits: {"smithy.api#documentation" => "Use this setting to add an identifying string to the filename of each segment. The service adds this string between the name modifier and segment index number. You can use format identifiers in the string. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/using-variables-in-your-job-settings.html", "smithy.api#jsonName" => "segmentModifier"}))
