    HlsTimedMetadataId3Frame.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
    HlsTimedMetadataId3Frame.add_member(:priv, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PRIV', traits: {"smithy.api#enumValue" => "PRIV"}))
    HlsTimedMetadataId3Frame.add_member(:tdrl, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TDRL', traits: {"smithy.api#enumValue" => "TDRL"}))
    HopDestination.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative50max50, location_name: 'Priority', traits: {"smithy.api#documentation" => "Optional. When you set up a job to use queue hopping, you can specify a different relative priority for the job in the destination queue. If you don't specify, the relative priority will remain the same as in the previous queue.", "smithy.api#jsonName" => "priority"}))
    HopDestination.add_member(:queue, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Queue', traits: {"smithy.api#documentation" => "Optional unless the job is submitted on the default queue. When you set up a job to use queue hopping, you can specify a destination queue. This queue cannot be the original queue to which the job is submitted. If the original queue isn't the default queue and you don't specify the destination queue, the job will move to the default queue.", "smithy.api#jsonName" => "queue"}))
    HopDestination.add_member(:wait_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'WaitMinutes', traits: {"smithy.api#documentation" => "Required for setting up a job to use queue hopping. Minimum wait time in minutes until the job can hop to the destination queue. Valid range is 1 to 4320 minutes, inclusive.", "smithy.api#jsonName" => "waitMinutes"}))
    HopDestination.type = Types::HopDestination
    Id3Insertion.add_member(:id3, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatternazaz0902, location_name: 'Id3', traits: {"smithy.api#documentation" => "Use ID3 tag to provide a fully formed ID3 tag in base64-encode format.", "smithy.api#jsonName" => "id3"}))
    Id3Insertion.add_member(:timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092, location_name: 'Timecode', traits: {"smithy.api#documentation" => "Provide a Timecode in HH:MM:SS:FF or HH:MM:SS;FF format.", "smithy.api#jsonName" => "timecode"}))
    Id3Insertion.type = Types::Id3Insertion
    ImageInserter.add_member(:insertable_images, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofinsertableimage, location_name: 'InsertableImages', traits: {"smithy.api#documentation" => "Specify the images that you want to overlay on your video. The images must be PNG or TGA files.", "smithy.api#jsonName" => "insertableImages"}))
    ImageInserter.add_member(:sdr_reference_white_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin100max1000, location_name: 'SdrReferenceWhiteLevel', traits: {"smithy.api#documentation" => "Specify the reference white level, in nits, for all of your image inserter images. Use to correct brightness levels within HDR10 outputs. For 1,000 nit peak brightness displays, we recommend that you set SDR reference white level to 203 (according to ITU-R BT.2408). Leave blank to use the default value of 100, or specify an integer from 100 to 1000.", "smithy.api#jsonName" => "sdrReferenceWhiteLevel"}))
    ImageInserter.type = Types::ImageInserter
    ImscAccessibilitySubs.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    ImscAccessibilitySubs.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    ImscDestinationSettings.add_member(:accessibility, Smithy::Schema::Shapes::ShapeRef.new(shape: ImscAccessibilitySubs, location_name: 'Accessibility', traits: {"smithy.api#documentation" => "If the IMSC captions track is intended to provide accessibility for people who are deaf or hard of hearing: Set Accessibility subtitles to Enabled. When you do, MediaConvert adds accessibility attributes to your output HLS or DASH manifest. For HLS manifests, MediaConvert adds the following accessibility attributes under EXT-X-MEDIA for this track: CHARACTERISTICS=\"public.accessibility.describes-spoken-dialog,public.accessibility.describes-music-and-sound\" and AUTOSELECT=\"YES\". For DASH manifests, MediaConvert adds the following in the adaptation set for this track: <Accessibility schemeIdUri=\"urn:mpeg:dash:role:2011\" value=\"caption\"/>. If the captions track is not intended to provide such accessibility: Keep the default value, Disabled. When you do, for DASH manifests, MediaConvert instead adds the following in the adaptation set for this track: <Role schemeIDUri=\"urn:mpeg:dash:role:2011\" value=\"subtitle\"/>.", "smithy.api#jsonName" => "accessibility"}))
    ImscDestinationSettings.add_member(:style_passthrough, Smithy::Schema::Shapes::ShapeRef.new(shape: ImscStylePassthrough, location_name: 'StylePassthrough', traits: {"smithy.api#documentation" => "Keep this setting enabled to have MediaConvert use the font style and position information from the captions source in the output. This option is available only when your input captions are IMSC, SMPTE-TT, or TTML. Disable this setting for simplified output captions.", "smithy.api#jsonName" => "stylePassthrough"}))
    ImscDestinationSettings.type = Types::ImscDestinationSettings
    ImscStylePassthrough.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    ImscStylePassthrough.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    Input.add_member(:advanced_input_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedInputFilter, location_name: 'AdvancedInputFilter', traits: {"smithy.api#documentation" => "Use to remove noise, blocking, blurriness, or ringing from your input as a pre-filter step before encoding. The Advanced input filter removes more types of compression artifacts and is an improvement when compared to basic Deblock and Denoise filters. To remove video compression artifacts from your input and improve the video quality: Choose Enabled. Additionally, this filter can help increase the video quality of your output relative to its bitrate, since noisy inputs are more complex and require more bits to encode. To help restore loss of detail after applying the filter, you can optionally add texture or sharpening as an additional step. Jobs that use this feature incur pro-tier pricing. To not apply advanced input filtering: Choose Disabled. Note that you can still apply basic filtering with Deblock and Denoise.", "smithy.api#jsonName" => "advancedInputFilter"}))
    Input.add_member(:advanced_input_filter_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedInputFilterSettings, location_name: 'AdvancedInputFilterSettings', traits: {"smithy.api#documentation" => "Optional settings for Advanced input filter when you set Advanced input filter to Enabled.", "smithy.api#jsonName" => "advancedInputFilterSettings"}))
    Input.add_member(:audio_selector_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofaudioselectorgroup, location_name: 'AudioSelectorGroups', traits: {"smithy.api#documentation" => "Use audio selector groups to combine multiple sidecar audio inputs so that you can assign them to a single output audio tab. Note that, if you're working with embedded audio, it's simpler to assign multiple input tracks into a single audio selector rather than use an audio selector group.", "smithy.api#jsonName" => "audioSelectorGroups"}))
    Input.add_member(:audio_selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofaudioselector, location_name: 'AudioSelectors', traits: {"smithy.api#documentation" => "Use Audio selectors to specify a track or set of tracks from the input that you will use in your outputs. You can use multiple Audio selectors per input.", "smithy.api#jsonName" => "audioSelectors"}))
    Input.add_member(:caption_selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofcaptionselector, location_name: 'CaptionSelectors', traits: {"smithy.api#documentation" => "Use captions selectors to specify the captions data from your input that you use in your outputs. You can use up to 100 captions selectors per input.", "smithy.api#jsonName" => "captionSelectors"}))
    Input.add_member(:crop, Smithy::Schema::Shapes::ShapeRef.new(shape: Rectangle, location_name: 'Crop', traits: {"smithy.api#documentation" => "Use Cropping selection to specify the video area that the service will include in the output video frame. If you specify a value here, it will override any value that you specify in the output setting Cropping selection.", "smithy.api#jsonName" => "crop"}))
    Input.add_member(:deblock_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDeblockFilter, location_name: 'DeblockFilter', traits: {"smithy.api#documentation" => "Enable Deblock to produce smoother motion in the output. Default is disabled. Only manually controllable for MPEG2 and uncompressed video inputs.", "smithy.api#jsonName" => "deblockFilter"}))
    Input.add_member(:decryption_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDecryptionSettings, location_name: 'DecryptionSettings', traits: {"smithy.api#documentation" => "Settings for decrypting any input files that you encrypt before you upload them to Amazon S3. MediaConvert can decrypt files only when you use AWS Key Management Service (KMS) to encrypt the data key that you use to encrypt your content.", "smithy.api#jsonName" => "decryptionSettings"}))
    Input.add_member(:denoise_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDenoiseFilter, location_name: 'DenoiseFilter', traits: {"smithy.api#documentation" => "Enable Denoise to filter noise from the input. Default is disabled. Only applicable to MPEG2, H.264, H.265, and uncompressed video inputs.", "smithy.api#jsonName" => "denoiseFilter"}))
    Input.add_member(:dolby_vision_metadata_xml, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin14patterns3xmlxmlhttpsxmlxml, location_name: 'DolbyVisionMetadataXml', traits: {"smithy.api#documentation" => "Use this setting only when your video source has Dolby Vision studio mastering metadata that is carried in a separate XML file. Specify the Amazon S3 location for the metadata XML file. MediaConvert uses this file to provide global and frame-level metadata for Dolby Vision preprocessing. When you specify a file here and your input also has interleaved global and frame level metadata, MediaConvert ignores the interleaved metadata and uses only the the metadata from this external XML file. Note that your IAM service role must grant MediaConvert read permissions to this file. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/iam-role.html.", "smithy.api#jsonName" => "dolbyVisionMetadataXml"}))
    Input.add_member(:dynamic_audio_selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofdynamicaudioselector, location_name: 'DynamicAudioSelectors', traits: {"smithy.api#documentation" => "Use Dynamic audio selectors when you do not know the track layout of your source when you submit your job, but want to select multiple audio tracks. When you include an audio track in your output and specify this Dynamic audio selector as the Audio source, MediaConvert creates an output audio track for each dynamically selected track. Note that when you include a Dynamic audio selector for two or more inputs, each input must have the same number of audio tracks and audio channels.", "smithy.api#jsonName" => "dynamicAudioSelectors"}))
    Input.add_member(:file_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmax2048patterns3https, location_name: 'FileInput', traits: {"smithy.api#documentation" => "Specify the source file for your transcoding job. You can use multiple inputs in a single job. The service concatenates these inputs, in the order that you specify them in the job, to create the outputs. For standard inputs, provide the path to your S3, HTTP, or HTTPS source file. For example, s3://amzn-s3-demo-bucket/input.mp4 for an Amazon S3 input or https://example.com/input.mp4 for an HTTPS input. For TAMS inputs, specify the HTTPS endpoint of your TAMS server. For example, https://tams-server.example.com . When you do, also specify Source ID, Timerange, GAP handling, and the Authorization connection ARN under TAMS settings. (Don't include these parameters in the Input file URL.) For IMF inputs, specify your input by providing the path to your CPL. For example, s3://amzn-s3-demo-bucket/vf/cpl.xml . If the CPL is in an incomplete IMP, make sure to use Supplemental IMPsto specify any supplemental IMPs that contain assets referenced by the CPL.", "smithy.api#jsonName" => "fileInput"}))
    Input.add_member(:filter_enable, Smithy::Schema::Shapes::ShapeRef.new(shape: InputFilterEnable, location_name: 'FilterEnable', traits: {"smithy.api#documentation" => "Specify whether to apply input filtering to improve the video quality of your input. To apply filtering depending on your input type and quality: Choose Auto. To apply no filtering: Choose Disable. To apply filtering regardless of your input type and quality: Choose Force. When you do, you must also specify a value for Filter strength.", "smithy.api#jsonName" => "filterEnable"}))
    Input.add_member(:filter_strength, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max5, location_name: 'FilterStrength', traits: {"smithy.api#documentation" => "Specify the strength of the input filter. To apply an automatic amount of filtering based the compression artifacts measured in your input: We recommend that you leave Filter strength blank and set Filter enable to Auto. To manually apply filtering: Enter a value from 1 to 5, where 1 is the least amount of filtering and 5 is the most. The value that you enter applies to the strength of the Deblock or Denoise filters, or to the strength of the Advanced input filter.", "smithy.api#jsonName" => "filterStrength"}))
    Input.add_member(:image_inserter, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageInserter, location_name: 'ImageInserter', traits: {"smithy.api#documentation" => "Enable the image inserter feature to include a graphic overlay on your video. Enable or disable this feature for each input individually. This setting is disabled by default.", "smithy.api#jsonName" => "imageInserter"}))
    Input.add_member(:input_clippings, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofinputclipping, location_name: 'InputClippings', traits: {"smithy.api#documentation" => "Contains sets of start and end times that together specify a portion of the input to be used in the outputs. If you provide only a start time, the clip will be the entire input from that point to the end. If you provide only an end time, it will be the entire input up to that point. When you specify more than one input clip, the transcoding service creates the job outputs by stringing the clips together in the order you specify them.", "smithy.api#jsonName" => "inputClippings"}))
    Input.add_member(:input_scan_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InputScanType, location_name: 'InputScanType', traits: {"smithy.api#documentation" => "When you have a progressive segmented frame (PsF) input, use this setting to flag the input as PsF. MediaConvert doesn't automatically detect PsF. Therefore, flagging your input as PsF results in better preservation of video quality when you do deinterlacing and frame rate conversion. If you don't specify, the default value is Auto. Auto is the correct setting for all inputs that are not PsF. Don't set this value to PsF when your input is interlaced. Doing so creates horizontal interlacing artifacts.", "smithy.api#jsonName" => "inputScanType"}))
    Input.add_member(:position, Smithy::Schema::Shapes::ShapeRef.new(shape: Rectangle, location_name: 'Position', traits: {"smithy.api#documentation" => "Use Selection placement to define the video area in your output frame. The area outside of the rectangle that you specify here is black. If you specify a value here, it will override any value that you specify in the output setting Selection placement. If you specify a value here, this will override any AFD values in your input, even if you set Respond to AFD to Respond. If you specify a value here, this will ignore anything that you specify for the setting Scaling Behavior.", "smithy.api#jsonName" => "position"}))
    Input.add_member(:program_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'ProgramNumber', traits: {"smithy.api#documentation" => "Use Program to select a specific program from within a multi-program transport stream. Note that Quad 4K is not currently supported. Default is the first program within the transport stream. If the program you specify doesn't exist, the transcoding service will use this default.", "smithy.api#jsonName" => "programNumber"}))
    Input.add_member(:psi_control, Smithy::Schema::Shapes::ShapeRef.new(shape: InputPsiControl, location_name: 'PsiControl', traits: {"smithy.api#documentation" => "Set PSI control for transport stream inputs to specify which data the demux process to scans.\n* Ignore PSI - Scan all PIDs for audio and video.\n* Use PSI - Scan only PSI data.", "smithy.api#jsonName" => "psiControl"}))
    Input.add_member(:supplemental_imps, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofStringpatterns3assetmapxml, location_name: 'SupplementalImps', traits: {"smithy.api#documentation" => "Provide a list of any necessary supplemental IMPs. You need supplemental IMPs if the CPL that you're using for your input is in an incomplete IMP. Specify either the supplemental IMP directories with a trailing slash or the ASSETMAP.xml files. For example [\"s3://bucket/ov/\", \"s3://bucket/vf2/ASSETMAP.xml\"]. You don't need to specify the IMP that contains your input CPL, because the service automatically detects it.", "smithy.api#jsonName" => "supplementalImps"}))
    Input.add_member(:tams_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTamsSettings, location_name: 'TamsSettings', traits: {"smithy.api#documentation" => "Specify a Time Addressable Media Store (TAMS) server as an input source. TAMS is an open-source API specification that provides access to time-segmented media content. Use TAMS to retrieve specific time ranges from live or archived media streams. When you specify TAMS settings, MediaConvert connects to your TAMS server, retrieves the media segments for your specified time range, and processes them as a single input. This enables workflows like extracting clips from live streams or processing specific portions of archived content. To use TAMS, you must: 1. Have access to a TAMS-compliant server 2. Specify the server URL in the Input file URL field 3. Provide the required SourceId and Timerange parameters 4. Configure authentication, if your TAMS server requires it", "smithy.api#jsonName" => "tamsSettings"}))
    Input.add_member(:timecode_source, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTimecodeSource, location_name: 'TimecodeSource', traits: {"smithy.api#documentation" => "Use this Timecode source setting, located under the input settings, to specify how the service counts input video frames. This input frame count affects only the behavior of features that apply to a single input at a time, such as input clipping and synchronizing some captions formats. Choose Embedded to use the timecodes in your input video. Choose Start at zero to start the first frame at zero. Choose Specified start to start the first frame at the timecode that you specify in the setting Start timecode. If you don't specify a value for Timecode source, the service will use Embedded by default. For more information about timecodes, see https://docs.aws.amazon.com/console/mediaconvert/timecode.", "smithy.api#jsonName" => "timecodeSource"}))
    Input.add_member(:timecode_start, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin11max11pattern01d20305d205d, location_name: 'TimecodeStart', traits: {"smithy.api#documentation" => "Specify the timecode that you want the service to use for this input's initial frame. To use this setting, you must set the Timecode source setting, located under the input settings, to Specified start. For more information about timecodes, see https://docs.aws.amazon.com/console/mediaconvert/timecode.", "smithy.api#jsonName" => "timecodeStart"}))
    Input.add_member(:video_generator, Smithy::Schema::Shapes::ShapeRef.new(shape: InputVideoGenerator, location_name: 'VideoGenerator', traits: {"smithy.api#documentation" => "When you include Video generator, MediaConvert creates a video input with black frames. Use this setting if you do not have a video input or if you want to add black video frames before, or after, other inputs. You can specify Video generator, or you can specify an Input file, but you cannot specify both. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/video-generator.html", "smithy.api#jsonName" => "videoGenerator"}))
    Input.add_member(:video_overlays, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofvideooverlay, location_name: 'VideoOverlays', traits: {"smithy.api#documentation" => "Contains an array of video overlays.", "smithy.api#jsonName" => "videoOverlays"}))
    Input.add_member(:video_selector, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoSelector, location_name: 'VideoSelector', traits: {"smithy.api#documentation" => "Input video selectors contain the video settings for the input. Each of your inputs can have up to one video selector.", "smithy.api#jsonName" => "videoSelector"}))
    Input.type = Types::Input
    InputClipping.add_member(:end_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092090909, location_name: 'EndTimecode', traits: {"smithy.api#documentation" => "Set End timecode to the end of the portion of the input you are clipping. The frame corresponding to the End timecode value is included in the clip. Start timecode or End timecode may be left blank, but not both. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When choosing this value, take into account your setting for timecode source under input settings. For example, if you have embedded timecodes that start at 01:00:00:00 and you want your clip to end six minutes into the video, use 01:06:00:00.", "smithy.api#jsonName" => "endTimecode"}))
    InputClipping.add_member(:start_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092090909, location_name: 'StartTimecode', traits: {"smithy.api#documentation" => "Set Start timecode to the beginning of the portion of the input you are clipping. The frame corresponding to the Start timecode value is included in the clip. Start timecode or End timecode may be left blank, but not both. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When choosing this value, take into account your setting for Input timecode source. For example, if you have embedded timecodes that start at 01:00:00:00 and you want your clip to begin five minutes into the video, use 01:05:00:00.", "smithy.api#jsonName" => "startTimecode"}))
    InputClipping.type = Types::InputClipping
    InputDeblockFilter.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    InputDeblockFilter.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    InputDecryptionSettings.add_member(:decryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DecryptionMode, location_name: 'DecryptionMode', traits: {"smithy.api#documentation" => "Specify the encryption mode that you used to encrypt your input files.", "smithy.api#jsonName" => "decryptionMode"}))
    InputDecryptionSettings.add_member(:encrypted_decryption_key, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin24max512patternazaz0902, location_name: 'EncryptedDecryptionKey', traits: {"smithy.api#documentation" => "Warning! Don't provide your encryption key in plaintext. Your job settings could be intercepted, making your encrypted content vulnerable. Specify the encrypted version of the data key that you used to encrypt your content. The data key must be encrypted by AWS Key Management Service (KMS). The key can be 128, 192, or 256 bits.", "smithy.api#jsonName" => "encryptedDecryptionKey"}))
    InputDecryptionSettings.add_member(:initialization_vector, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin16max24patternazaz0922azaz0916, location_name: 'InitializationVector', traits: {"smithy.api#documentation" => "Specify the initialization vector that you used when you encrypted your content before uploading it to Amazon S3. You can use a 16-byte initialization vector with any encryption mode. Or, you can use a 12-byte initialization vector with GCM or CTR. MediaConvert accepts only initialization vectors that are base64-encoded.", "smithy.api#jsonName" => "initializationVector"}))
    InputDecryptionSettings.add_member(:kms_key_region, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin9max19patternaz26eastwestcentralnorthsoutheastwest1912, location_name: 'KmsKeyRegion', traits: {"smithy.api#documentation" => "Specify the AWS Region for AWS Key Management Service (KMS) that you used to encrypt your data key, if that Region is different from the one you are using for AWS Elemental MediaConvert.", "smithy.api#jsonName" => "kmsKeyRegion"}))
    InputDecryptionSettings.type = Types::InputDecryptionSettings
    InputDenoiseFilter.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    InputDenoiseFilter.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    InputFilterEnable.add_member(:auto, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AUTO', traits: {"smithy.api#enumValue" => "AUTO"}))
    InputFilterEnable.add_member(:disable, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLE', traits: {"smithy.api#enumValue" => "DISABLE"}))
    InputFilterEnable.add_member(:force, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FORCE', traits: {"smithy.api#enumValue" => "FORCE"}))
    InputPolicy.add_member(:allowed, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ALLOWED', traits: {"smithy.api#enumValue" => "ALLOWED"}))
    InputPolicy.add_member(:disallowed, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISALLOWED', traits: {"smithy.api#enumValue" => "DISALLOWED"}))
    InputPsiControl.add_member(:ignore_psi, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'IGNORE_PSI', traits: {"smithy.api#enumValue" => "IGNORE_PSI"}))
    InputPsiControl.add_member(:use_psi, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'USE_PSI', traits: {"smithy.api#enumValue" => "USE_PSI"}))
    InputRotate.add_member(:degree_0, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DEGREE_0', traits: {"smithy.api#enumValue" => "DEGREE_0"}))
    InputRotate.add_member(:degrees_90, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DEGREES_90', traits: {"smithy.api#enumValue" => "DEGREES_90"}))
    InputRotate.add_member(:degrees_180, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DEGREES_180', traits: {"smithy.api#enumValue" => "DEGREES_180"}))
    InputRotate.add_member(:degrees_270, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DEGREES_270', traits: {"smithy.api#enumValue" => "DEGREES_270"}))
    InputRotate.add_member(:auto, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AUTO', traits: {"smithy.api#enumValue" => "AUTO"}))
    InputSampleRange.add_member(:follow, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FOLLOW', traits: {"smithy.api#enumValue" => "FOLLOW"}))
    InputSampleRange.add_member(:full_range, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FULL_RANGE', traits: {"smithy.api#enumValue" => "FULL_RANGE"}))
    InputSampleRange.add_member(:limited_range, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LIMITED_RANGE', traits: {"smithy.api#enumValue" => "LIMITED_RANGE"}))
    InputScanType.add_member(:auto, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AUTO', traits: {"smithy.api#enumValue" => "AUTO"}))
    InputScanType.add_member(:psf, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PSF', traits: {"smithy.api#enumValue" => "PSF"}))
    InputTamsSettings.add_member(:auth_connection_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatternarnawsaz09eventsaz090912connectionazaz09af0936, location_name: 'AuthConnectionArn', traits: {"smithy.api#documentation" => "Specify the ARN (Amazon Resource Name) of an EventBridge Connection to authenticate with your TAMS server. The EventBridge Connection stores your authentication credentials securely. MediaConvert assumes your job's IAM role to access this connection, so ensure the role has the events:RetrieveConnectionCredentials, secretsmanager:DescribeSecret, and secretsmanager:GetSecretValue permissions. Format: arn:aws:events:region:account-id:connection/connection-name/unique-id", "smithy.api#jsonName" => "authConnectionArn"}))
    InputTamsSettings.add_member(:gap_handling, Smithy::Schema::Shapes::ShapeRef.new(shape: TamsGapHandling, location_name: 'GapHandling', traits: {"smithy.api#documentation" => "Specify how MediaConvert handles gaps between media segments in your TAMS source. Gaps can occur in live streams due to network issues or other interruptions. Choose from the following options: * Skip gaps - Default. Skip over gaps and join segments together. This creates a continuous output with no blank frames, but may cause timeline discontinuities. * Fill with black - Insert black frames to fill gaps between segments. This maintains timeline continuity but adds black frames where content is missing. * Hold last frame - Repeat the last frame before a gap until the next segment begins. This maintains visual continuity during gaps.", "smithy.api#jsonName" => "gapHandling"}))
    InputTamsSettings.add_member(:source_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceId', traits: {"smithy.api#documentation" => "Specify the unique identifier for the media source in your TAMS server. MediaConvert uses this source ID to locate the appropriate flows containing the media segments you want to process. The source ID corresponds to a specific media source registered in your TAMS server. This source must be of type urn:x-nmos:format:multi, and can can reference multiple flows for audio, video, or combined audio/video content. MediaConvert automatically selects the highest quality flows available for your job. This setting is required when include TAMS settings in your job.", "smithy.api#jsonName" => "sourceId"}))
    InputTamsSettings.add_member(:timerange, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern019090190908019090190908, location_name: 'Timerange', traits: {"smithy.api#documentation" => "Specify the time range of media segments to retrieve from your TAMS server. MediaConvert fetches only the segments that fall within this range. Use the format specified by your TAMS server implementation. This must be two timestamp values with the format {sign?}{seconds}:{nanoseconds}, separated by an underscore, surrounded by either parentheses or square brackets.  Example: [15:0_35:0) This setting is required when include TAMS settings in your job.", "smithy.api#jsonName" => "timerange"}))
    InputTamsSettings.type = Types::InputTamsSettings
    InputTemplate.add_member(:advanced_input_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedInputFilter, location_name: 'AdvancedInputFilter', traits: {"smithy.api#documentation" => "Use to remove noise, blocking, blurriness, or ringing from your input as a pre-filter step before encoding. The Advanced input filter removes more types of compression artifacts and is an improvement when compared to basic Deblock and Denoise filters. To remove video compression artifacts from your input and improve the video quality: Choose Enabled. Additionally, this filter can help increase the video quality of your output relative to its bitrate, since noisy inputs are more complex and require more bits to encode. To help restore loss of detail after applying the filter, you can optionally add texture or sharpening as an additional step. Jobs that use this feature incur pro-tier pricing. To not apply advanced input filtering: Choose Disabled. Note that you can still apply basic filtering with Deblock and Denoise.", "smithy.api#jsonName" => "advancedInputFilter"}))
    InputTemplate.add_member(:advanced_input_filter_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedInputFilterSettings, location_name: 'AdvancedInputFilterSettings', traits: {"smithy.api#documentation" => "Optional settings for Advanced input filter when you set Advanced input filter to Enabled.", "smithy.api#jsonName" => "advancedInputFilterSettings"}))
    InputTemplate.add_member(:audio_selector_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofaudioselectorgroup, location_name: 'AudioSelectorGroups', traits: {"smithy.api#documentation" => "Use audio selector groups to combine multiple sidecar audio inputs so that you can assign them to a single output audio tab. Note that, if you're working with embedded audio, it's simpler to assign multiple input tracks into a single audio selector rather than use an audio selector group.", "smithy.api#jsonName" => "audioSelectorGroups"}))
    InputTemplate.add_member(:audio_selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofaudioselector, location_name: 'AudioSelectors', traits: {"smithy.api#documentation" => "Use Audio selectors to specify a track or set of tracks from the input that you will use in your outputs. You can use multiple Audio selectors per input.", "smithy.api#jsonName" => "audioSelectors"}))
    InputTemplate.add_member(:caption_selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofcaptionselector, location_name: 'CaptionSelectors', traits: {"smithy.api#documentation" => "Use captions selectors to specify the captions data from your input that you use in your outputs. You can use up to 100 captions selectors per input.", "smithy.api#jsonName" => "captionSelectors"}))
    InputTemplate.add_member(:crop, Smithy::Schema::Shapes::ShapeRef.new(shape: Rectangle, location_name: 'Crop', traits: {"smithy.api#documentation" => "Use Cropping selection to specify the video area that the service will include in the output video frame. If you specify a value here, it will override any value that you specify in the output setting Cropping selection.", "smithy.api#jsonName" => "crop"}))
    InputTemplate.add_member(:deblock_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDeblockFilter, location_name: 'DeblockFilter', traits: {"smithy.api#documentation" => "Enable Deblock to produce smoother motion in the output. Default is disabled. Only manually controllable for MPEG2 and uncompressed video inputs.", "smithy.api#jsonName" => "deblockFilter"}))
    InputTemplate.add_member(:denoise_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDenoiseFilter, location_name: 'DenoiseFilter', traits: {"smithy.api#documentation" => "Enable Denoise to filter noise from the input. Default is disabled. Only applicable to MPEG2, H.264, H.265, and uncompressed video inputs.", "smithy.api#jsonName" => "denoiseFilter"}))
    InputTemplate.add_member(:dolby_vision_metadata_xml, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin14patterns3xmlxmlhttpsxmlxml, location_name: 'DolbyVisionMetadataXml', traits: {"smithy.api#documentation" => "Use this setting only when your video source has Dolby Vision studio mastering metadata that is carried in a separate XML file. Specify the Amazon S3 location for the metadata XML file. MediaConvert uses this file to provide global and frame-level metadata for Dolby Vision preprocessing. When you specify a file here and your input also has interleaved global and frame level metadata, MediaConvert ignores the interleaved metadata and uses only the the metadata from this external XML file. Note that your IAM service role must grant MediaConvert read permissions to this file. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/iam-role.html.", "smithy.api#jsonName" => "dolbyVisionMetadataXml"}))
    InputTemplate.add_member(:dynamic_audio_selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: Mapofdynamicaudioselector, location_name: 'DynamicAudioSelectors', traits: {"smithy.api#documentation" => "Use Dynamic audio selectors when you do not know the track layout of your source when you submit your job, but want to select multiple audio tracks. When you include an audio track in your output and specify this Dynamic audio selector as the Audio source, MediaConvert creates an output audio track for each dynamically selected track. Note that when you include a Dynamic audio selector for two or more inputs, each input must have the same number of audio tracks and audio channels.", "smithy.api#jsonName" => "dynamicAudioSelectors"}))
    InputTemplate.add_member(:filter_enable, Smithy::Schema::Shapes::ShapeRef.new(shape: InputFilterEnable, location_name: 'FilterEnable', traits: {"smithy.api#documentation" => "Specify whether to apply input filtering to improve the video quality of your input. To apply filtering depending on your input type and quality: Choose Auto. To apply no filtering: Choose Disable. To apply filtering regardless of your input type and quality: Choose Force. When you do, you must also specify a value for Filter strength.", "smithy.api#jsonName" => "filterEnable"}))
    InputTemplate.add_member(:filter_strength, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max5, location_name: 'FilterStrength', traits: {"smithy.api#documentation" => "Specify the strength of the input filter. To apply an automatic amount of filtering based the compression artifacts measured in your input: We recommend that you leave Filter strength blank and set Filter enable to Auto. To manually apply filtering: Enter a value from 1 to 5, where 1 is the least amount of filtering and 5 is the most. The value that you enter applies to the strength of the Deblock or Denoise filters, or to the strength of the Advanced input filter.", "smithy.api#jsonName" => "filterStrength"}))
    InputTemplate.add_member(:image_inserter, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageInserter, location_name: 'ImageInserter', traits: {"smithy.api#documentation" => "Enable the image inserter feature to include a graphic overlay on your video. Enable or disable this feature for each input individually. This setting is disabled by default.", "smithy.api#jsonName" => "imageInserter"}))
    InputTemplate.add_member(:input_clippings, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofinputclipping, location_name: 'InputClippings', traits: {"smithy.api#documentation" => "Contains sets of start and end times that together specify a portion of the input to be used in the outputs. If you provide only a start time, the clip will be the entire input from that point to the end. If you provide only an end time, it will be the entire input up to that point. When you specify more than one input clip, the transcoding service creates the job outputs by stringing the clips together in the order you specify them.", "smithy.api#jsonName" => "inputClippings"}))
    InputTemplate.add_member(:input_scan_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InputScanType, location_name: 'InputScanType', traits: {"smithy.api#documentation" => "When you have a progressive segmented frame (PsF) input, use this setting to flag the input as PsF. MediaConvert doesn't automatically detect PsF. Therefore, flagging your input as PsF results in better preservation of video quality when you do deinterlacing and frame rate conversion. If you don't specify, the default value is Auto. Auto is the correct setting for all inputs that are not PsF. Don't set this value to PsF when your input is interlaced. Doing so creates horizontal interlacing artifacts.", "smithy.api#jsonName" => "inputScanType"}))
    InputTemplate.add_member(:position, Smithy::Schema::Shapes::ShapeRef.new(shape: Rectangle, location_name: 'Position', traits: {"smithy.api#documentation" => "Use Selection placement to define the video area in your output frame. The area outside of the rectangle that you specify here is black. If you specify a value here, it will override any value that you specify in the output setting Selection placement. If you specify a value here, this will override any AFD values in your input, even if you set Respond to AFD to Respond. If you specify a value here, this will ignore anything that you specify for the setting Scaling Behavior.", "smithy.api#jsonName" => "position"}))
    InputTemplate.add_member(:program_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'ProgramNumber', traits: {"smithy.api#documentation" => "Use Program to select a specific program from within a multi-program transport stream. Note that Quad 4K is not currently supported. Default is the first program within the transport stream. If the program you specify doesn't exist, the transcoding service will use this default.", "smithy.api#jsonName" => "programNumber"}))
    InputTemplate.add_member(:psi_control, Smithy::Schema::Shapes::ShapeRef.new(shape: InputPsiControl, location_name: 'PsiControl', traits: {"smithy.api#documentation" => "Set PSI control for transport stream inputs to specify which data the demux process to scans.\n* Ignore PSI - Scan all PIDs for audio and video.\n* Use PSI - Scan only PSI data.", "smithy.api#jsonName" => "psiControl"}))
    InputTemplate.add_member(:timecode_source, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTimecodeSource, location_name: 'TimecodeSource', traits: {"smithy.api#documentation" => "Use this Timecode source setting, located under the input settings, to specify how the service counts input video frames. This input frame count affects only the behavior of features that apply to a single input at a time, such as input clipping and synchronizing some captions formats. Choose Embedded to use the timecodes in your input video. Choose Start at zero to start the first frame at zero. Choose Specified start to start the first frame at the timecode that you specify in the setting Start timecode. If you don't specify a value for Timecode source, the service will use Embedded by default. For more information about timecodes, see https://docs.aws.amazon.com/console/mediaconvert/timecode.", "smithy.api#jsonName" => "timecodeSource"}))
    InputTemplate.add_member(:timecode_start, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin11max11pattern01d20305d205d, location_name: 'TimecodeStart', traits: {"smithy.api#documentation" => "Specify the timecode that you want the service to use for this input's initial frame. To use this setting, you must set the Timecode source setting, located under the input settings, to Specified start. For more information about timecodes, see https://docs.aws.amazon.com/console/mediaconvert/timecode.", "smithy.api#jsonName" => "timecodeStart"}))
    InputTemplate.add_member(:video_overlays, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofvideooverlay, location_name: 'VideoOverlays', traits: {"smithy.api#documentation" => "Contains an array of video overlays.", "smithy.api#jsonName" => "videoOverlays"}))
    InputTemplate.add_member(:video_selector, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoSelector, location_name: 'VideoSelector', traits: {"smithy.api#documentation" => "Input video selectors contain the video settings for the input. Each of your inputs can have up to one video selector.", "smithy.api#jsonName" => "videoSelector"}))
    InputTemplate.type = Types::InputTemplate
    InputTimecodeSource.add_member(:embedded, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EMBEDDED', traits: {"smithy.api#enumValue" => "EMBEDDED"}))
    InputTimecodeSource.add_member(:zerobased, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ZEROBASED', traits: {"smithy.api#enumValue" => "ZEROBASED"}))
    InputTimecodeSource.add_member(:specifiedstart, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFIEDSTART', traits: {"smithy.api#enumValue" => "SPECIFIEDSTART"}))
    InputVideoGenerator.add_member(:channels, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max32, location_name: 'Channels', traits: {"smithy.api#documentation" => "Specify the number of audio channels to include in your video generator input. MediaConvert creates these audio channels as silent audio within a single audio track. Enter an integer from 1 to 32.", "smithy.api#jsonName" => "channels"}))
    InputVideoGenerator.add_member(:duration, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin50max86400000, location_name: 'Duration', traits: {"smithy.api#documentation" => "Specify the duration, in milliseconds, for your video generator input.\nEnter an integer from 50 to 86400000.", "smithy.api#jsonName" => "duration"}))
    InputVideoGenerator.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max1001, location_name: 'FramerateDenominator', traits: {"smithy.api#documentation" => "Specify the denominator of the fraction that represents the frame rate for your video generator input. When you do, you must also specify a value for Frame rate numerator. MediaConvert uses a default frame rate of 29.97 when you leave Frame rate numerator and Frame rate denominator blank.", "smithy.api#jsonName" => "framerateDenominator"}))
    InputVideoGenerator.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max60000, location_name: 'FramerateNumerator', traits: {"smithy.api#documentation" => "Specify the numerator of the fraction that represents the frame rate for your video generator input. When you do, you must also specify a value for Frame rate denominator. MediaConvert uses a default frame rate of 29.97 when you leave Frame rate numerator and Frame rate denominator blank.", "smithy.api#jsonName" => "framerateNumerator"}))
    InputVideoGenerator.add_member(:sample_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32000max48000, location_name: 'SampleRate', traits: {"smithy.api#documentation" => "Specify the audio sample rate, in Hz, for the silent audio in your video generator input.\nEnter an integer from 32000 to 48000.", "smithy.api#jsonName" => "sampleRate"}))
    InputVideoGenerator.type = Types::InputVideoGenerator
    InsertableImage.add_member(:duration, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Duration', traits: {"smithy.api#documentation" => "Specify the time, in milliseconds, for the image to remain on the output video. This duration includes fade-in time but not fade-out time.", "smithy.api#jsonName" => "duration"}))
    InsertableImage.add_member(:fade_in, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'FadeIn', traits: {"smithy.api#documentation" => "Specify the length of time, in milliseconds, between the Start time that you specify for the image insertion and the time that the image appears at full opacity. Full opacity is the level that you specify for the opacity setting. If you don't specify a value for Fade-in, the image will appear abruptly at the overlay start time.", "smithy.api#jsonName" => "fadeIn"}))
    InsertableImage.add_member(:fade_out, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'FadeOut', traits: {"smithy.api#documentation" => "Specify the length of time, in milliseconds, between the end of the time that you have specified for the image overlay Duration and when the overlaid image has faded to total transparency. If you don't specify a value for Fade-out, the image will disappear abruptly at the end of the inserted image duration.", "smithy.api#jsonName" => "fadeOut"}))
    InsertableImage.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Height', traits: {"smithy.api#documentation" => "Specify the height of the inserted image in pixels. If you specify a value that's larger than the video resolution height, the service will crop your overlaid image to fit. To use the native height of the image, keep this setting blank.", "smithy.api#jsonName" => "height"}))
    InsertableImage.add_member(:image_inserter_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin14patterns3bmpbmppngpngtgatgahttpsbmpbmppngpngtgatga, location_name: 'ImageInserterInput', traits: {"smithy.api#documentation" => "Specify the HTTP, HTTPS, or Amazon S3 location of the image that you want to overlay on the video. Use a PNG or TGA file.", "smithy.api#jsonName" => "imageInserterInput"}))
    InsertableImage.add_member(:image_x, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'ImageX', traits: {"smithy.api#documentation" => "Specify the distance, in pixels, between the inserted image and the left edge of the video frame. Required for any image overlay that you specify.", "smithy.api#jsonName" => "imageX"}))
    InsertableImage.add_member(:image_y, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'ImageY', traits: {"smithy.api#documentation" => "Specify the distance, in pixels, between the overlaid image and the top edge of the video frame. Required for any image overlay that you specify.", "smithy.api#jsonName" => "imageY"}))
    InsertableImage.add_member(:layer, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max99, location_name: 'Layer', traits: {"smithy.api#documentation" => "Specify how overlapping inserted images appear. Images with higher values for Layer appear on top of images with lower values for Layer.", "smithy.api#jsonName" => "layer"}))
    InsertableImage.add_member(:opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max100, location_name: 'Opacity', traits: {"smithy.api#documentation" => "Use Opacity to specify how much of the underlying video shows through the inserted image. 0 is transparent and 100 is fully opaque. Default is 50.", "smithy.api#jsonName" => "opacity"}))
    InsertableImage.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern01d20305d205d, location_name: 'StartTime', traits: {"smithy.api#documentation" => "Specify the timecode of the frame that you want the overlay to first appear on. This must be in timecode (HH:MM:SS:FF or HH:MM:SS;FF) format. Remember to take into account your timecode source settings.", "smithy.api#jsonName" => "startTime"}))
    InsertableImage.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Width', traits: {"smithy.api#documentation" => "Specify the width of the inserted image in pixels. If you specify a value that's larger than the video resolution width, the service will crop your overlaid image to fit. To use the native width of the image, keep this setting blank.", "smithy.api#jsonName" => "width"}))
    InsertableImage.type = Types::InsertableImage
    InternalServerErrorException.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Message', traits: {"smithy.api#jsonName" => "message"}))
    InternalServerErrorException.type = Types::InternalServerErrorException
    Job.add_member(:acceleration_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AccelerationSettings, location_name: 'AccelerationSettings', traits: {"smithy.api#documentation" => "Accelerated transcoding can significantly speed up jobs with long, visually complex content.", "smithy.api#jsonName" => "accelerationSettings"}))
    Job.add_member(:acceleration_status, Smithy::Schema::Shapes::ShapeRef.new(shape: AccelerationStatus, location_name: 'AccelerationStatus', traits: {"smithy.api#documentation" => "Describes whether the current job is running with accelerated transcoding. For jobs that have Acceleration (AccelerationMode) set to DISABLED, AccelerationStatus is always NOT_APPLICABLE. For jobs that have Acceleration (AccelerationMode) set to ENABLED or PREFERRED, AccelerationStatus is one of the other states. AccelerationStatus is IN_PROGRESS initially, while the service determines whether the input files and job settings are compatible with accelerated transcoding. If they are, AcclerationStatus is ACCELERATED. If your input files and job settings aren't compatible with accelerated transcoding, the service either fails your job or runs it without accelerated transcoding, depending on how you set Acceleration (AccelerationMode). When the service runs your job without accelerated transcoding, AccelerationStatus is NOT_ACCELERATED.", "smithy.api#jsonName" => "accelerationStatus"}))
    Job.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Arn', traits: {"smithy.api#documentation" => "An identifier for this resource that is unique within all of AWS.", "smithy.api#jsonName" => "arn"}))
    Job.add_member(:billing_tags_source, Smithy::Schema::Shapes::ShapeRef.new(shape: BillingTagsSource, location_name: 'BillingTagsSource', traits: {"smithy.api#documentation" => "The tag type that AWS Billing and Cost Management will use to sort your AWS Elemental MediaConvert costs on any billing report that you set up.", "smithy.api#jsonName" => "billingTagsSource"}))
    Job.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "Prevent duplicate jobs from being created and ensure idempotency for your requests. A client request token can be any string that includes up to 64 ASCII characters. If you reuse a client request token within one minute of a successful request, the API returns the job details of the original request instead. For more information see https://docs.aws.amazon.com/mediaconvert/latest/apireference/idempotency.html.", "smithy.api#jsonName" => "clientRequestToken"}))
    Job.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'CreatedAt', traits: {"smithy.api#documentation" => "The time, in Unix epoch format in seconds, when the job got created.", "smithy.api#jsonName" => "createdAt"}))
    Job.add_member(:current_phase, Smithy::Schema::Shapes::ShapeRef.new(shape: JobPhase, location_name: 'CurrentPhase', traits: {"smithy.api#documentation" => "A job's phase can be PROBING, TRANSCODING OR UPLOADING", "smithy.api#jsonName" => "currentPhase"}))
    Job.add_member(:error_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ErrorCode', traits: {"smithy.api#documentation" => "Error code for the job", "smithy.api#jsonName" => "errorCode"}))
    Job.add_member(:error_message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ErrorMessage', traits: {"smithy.api#documentation" => "Error message of Job", "smithy.api#jsonName" => "errorMessage"}))
    Job.add_member(:hop_destinations, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofhopdestination, location_name: 'HopDestinations', traits: {"smithy.api#documentation" => "Optional list of hop destinations.", "smithy.api#jsonName" => "hopDestinations"}))
    Job.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Id', traits: {"smithy.api#documentation" => "A portion of the job's ARN, unique within your AWS Elemental MediaConvert resources", "smithy.api#jsonName" => "id"}))
    Job.add_member(:job_engine_version_requested, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'JobEngineVersionRequested', traits: {"smithy.api#documentation" => "The Job engine version that you requested for your job. Valid versions are in a YYYY-MM-DD format.", "smithy.api#jsonName" => "jobEngineVersionRequested"}))
    Job.add_member(:job_engine_version_used, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'JobEngineVersionUsed', traits: {"smithy.api#documentation" => "The Job engine version that your job used. Job engine versions are in a YYYY-MM-DD format. When you request an expired version, the response for this property will be empty. Requests to create jobs with an expired version result in a regular job, as if no specific Job engine version was requested. When you request an invalid version, the response for this property will be empty. Requests to create jobs with an invalid version result in a 400 error message, and no job is created.", "smithy.api#jsonName" => "jobEngineVersionUsed"}))
    Job.add_member(:job_percent_complete, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'JobPercentComplete', traits: {"smithy.api#documentation" => "An estimate of how far your job has progressed. This estimate is shown as a percentage of the total time from when your job leaves its queue to when your output files appear in your output Amazon S3 bucket. AWS Elemental MediaConvert provides jobPercentComplete in CloudWatch STATUS_UPDATE events and in the response to GetJob and ListJobs requests. The jobPercentComplete estimate is reliable for the following input containers: Quicktime, Transport Stream, MP4, and MXF. For some jobs, the service can't provide information about job progress. In those cases, jobPercentComplete returns a null value.", "smithy.api#jsonName" => "jobPercentComplete"}))
