    Job.add_member(:retry_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'RetryCount', traits: {"smithy.api#documentation" => "The number of times that the service automatically attempted to process your job after encountering an error.", "smithy.api#jsonName" => "retryCount"}))
