    Job.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: JobSettings, location_name: 'Settings', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "JobSettings contains all the transcode settings for a job.", "smithy.api#jsonName" => "settings", "smithy.api#required" => {}}))
    Job.add_member(:simulate_reserved_queue, Smithy::Schema::Shapes::ShapeRef.new(shape: SimulateReservedQueue, location_name: 'SimulateReservedQueue', traits: {"smithy.api#documentation" => "Enable this setting when you run a test job to estimate how many reserved transcoding slots (RTS) you need. When this is enabled, MediaConvert runs your job from an on-demand queue with similar performance to what you will see with one RTS in a reserved queue. This setting is disabled by default.", "smithy.api#jsonName" => "simulateReservedQueue"}))
    Job.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: JobStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "A job's status can be SUBMITTED, PROGRESSING, COMPLETE, CANCELED, or ERROR.", "smithy.api#jsonName" => "status"}))
    Job.add_member(:status_update_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusUpdateInterval, location_name: 'StatusUpdateInterval', traits: {"smithy.api#documentation" => "Specify how often MediaConvert sends STATUS_UPDATE events to Amazon CloudWatch Events. Set the interval, in seconds, between status updates. MediaConvert sends an update at this interval from the time the service begins processing your job to the time it completes the transcode or encounters an error.", "smithy.api#jsonName" => "statusUpdateInterval"}))
