    JobSettings.add_member(:color_conversion3_dlut_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofcolorconversion3dlutsetting, location_name: 'ColorConversion3DLUTSettings', traits: {"smithy.api#documentation" => "Use 3D LUTs to specify custom color mapping behavior when you convert from one color space into another. You can include up to 8 different 3D LUTs. For more information, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/3d-luts.html", "smithy.api#jsonName" => "colorConversion3DLUTSettings"}))
