    JobSettings.add_member(:timed_metadata_insertion, Smithy::Schema::Shapes::ShapeRef.new(shape: TimedMetadataInsertion, location_name: 'TimedMetadataInsertion', traits: {"smithy.api#documentation" => "Insert user-defined custom ID3 metadata at timecodes that you specify. In each output that you want to include this metadata, you must set ID3 metadata to Passthrough.", "smithy.api#jsonName" => "timedMetadataInsertion"}))
