    M2tsSettings.add_member(:audio_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsAudioDuration, location_name: 'AudioDuration', traits: {"smithy.api#documentation" => "Specify this setting only when your output will be consumed by a downstream repackaging workflow that is sensitive to very small duration differences between video and audio. For this situation, choose Match video duration. In all other cases, keep the default value, Default codec duration. When you choose Match video duration, MediaConvert pads the output audio streams with silence or trims them to ensure that the total duration of each audio stream is at least as long as the total duration of the video stream. After padding or trimming, the audio stream duration is no more than one frame longer than the video stream. MediaConvert applies audio padding or trimming only to the end of the last segment of the output. For unsegmented outputs, MediaConvert adds padding only to the end of the file. When you keep the default value, any minor discrepancies between audio and video duration will depend on your output audio codec.", "smithy.api#jsonName" => "audioDuration"}))
    M2tsSettings.add_member(:audio_frames_per_pes, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'AudioFramesPerPes', traits: {"smithy.api#documentation" => "The number of audio frames to insert for each PES packet.", "smithy.api#jsonName" => "audioFramesPerPes"}))
    M2tsSettings.add_member(:audio_pids, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofIntegermin32max8182, location_name: 'AudioPids', traits: {"smithy.api#documentation" => "Specify the packet identifiers (PIDs) for any elementary audio streams you include in this output. Specify multiple PIDs as a JSON array. Default is the range 482-492.", "smithy.api#jsonName" => "audioPids"}))
    M2tsSettings.add_member(:audio_pts_offset_delta, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative10000max10000, location_name: 'AudioPtsOffsetDelta', traits: {"smithy.api#documentation" => "Manually specify the difference in PTS offset that will be applied to the audio track, in seconds or milliseconds, when you set PTS offset to Seconds or Milliseconds. Enter an integer from -10000 to 10000. Leave blank to keep the default value 0.", "smithy.api#jsonName" => "audioPtsOffsetDelta"}))
    M2tsSettings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Specify the output bitrate of the transport stream in bits per second. Setting to 0 lets the muxer automatically determine the appropriate bitrate. Other common values are 3750000, 7500000, and 15000000.", "smithy.api#jsonName" => "bitrate"}))
    M2tsSettings.add_member(:buffer_model, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsBufferModel, location_name: 'BufferModel', traits: {"smithy.api#documentation" => "Controls what buffer model to use for accurate interleaving. If set to MULTIPLEX, use multiplex buffer model. If set to NONE, this can lead to lower latency, but low-memory devices may not be able to play back the stream without interruptions.", "smithy.api#jsonName" => "bufferModel"}))
    M2tsSettings.add_member(:data_pts_control, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsDataPtsControl, location_name: 'DataPTSControl', traits: {"smithy.api#documentation" => "If you select ALIGN_TO_VIDEO, MediaConvert writes captions and data packets with Presentation Timestamp (PTS) values greater than or equal to the first video packet PTS (MediaConvert drops captions and data packets with lesser PTS values). Keep the default value to allow all PTS values.", "smithy.api#jsonName" => "dataPTSControl"}))
