    M2tsSettings.add_member(:dvb_sdt_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSdtSettings, location_name: 'DvbSdtSettings', traits: {"smithy.api#documentation" => "Use these settings to insert a DVB Service Description Table (SDT) in the transport stream of this output.", "smithy.api#jsonName" => "dvbSdtSettings"}))
    M2tsSettings.add_member(:dvb_sub_pids, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofIntegermin32max8182, location_name: 'DvbSubPids', traits: {"smithy.api#documentation" => "Specify the packet identifiers (PIDs) for DVB subtitle data included in this output. Specify multiple PIDs as a JSON array. Default is the range 460-479.", "smithy.api#jsonName" => "dvbSubPids"}))
    M2tsSettings.add_member(:dvb_tdt_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbTdtSettings, location_name: 'DvbTdtSettings', traits: {"smithy.api#documentation" => "Use these settings to insert a DVB Time and Date Table (TDT) in the transport stream of this output.", "smithy.api#jsonName" => "dvbTdtSettings"}))
    M2tsSettings.add_member(:dvb_teletext_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'DvbTeletextPid', traits: {"smithy.api#documentation" => "Specify the packet identifier (PID) for DVB teletext data you include in this output. Default is 499.", "smithy.api#jsonName" => "dvbTeletextPid"}))
    M2tsSettings.add_member(:ebp_audio_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsEbpAudioInterval, location_name: 'EbpAudioInterval', traits: {"smithy.api#documentation" => "When set to VIDEO_AND_FIXED_INTERVALS, audio EBP markers will be added to partitions 3 and 4. The interval between these additional markers will be fixed, and will be slightly shorter than the video EBP marker interval. When set to VIDEO_INTERVAL, these additional markers will not be inserted. Only applicable when EBP segmentation markers are is selected (segmentationMarkers is EBP or EBP_LEGACY).", "smithy.api#jsonName" => "ebpAudioInterval"}))
    M2tsSettings.add_member(:ebp_placement, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsEbpPlacement, location_name: 'EbpPlacement', traits: {"smithy.api#documentation" => "Selects which PIDs to place EBP markers on. They can either be placed only on the video PID, or on both the video PID and all audio PIDs. Only applicable when EBP segmentation markers are is selected (segmentationMarkers is EBP or EBP_LEGACY).", "smithy.api#jsonName" => "ebpPlacement"}))
    M2tsSettings.add_member(:es_rate_in_pes, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsEsRateInPes, location_name: 'EsRateInPes', traits: {"smithy.api#documentation" => "Controls whether to include the ES Rate field in the PES header.", "smithy.api#jsonName" => "esRateInPes"}))
    M2tsSettings.add_member(:force_ts_video_ebp_order, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsForceTsVideoEbpOrder, location_name: 'ForceTsVideoEbpOrder', traits: {"smithy.api#documentation" => "Keep the default value unless you know that your audio EBP markers are incorrectly appearing before your video EBP markers. To correct this problem, set this value to Force.", "smithy.api#jsonName" => "forceTsVideoEbpOrder"}))
    M2tsSettings.add_member(:fragment_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0, location_name: 'FragmentTime', traits: {"smithy.api#documentation" => "The length, in seconds, of each fragment. Only used with EBP markers.", "smithy.api#jsonName" => "fragmentTime"}))
    M2tsSettings.add_member(:klv_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsKlvMetadata, location_name: 'KlvMetadata', traits: {"smithy.api#documentation" => "To include key-length-value metadata in this output: Set KLV metadata insertion to Passthrough. MediaConvert reads KLV metadata present in your input and passes it through to the output transport stream. To exclude this KLV metadata: Set KLV metadata insertion to None or leave blank.", "smithy.api#jsonName" => "klvMetadata"}))
    M2tsSettings.add_member(:max_pcr_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max500, location_name: 'MaxPcrInterval', traits: {"smithy.api#documentation" => "Specify the maximum time, in milliseconds, between Program Clock References (PCRs) inserted into the transport stream.", "smithy.api#jsonName" => "maxPcrInterval"}))
    M2tsSettings.add_member(:min_ebp_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max10000, location_name: 'MinEbpInterval', traits: {"smithy.api#documentation" => "When set, enforces that Encoder Boundary Points do not come within the specified time interval of each other by looking ahead at input video. If another EBP is going to come in within the specified time interval, the current EBP is not emitted, and the segment is \"stretched\" to the next marker. The lookahead value does not add latency to the system. The Live Event must be configured elsewhere to create sufficient latency to make the lookahead accurate.", "smithy.api#jsonName" => "minEbpInterval"}))
    M2tsSettings.add_member(:nielsen_id3, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsNielsenId3, location_name: 'NielsenId3', traits: {"smithy.api#documentation" => "If INSERT, Nielsen inaudible tones for media tracking will be detected in the input audio and an equivalent ID3 tag will be inserted in the output.", "smithy.api#jsonName" => "nielsenId3"}))
    M2tsSettings.add_member(:null_packet_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0, location_name: 'NullPacketBitrate', traits: {"smithy.api#documentation" => "Value in bits per second of extra null packets to insert into the transport stream. This can be used if a downstream encryption system requires periodic null packets.", "smithy.api#jsonName" => "nullPacketBitrate"}))
    M2tsSettings.add_member(:pat_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max1000, location_name: 'PatInterval', traits: {"smithy.api#documentation" => "The number of milliseconds between instances of this table in the output transport stream.", "smithy.api#jsonName" => "patInterval"}))
    M2tsSettings.add_member(:pcr_control, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsPcrControl, location_name: 'PcrControl', traits: {"smithy.api#documentation" => "When set to PCR_EVERY_PES_PACKET, a Program Clock Reference value is inserted for every Packetized Elementary Stream (PES) header. This is effective only when the PCR PID is the same as the video or audio elementary stream.", "smithy.api#jsonName" => "pcrControl"}))
    M2tsSettings.add_member(:pcr_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'PcrPid', traits: {"smithy.api#documentation" => "Specify the packet identifier (PID) for the program clock reference (PCR) in this output. If you do not specify a value, the service will use the value for Video PID.", "smithy.api#jsonName" => "pcrPid"}))
    M2tsSettings.add_member(:pmt_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max1000, location_name: 'PmtInterval', traits: {"smithy.api#documentation" => "Specify the number of milliseconds between instances of the program map table (PMT) in the output transport stream.", "smithy.api#jsonName" => "pmtInterval"}))
    M2tsSettings.add_member(:pmt_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'PmtPid', traits: {"smithy.api#documentation" => "Specify the packet identifier (PID) for the program map table (PMT) itself. Default is 480.", "smithy.api#jsonName" => "pmtPid"}))
    M2tsSettings.add_member(:prevent_buffer_underflow, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsPreventBufferUnderflow, location_name: 'PreventBufferUnderflow', traits: {"smithy.api#documentation" => "Specify whether MediaConvert automatically attempts to prevent decoder buffer underflows in your transport stream output. Use if you are seeing decoder buffer underflows in your output and are unable to increase your transport stream's bitrate. For most workflows: We recommend that you keep the default value, Disabled. To prevent decoder buffer underflows in your output, when possible: Choose Enabled. Note that if MediaConvert prevents a decoder buffer underflow in your output, output video quality is reduced and your job will take longer to complete.", "smithy.api#jsonName" => "preventBufferUnderflow"}))
    M2tsSettings.add_member(:private_metadata_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'PrivateMetadataPid', traits: {"smithy.api#documentation" => "Specify the packet identifier (PID) of the private metadata stream. Default is 503.", "smithy.api#jsonName" => "privateMetadataPid"}))
    M2tsSettings.add_member(:program_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65535, location_name: 'ProgramNumber', traits: {"smithy.api#documentation" => "Use Program number to specify the program number used in the program map table (PMT) for this output. Default is 1. Program numbers and program map tables are parts of MPEG-2 transport stream containers, used for organizing data.", "smithy.api#jsonName" => "programNumber"}))
    M2tsSettings.add_member(:pts_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max3600, location_name: 'PtsOffset', traits: {"smithy.api#documentation" => "Manually specify the initial PTS offset, in seconds, when you set PTS offset to Seconds. Enter an integer from 0 to 3600. Leave blank to keep the default value 2.", "smithy.api#jsonName" => "ptsOffset"}))
    M2tsSettings.add_member(:pts_offset_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TsPtsOffset, location_name: 'PtsOffsetMode', traits: {"smithy.api#documentation" => "Specify the initial presentation timestamp (PTS) offset for your transport stream output. To let MediaConvert automatically determine the initial PTS offset: Keep the default value, Auto. We recommend that you choose Auto for the widest player compatibility. The initial PTS will be at least two seconds and vary depending on your output's bitrate, HRD buffer size and HRD buffer initial fill percentage. To manually specify an initial PTS offset: Choose Seconds or Milliseconds. Then specify the number of seconds or milliseconds with PTS offset.", "smithy.api#jsonName" => "ptsOffsetMode"}))
    M2tsSettings.add_member(:rate_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsRateMode, location_name: 'RateMode', traits: {"smithy.api#documentation" => "When set to CBR, inserts null packets into transport stream to fill specified bitrate. When set to VBR, the bitrate setting acts as the maximum bitrate, but the output will not be padded up to that bitrate.", "smithy.api#jsonName" => "rateMode"}))
    M2tsSettings.add_member(:scte35_esam, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsScte35Esam, location_name: 'Scte35Esam', traits: {"smithy.api#documentation" => "Include this in your job settings to put SCTE-35 markers in your HLS and transport stream outputs at the insertion points that you specify in an ESAM XML document. Provide the document in the setting SCC XML.", "smithy.api#jsonName" => "scte35Esam"}))
    M2tsSettings.add_member(:scte35_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'Scte35Pid', traits: {"smithy.api#documentation" => "Specify the packet identifier (PID) of the SCTE-35 stream in the transport stream.", "smithy.api#jsonName" => "scte35Pid"}))
    M2tsSettings.add_member(:scte35_source, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsScte35Source, location_name: 'Scte35Source', traits: {"smithy.api#documentation" => "For SCTE-35 markers from your input-- Choose Passthrough if you want SCTE-35 markers that appear in your input to also appear in this output. Choose None if you don't want SCTE-35 markers in this output. For SCTE-35 markers from an ESAM XML document-- Choose None. Also provide the ESAM XML as a string in the setting Signal processing notification XML. Also enable ESAM SCTE-35 (include the property scte35Esam).", "smithy.api#jsonName" => "scte35Source"}))
    M2tsSettings.add_member(:segmentation_markers, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsSegmentationMarkers, location_name: 'SegmentationMarkers', traits: {"smithy.api#documentation" => "Inserts segmentation markers at each segmentation_time period. rai_segstart sets the Random Access Indicator bit in the adaptation field. rai_adapt sets the RAI bit and adds the current timecode in the private data bytes. psi_segstart inserts PAT and PMT tables at the start of segments. ebp adds Encoder Boundary Point information to the adaptation field as per OpenCable specification OC-SP-EBP-I01-130118. ebp_legacy adds Encoder Boundary Point information to the adaptation field using a legacy proprietary format.", "smithy.api#jsonName" => "segmentationMarkers"}))
    M2tsSettings.add_member(:segmentation_style, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsSegmentationStyle, location_name: 'SegmentationStyle', traits: {"smithy.api#documentation" => "The segmentation style parameter controls how segmentation markers are inserted into the transport stream. With avails, it is possible that segments may be truncated, which can influence where future segmentation markers are inserted. When a segmentation style of \"reset_cadence\" is selected and a segment is truncated due to an avail, we will reset the segmentation cadence. This means the subsequent segment will have a duration of of $segmentation_time seconds. When a segmentation style of \"maintain_cadence\" is selected and a segment is truncated due to an avail, we will not reset the segmentation cadence. This means the subsequent segment will likely be truncated as well. However, all segments after that will have a duration of $segmentation_time seconds. Note that EBP lookahead is a slight exception to this rule.", "smithy.api#jsonName" => "segmentationStyle"}))
    M2tsSettings.add_member(:segmentation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0, location_name: 'SegmentationTime', traits: {"smithy.api#documentation" => "Specify the length, in seconds, of each segment. Required unless markers is set to _none_.", "smithy.api#jsonName" => "segmentationTime"}))
    M2tsSettings.add_member(:timed_metadata_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'TimedMetadataPid', traits: {"smithy.api#documentation" => "Packet Identifier (PID) of the ID3 metadata stream in the transport stream.", "smithy.api#jsonName" => "timedMetadataPid"}))
    M2tsSettings.add_member(:transport_stream_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65535, location_name: 'TransportStreamId', traits: {"smithy.api#documentation" => "Specify the ID for the transport stream itself in the program map table for this output. Transport stream IDs and program map tables are parts of MPEG-2 transport stream containers, used for organizing data.", "smithy.api#jsonName" => "transportStreamId"}))
    M2tsSettings.add_member(:video_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'VideoPid', traits: {"smithy.api#documentation" => "Specify the packet identifier (PID) of the elementary video stream in the transport stream.", "smithy.api#jsonName" => "videoPid"}))
