    M3u8PcrControl.add_member(:configured_pcr_period, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CONFIGURED_PCR_PERIOD', traits: {"smithy.api#enumValue" => "CONFIGURED_PCR_PERIOD"}))
