    M3u8Settings.add_member(:audio_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: M3u8AudioDuration, location_name: 'AudioDuration', traits: {"smithy.api#documentation" => "Specify this setting only when your output will be consumed by a downstream repackaging workflow that is sensitive to very small duration differences between video and audio. For this situation, choose Match video duration. In all other cases, keep the default value, Default codec duration. When you choose Match video duration, MediaConvert pads the output audio streams with silence or trims them to ensure that the total duration of each audio stream is at least as long as the total duration of the video stream. After padding or trimming, the audio stream duration is no more than one frame longer than the video stream. MediaConvert applies audio padding or trimming only to the end of the last segment of the output. For unsegmented outputs, MediaConvert adds padding only to the end of the file. When you keep the default value, any minor discrepancies between audio and video duration will depend on your output audio codec.", "smithy.api#jsonName" => "audioDuration"}))
    M3u8Settings.add_member(:audio_frames_per_pes, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'AudioFramesPerPes', traits: {"smithy.api#documentation" => "The number of audio frames to insert for each PES packet.", "smithy.api#jsonName" => "audioFramesPerPes"}))
    M3u8Settings.add_member(:audio_pids, Smithy::Schema::Shapes::ShapeRef.new(shape: ListofIntegermin32max8182, location_name: 'AudioPids', traits: {"smithy.api#documentation" => "Packet Identifier (PID) of the elementary audio stream(s) in the transport stream. Multiple values are accepted, and can be entered in ranges and/or by comma separation.", "smithy.api#jsonName" => "audioPids"}))
    M3u8Settings.add_member(:audio_pts_offset_delta, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative10000max10000, location_name: 'AudioPtsOffsetDelta', traits: {"smithy.api#documentation" => "Manually specify the difference in PTS offset that will be applied to the audio track, in seconds or milliseconds, when you set PTS offset to Seconds or Milliseconds. Enter an integer from -10000 to 10000. Leave blank to keep the default value 0.", "smithy.api#jsonName" => "audioPtsOffsetDelta"}))
    M3u8Settings.add_member(:data_pts_control, Smithy::Schema::Shapes::ShapeRef.new(shape: M3u8DataPtsControl, location_name: 'DataPTSControl', traits: {"smithy.api#documentation" => "If you select ALIGN_TO_VIDEO, MediaConvert writes captions and data packets with Presentation Timestamp (PTS) values greater than or equal to the first video packet PTS (MediaConvert drops captions and data packets with lesser PTS values). Keep the default value AUTO to allow all PTS values.", "smithy.api#jsonName" => "dataPTSControl"}))
    M3u8Settings.add_member(:max_pcr_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max500, location_name: 'MaxPcrInterval', traits: {"smithy.api#documentation" => "Specify the maximum time, in milliseconds, between Program Clock References (PCRs) inserted into the transport stream.", "smithy.api#jsonName" => "maxPcrInterval"}))
    M3u8Settings.add_member(:nielsen_id3, Smithy::Schema::Shapes::ShapeRef.new(shape: M3u8NielsenId3, location_name: 'NielsenId3', traits: {"smithy.api#documentation" => "If INSERT, Nielsen inaudible tones for media tracking will be detected in the input audio and an equivalent ID3 tag will be inserted in the output.", "smithy.api#jsonName" => "nielsenId3"}))
    M3u8Settings.add_member(:pat_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max1000, location_name: 'PatInterval', traits: {"smithy.api#documentation" => "The number of milliseconds between instances of this table in the output transport stream.", "smithy.api#jsonName" => "patInterval"}))
    M3u8Settings.add_member(:pcr_control, Smithy::Schema::Shapes::ShapeRef.new(shape: M3u8PcrControl, location_name: 'PcrControl', traits: {"smithy.api#documentation" => "When set to PCR_EVERY_PES_PACKET a Program Clock Reference value is inserted for every Packetized Elementary Stream (PES) header. This parameter is effective only when the PCR PID is the same as the video or audio elementary stream.", "smithy.api#jsonName" => "pcrControl"}))
    M3u8Settings.add_member(:pcr_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'PcrPid', traits: {"smithy.api#documentation" => "Packet Identifier (PID) of the Program Clock Reference (PCR) in the transport stream. When no value is given, the encoder will assign the same value as the Video PID.", "smithy.api#jsonName" => "pcrPid"}))
    M3u8Settings.add_member(:pmt_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max1000, location_name: 'PmtInterval', traits: {"smithy.api#documentation" => "The number of milliseconds between instances of this table in the output transport stream.", "smithy.api#jsonName" => "pmtInterval"}))
    M3u8Settings.add_member(:pmt_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'PmtPid', traits: {"smithy.api#documentation" => "Packet Identifier (PID) for the Program Map Table (PMT) in the transport stream.", "smithy.api#jsonName" => "pmtPid"}))
    M3u8Settings.add_member(:private_metadata_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'PrivateMetadataPid', traits: {"smithy.api#documentation" => "Packet Identifier (PID) of the private metadata stream in the transport stream.", "smithy.api#jsonName" => "privateMetadataPid"}))
    M3u8Settings.add_member(:program_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65535, location_name: 'ProgramNumber', traits: {"smithy.api#documentation" => "The value of the program number field in the Program Map Table.", "smithy.api#jsonName" => "programNumber"}))
    M3u8Settings.add_member(:pts_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max3600, location_name: 'PtsOffset', traits: {"smithy.api#documentation" => "Manually specify the initial PTS offset, in seconds, when you set PTS offset to Seconds. Enter an integer from 0 to 3600. Leave blank to keep the default value 2.", "smithy.api#jsonName" => "ptsOffset"}))
    M3u8Settings.add_member(:pts_offset_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TsPtsOffset, location_name: 'PtsOffsetMode', traits: {"smithy.api#documentation" => "Specify the initial presentation timestamp (PTS) offset for your transport stream output. To let MediaConvert automatically determine the initial PTS offset: Keep the default value, Auto. We recommend that you choose Auto for the widest player compatibility. The initial PTS will be at least two seconds and vary depending on your output's bitrate, HRD buffer size and HRD buffer initial fill percentage. To manually specify an initial PTS offset: Choose Seconds or Milliseconds. Then specify the number of seconds or milliseconds with PTS offset.", "smithy.api#jsonName" => "ptsOffsetMode"}))
    M3u8Settings.add_member(:scte35_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'Scte35Pid', traits: {"smithy.api#documentation" => "Packet Identifier (PID) of the SCTE-35 stream in the transport stream.", "smithy.api#jsonName" => "scte35Pid"}))
    M3u8Settings.add_member(:scte35_source, Smithy::Schema::Shapes::ShapeRef.new(shape: M3u8Scte35Source, location_name: 'Scte35Source', traits: {"smithy.api#documentation" => "For SCTE-35 markers from your input-- Choose Passthrough if you want SCTE-35 markers that appear in your input to also appear in this output. Choose None if you don't want SCTE-35 markers in this output. For SCTE-35 markers from an ESAM XML document-- Choose None if you don't want manifest conditioning. Choose Passthrough and choose Ad markers if you do want manifest conditioning. In both cases, also provide the ESAM XML as a string in the setting Signal processing notification XML.", "smithy.api#jsonName" => "scte35Source"}))
    M3u8Settings.add_member(:timed_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: TimedMetadata, location_name: 'TimedMetadata', traits: {"smithy.api#documentation" => "Set ID3 metadata to Passthrough to include ID3 metadata in this output. This includes ID3 metadata from the following features: ID3 timestamp period, and Custom ID3 metadata inserter. To exclude this ID3 metadata in this output: set ID3 metadata to None or leave blank.", "smithy.api#jsonName" => "timedMetadata"}))
    M3u8Settings.add_member(:timed_metadata_pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8182, location_name: 'TimedMetadataPid', traits: {"smithy.api#documentation" => "Packet Identifier (PID) of the ID3 metadata stream in the transport stream.", "smithy.api#jsonName" => "timedMetadataPid"}))
