    MovSettings.add_member(:padding_control, Smithy::Schema::Shapes::ShapeRef.new(shape: MovPaddingControl, location_name: 'PaddingControl', traits: {"smithy.api#documentation" => "Unless you need Omneon compatibility: Keep the default value, None. To make this output compatible with Omneon: Choose Omneon. When you do, MediaConvert increases the length of the 'elst' edit list atom. Note that this might cause file rejections when a recipient of the output file doesn't expect this extra padding.", "smithy.api#jsonName" => "paddingControl"}))
