    Mp4Settings.add_member(:certificate_secret, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max2048patternarnazsecretsmanagerwd12secretazaz09, location_name: 'CertificateSecret', traits: {"smithy.api#documentation" => "Specify the name or ARN of the AWS Secrets Manager secret that contains your C2PA public certificate chain in PEM format. Provide a valid secret name or ARN. Note that your MediaConvert service role must allow access to this secret. The public certificate chain is added to the COSE header (x5chain) for signature validation. Include the signer's certificate and all intermediate certificates. Do not include the root certificate. For details on COSE, see: https://opensource.contentauthenticity.org/docs/manifest/signing-manifests", "smithy.api#jsonName" => "certificateSecret"}))
    Mp4Settings.add_member(:cslg_atom, Smithy::Schema::Shapes::ShapeRef.new(shape: Mp4CslgAtom, location_name: 'CslgAtom', traits: {"smithy.api#documentation" => "When enabled, file composition times will start at zero, composition times in the 'ctts' (composition time to sample) box for B-frames will be negative, and a 'cslg' (composition shift least greatest) box will be included per 14496-1 amendment 1. This improves compatibility with Apple players and tools.", "smithy.api#jsonName" => "cslgAtom"}))
    Mp4Settings.add_member(:ctts_version, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max1, location_name: 'CttsVersion', traits: {"smithy.api#documentation" => "Ignore this setting unless compliance to the CTTS box version specification matters in your workflow. Specify a value of 1 to set your CTTS box version to 1 and make your output compliant with the specification. When you specify a value of 1, you must also set CSLG atom to the value INCLUDE. Keep the default value 0 to set your CTTS box version to 0. This can provide backward compatibility for some players and packagers.", "smithy.api#jsonName" => "cttsVersion"}))
    Mp4Settings.add_member(:free_space_box, Smithy::Schema::Shapes::ShapeRef.new(shape: Mp4FreeSpaceBox, location_name: 'FreeSpaceBox', traits: {"smithy.api#documentation" => "Inserts a free-space box immediately after the moov box.", "smithy.api#jsonName" => "freeSpaceBox"}))
