    Mp4Settings.add_member(:mp4_major_brand, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Mp4MajorBrand', traits: {"smithy.api#documentation" => "Overrides the \"Major Brand\" field in the output file. Usually not necessary to specify.", "smithy.api#jsonName" => "mp4MajorBrand"}))
