    MpdSettings.add_member(:accessibility_caption_hints, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdAccessibilityCaptionHints, location_name: 'AccessibilityCaptionHints', traits: {"smithy.api#documentation" => "Optional. Choose Include to have MediaConvert mark up your DASH manifest with <Accessibility> elements for embedded 608 captions. This markup isn't generally required, but some video players require it to discover and play embedded 608 captions. Keep the default value, Exclude, to leave these elements out. When you enable this setting, this is the markup that MediaConvert includes in your manifest: <Accessibility schemeIdUri=\"urn:scte:dash:cc:cea-608:2015\" value=\"CC1=eng\"/>", "smithy.api#jsonName" => "accessibilityCaptionHints"}))
    MpdSettings.add_member(:audio_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdAudioDuration, location_name: 'AudioDuration', traits: {"smithy.api#documentation" => "Specify this setting only when your output will be consumed by a downstream repackaging workflow that is sensitive to very small duration differences between video and audio. For this situation, choose Match video duration. In all other cases, keep the default value, Default codec duration. When you choose Match video duration, MediaConvert pads the output audio streams with silence or trims them to ensure that the total duration of each audio stream is at least as long as the total duration of the video stream. After padding or trimming, the audio stream duration is no more than one frame longer than the video stream. MediaConvert applies audio padding or trimming only to the end of the last segment of the output. For unsegmented outputs, MediaConvert adds padding only to the end of the file. When you keep the default value, any minor discrepancies between audio and video duration will depend on your output audio codec.", "smithy.api#jsonName" => "audioDuration"}))
    MpdSettings.add_member(:caption_container_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdCaptionContainerType, location_name: 'CaptionContainerType', traits: {"smithy.api#documentation" => "Use this setting only in DASH output groups that include sidecar TTML or IMSC captions. You specify sidecar captions in a separate output from your audio and video. Choose Raw for captions in a single XML file in a raw container. Choose Fragmented MPEG-4 for captions in XML format contained within fragmented MP4 files. This set of fragmented MP4 files is separate from your video and audio fragmented MP4 files.", "smithy.api#jsonName" => "captionContainerType"}))
    MpdSettings.add_member(:klv_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdKlvMetadata, location_name: 'KlvMetadata', traits: {"smithy.api#documentation" => "To include key-length-value metadata in this output: Set KLV metadata insertion to Passthrough. MediaConvert reads KLV metadata present in your input and writes each instance to a separate event message box in the output, according to MISB ST1910.1. To exclude this KLV metadata: Set KLV metadata insertion to None or leave blank.", "smithy.api#jsonName" => "klvMetadata"}))
    MpdSettings.add_member(:manifest_metadata_signaling, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdManifestMetadataSignaling, location_name: 'ManifestMetadataSignaling', traits: {"smithy.api#documentation" => "To add an InbandEventStream element in your output MPD manifest for each type of event message, set Manifest metadata signaling to Enabled. For ID3 event messages, the InbandEventStream element schemeIdUri will be same value that you specify for ID3 metadata scheme ID URI. For SCTE35 event messages, the InbandEventStream element schemeIdUri will be \"urn:scte:scte35:2013:bin\". To leave these elements out of your output MPD manifest, set Manifest metadata signaling to Disabled. To enable Manifest metadata signaling, you must also set SCTE-35 source to Passthrough, ESAM SCTE-35 to insert, or ID3 metadata to Passthrough.", "smithy.api#jsonName" => "manifestMetadataSignaling"}))
    MpdSettings.add_member(:scte35_esam, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdScte35Esam, location_name: 'Scte35Esam', traits: {"smithy.api#documentation" => "Use this setting only when you specify SCTE-35 markers from ESAM. Choose INSERT to put SCTE-35 markers in this output at the insertion points that you specify in an ESAM XML document. Provide the document in the setting SCC XML.", "smithy.api#jsonName" => "scte35Esam"}))
    MpdSettings.add_member(:scte35_source, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdScte35Source, location_name: 'Scte35Source', traits: {"smithy.api#documentation" => "Ignore this setting unless you have SCTE-35 markers in your input video file. Choose Passthrough if you want SCTE-35 markers that appear in your input to also appear in this output. Choose None if you don't want those SCTE-35 markers in this output.", "smithy.api#jsonName" => "scte35Source"}))
    MpdSettings.add_member(:timed_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdTimedMetadata, location_name: 'TimedMetadata', traits: {"smithy.api#documentation" => "To include ID3 metadata in this output: Set ID3 metadata to Passthrough. Specify this ID3 metadata in Custom ID3 metadata inserter. MediaConvert writes each instance of ID3 metadata in a separate Event Message (eMSG) box. To exclude this ID3 metadata: Set ID3 metadata to None or leave blank.", "smithy.api#jsonName" => "timedMetadata"}))
    MpdSettings.add_member(:timed_metadata_box_version, Smithy::Schema::Shapes::ShapeRef.new(shape: MpdTimedMetadataBoxVersion, location_name: 'TimedMetadataBoxVersion', traits: {"smithy.api#documentation" => "Specify the event message box (eMSG) version for ID3 timed metadata in your output.\nFor more information, see ISO/IEC 23009-1:2022 section 5.10.3.3.3 Syntax.\nLeave blank to use the default value Version 0.\nWhen you specify Version 1, you must also set ID3 metadata to Passthrough.", "smithy.api#jsonName" => "timedMetadataBoxVersion"}))
    MpdSettings.add_member(:timed_metadata_scheme_id_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmax1000, location_name: 'TimedMetadataSchemeIdUri', traits: {"smithy.api#documentation" => "Specify the event message box (eMSG) scheme ID URI for ID3 timed metadata in your output. For more information, see ISO/IEC 23009-1:2022 section 5.10.3.3.4 Semantics. Leave blank to use the default value: https://aomedia.org/emsg/ID3 When you specify a value for ID3 metadata scheme ID URI, you must also set ID3 metadata to Passthrough.", "smithy.api#jsonName" => "timedMetadataSchemeIdUri"}))
    MpdSettings.add_member(:timed_metadata_value, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmax1000, location_name: 'TimedMetadataValue', traits: {"smithy.api#documentation" => "Specify the event message box (eMSG) value for ID3 timed metadata in your output. For more information, see ISO/IEC 23009-1:2022 section 5.10.3.3.4 Semantics. When you specify a value for ID3 Metadata Value, you must also set ID3 metadata to Passthrough.", "smithy.api#jsonName" => "timedMetadataValue"}))
