    Mpeg2IntraDcPrecision.add_member(:intra_dc_precision_9, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTRA_DC_PRECISION_9', traits: {"smithy.api#enumValue" => "INTRA_DC_PRECISION_9"}))
