    Mpeg2QualityTuningLevel.add_member(:multi_pass, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MULTI_PASS', traits: {"smithy.api#enumValue" => "MULTI_PASS"}))
