    NielsenNonLinearWatermarkSettings.add_member(:active_watermark_process, Smithy::Schema::Shapes::ShapeRef.new(shape: NielsenActiveWatermarkProcessType, location_name: 'ActiveWatermarkProcess', traits: {"smithy.api#documentation" => "Choose the type of Nielsen watermarks that you want in your outputs. When you choose NAES 2 and NW, you must provide a value for the setting SID. When you choose CBET, you must provide a value for the setting CSID. When you choose NAES 2, NW, and CBET, you must provide values for both of these settings.", "smithy.api#jsonName" => "activeWatermarkProcess"}))
    NielsenNonLinearWatermarkSettings.add_member(:adi_filename, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3, location_name: 'AdiFilename', traits: {"smithy.api#documentation" => "Optional. Use this setting when you want the service to include an ADI file in the Nielsen metadata .zip file. To provide an ADI file, store it in Amazon S3 and provide a URL to it here. The URL should be in the following format: S3://bucket/path/ADI-file. For more information about the metadata .zip file, see the setting Metadata destination.", "smithy.api#jsonName" => "adiFilename"}))
    NielsenNonLinearWatermarkSettings.add_member(:asset_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max20, location_name: 'AssetId', traits: {"smithy.api#documentation" => "Use the asset ID that you provide to Nielsen to uniquely identify this asset. Required for all Nielsen non-linear watermarking.", "smithy.api#jsonName" => "assetId"}))
    NielsenNonLinearWatermarkSettings.add_member(:asset_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max50, location_name: 'AssetName', traits: {"smithy.api#documentation" => "Use the asset name that you provide to Nielsen for this asset. Required for all Nielsen non-linear watermarking.", "smithy.api#jsonName" => "assetName"}))
    NielsenNonLinearWatermarkSettings.add_member(:cbet_source_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern0xafaf0908190908, location_name: 'CbetSourceId', traits: {"smithy.api#documentation" => "Use the CSID that Nielsen provides to you. This CBET source ID should be unique to your Nielsen account but common to all of your output assets that have CBET watermarking. Required when you choose a value for the setting Watermark types that includes CBET.", "smithy.api#jsonName" => "cbetSourceId"}))
    NielsenNonLinearWatermarkSettings.add_member(:episode_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin1max20, location_name: 'EpisodeId', traits: {"smithy.api#documentation" => "Optional. If this asset uses an episode ID with Nielsen, provide it here.", "smithy.api#jsonName" => "episodeId"}))
    NielsenNonLinearWatermarkSettings.add_member(:metadata_destination, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3, location_name: 'MetadataDestination', traits: {"smithy.api#documentation" => "Specify the Amazon S3 location where you want MediaConvert to save your Nielsen non-linear metadata .zip file. This Amazon S3 bucket must be in the same Region as the one where you do your MediaConvert transcoding. If you want to include an ADI file in this .zip file, use the setting ADI file to specify it. MediaConvert delivers the Nielsen metadata .zip files only to your metadata destination Amazon S3 bucket. It doesn't deliver the .zip files to Nielsen. You are responsible for delivering the metadata .zip files to Nielsen.", "smithy.api#jsonName" => "metadataDestination"}))
    NielsenNonLinearWatermarkSettings.add_member(:source_id, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max65534, location_name: 'SourceId', traits: {"smithy.api#documentation" => "Use the SID that Nielsen provides to you. This source ID should be unique to your Nielsen account but common to all of your output assets. Required for all Nielsen non-linear watermarking. This ID should be unique to your Nielsen account but common to all of your output assets. Required for all Nielsen non-linear watermarking.", "smithy.api#jsonName" => "sourceId"}))
    NielsenNonLinearWatermarkSettings.add_member(:source_watermark_status, Smithy::Schema::Shapes::ShapeRef.new(shape: NielsenSourceWatermarkStatusType, location_name: 'SourceWatermarkStatus', traits: {"smithy.api#documentation" => "Required. Specify whether your source content already contains Nielsen non-linear watermarks. When you set this value to Watermarked, the service fails the job. Nielsen requires that you add non-linear watermarking to only clean content that doesn't already have non-linear Nielsen watermarks.", "smithy.api#jsonName" => "sourceWatermarkStatus"}))
    NielsenNonLinearWatermarkSettings.add_member(:tic_server_url, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatternhttps, location_name: 'TicServerUrl', traits: {"smithy.api#documentation" => "Specify the endpoint for the TIC server that you have deployed and configured in the AWS Cloud. Required for all Nielsen non-linear watermarking. MediaConvert can't connect directly to a TIC server. Instead, you must use API Gateway to provide a RESTful interface between MediaConvert and a TIC server that you deploy in your AWS account. For more information on deploying a TIC server in your AWS account and the required API Gateway, contact Nielsen support.", "smithy.api#jsonName" => "ticServerUrl"}))
    NielsenNonLinearWatermarkSettings.add_member(:unique_tic_per_audio_track, Smithy::Schema::Shapes::ShapeRef.new(shape: NielsenUniqueTicPerAudioTrackType, location_name: 'UniqueTicPerAudioTrack', traits: {"smithy.api#documentation" => "To create assets that have the same TIC values in each audio track, keep the default value Share TICs. To create assets that have unique TIC values for each audio track, choose Use unique TICs.", "smithy.api#jsonName" => "uniqueTicPerAudioTrack"}))
