    NoiseReducer.add_member(:filter, Smithy::Schema::Shapes::ShapeRef.new(shape: NoiseReducerFilter, location_name: 'Filter', traits: {"smithy.api#documentation" => "Use Noise reducer filter to select one of the following spatial image filtering functions. To use this setting, you must also enable Noise reducer. * Bilateral preserves edges while reducing noise. * Mean (softest), Gaussian, Lanczos, and Sharpen (sharpest) do convolution filtering. * Conserve does min/max noise reduction. * Spatial does frequency-domain filtering based on JND principles. * Temporal optimizes video quality for complex motion.", "smithy.api#jsonName" => "filter"}))
    NoiseReducer.add_member(:filter_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: NoiseReducerFilterSettings, location_name: 'FilterSettings', traits: {"smithy.api#documentation" => "Settings for a noise reducer filter", "smithy.api#jsonName" => "filterSettings"}))
