    NoiseReducerFilterSettings.type = Types::NoiseReducerFilterSettings
    NoiseReducerSpatialFilterSettings.add_member(:post_filter_sharpen_strength, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max3, location_name: 'PostFilterSharpenStrength', traits: {"smithy.api#documentation" => "Specify strength of post noise reduction sharpening filter, with 0 disabling the filter and 3 enabling it at maximum strength.", "smithy.api#jsonName" => "postFilterSharpenStrength"}))
