    NoiseReducerSpatialFilterSettings.add_member(:strength, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max16, location_name: 'Strength', traits: {"smithy.api#documentation" => "Relative strength of noise reducing filter. Higher values produce stronger filtering.", "smithy.api#jsonName" => "strength"}))
    NoiseReducerSpatialFilterSettings.type = Types::NoiseReducerSpatialFilterSettings
    NoiseReducerTemporalFilterSettings.add_member(:aggressive_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max4, location_name: 'AggressiveMode', traits: {"smithy.api#documentation" => "Use Aggressive mode for content that has complex motion. Higher values produce stronger temporal filtering. This filters highly complex scenes more aggressively and creates better VQ for low bitrate outputs.", "smithy.api#jsonName" => "aggressiveMode"}))
    NoiseReducerTemporalFilterSettings.add_member(:post_temporal_sharpening, Smithy::Schema::Shapes::ShapeRef.new(shape: NoiseFilterPostTemporalSharpening, location_name: 'PostTemporalSharpening', traits: {"smithy.api#documentation" => "When you set Noise reducer to Temporal, the bandwidth and sharpness of your output is reduced. You can optionally use Post temporal sharpening to apply sharpening to the edges of your output. Note that Post temporal sharpening will also make the bandwidth reduction from the Noise reducer smaller. The default behavior, Auto, allows the transcoder to determine whether to apply sharpening, depending on your input type and quality. When you set Post temporal sharpening to Enabled, specify how much sharpening is applied using Post temporal sharpening strength. Set Post temporal sharpening to Disabled to not apply sharpening.", "smithy.api#jsonName" => "postTemporalSharpening"}))
    NoiseReducerTemporalFilterSettings.add_member(:post_temporal_sharpening_strength, Smithy::Schema::Shapes::ShapeRef.new(shape: NoiseFilterPostTemporalSharpeningStrength, location_name: 'PostTemporalSharpeningStrength', traits: {"smithy.api#documentation" => "Use Post temporal sharpening strength to define the amount of sharpening the transcoder applies to your output. Set Post temporal sharpening strength to Low, Medium, or High to indicate the amount of sharpening.", "smithy.api#jsonName" => "postTemporalSharpeningStrength"}))
    NoiseReducerTemporalFilterSettings.add_member(:speed, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative1max3, location_name: 'Speed', traits: {"smithy.api#documentation" => "The speed of the filter (higher number is faster). Low setting reduces bit rate at the cost of transcode time, high setting improves transcode time at the cost of bit rate.", "smithy.api#jsonName" => "speed"}))
    NoiseReducerTemporalFilterSettings.add_member(:strength, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max16, location_name: 'Strength', traits: {"smithy.api#documentation" => "Specify the strength of the noise reducing filter on this output. Higher values produce stronger filtering. We recommend the following value ranges, depending on the result that you want: * 0-2 for complexity reduction with minimal sharpness loss * 2-8 for complexity reduction with image preservation * 8-16 for a high level of complexity reduction", "smithy.api#jsonName" => "strength"}))
    NoiseReducerTemporalFilterSettings.type = Types::NoiseReducerTemporalFilterSettings
