    Queue.add_member(:concurrent_jobs, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ConcurrentJobs', traits: {"smithy.api#documentation" => "The maximum number of jobs your queue can process concurrently.", "smithy.api#jsonName" => "concurrentJobs"}))
    Queue.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'CreatedAt', traits: {"smithy.api#documentation" => "The timestamp in epoch seconds for when you created the queue.", "smithy.api#jsonName" => "createdAt"}))
    Queue.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "An optional description that you create for each queue.", "smithy.api#jsonName" => "description"}))
    Queue.add_member(:last_updated, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'LastUpdated', traits: {"smithy.api#documentation" => "The timestamp in epoch seconds for when you most recently updated the queue.", "smithy.api#jsonName" => "lastUpdated"}))
    Queue.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "A name that you create for each queue. Each name must be unique within your account.", "smithy.api#jsonName" => "name", "smithy.api#required" => {}}))
    Queue.add_member(:pricing_plan, Smithy::Schema::Shapes::ShapeRef.new(shape: PricingPlan, location_name: 'PricingPlan', traits: {"smithy.api#documentation" => "Specifies whether the pricing plan for the queue is on-demand or reserved. For on-demand, you pay per minute, billed in increments of .01 minute. For reserved, you pay for the transcoding capacity of the entire queue, regardless of how much or how little you use it. Reserved pricing requires a 12-month commitment.", "smithy.api#jsonName" => "pricingPlan"}))
    Queue.add_member(:progressing_jobs_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ProgressingJobsCount', traits: {"smithy.api#documentation" => "The estimated number of jobs with a PROGRESSING status.", "smithy.api#jsonName" => "progressingJobsCount"}))
    Queue.add_member(:reservation_plan, Smithy::Schema::Shapes::ShapeRef.new(shape: ReservationPlan, location_name: 'ReservationPlan', traits: {"smithy.api#documentation" => "Details about the pricing plan for your reserved queue. Required for reserved queues and not applicable to on-demand queues.", "smithy.api#jsonName" => "reservationPlan"}))
    Queue.add_member(:service_overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofserviceoverride, location_name: 'ServiceOverrides', traits: {"smithy.api#documentation" => "A list of any service overrides applied by MediaConvert to the settings that you have configured. If you see any overrides, we recommend that you contact AWS Support.", "smithy.api#jsonName" => "serviceOverrides"}))
    Queue.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "Queues can be ACTIVE or PAUSED. If you pause a queue, the service won't begin processing jobs in that queue. Jobs that are running when you pause the queue continue to run until they finish or result in an error.", "smithy.api#jsonName" => "status"}))
    Queue.add_member(:submitted_jobs_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'SubmittedJobsCount', traits: {"smithy.api#documentation" => "The estimated number of jobs with a SUBMITTED status.", "smithy.api#jsonName" => "submittedJobsCount"}))
    Queue.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: Type, location_name: 'Type', traits: {"smithy.api#documentation" => "Specifies whether this on-demand queue is system or custom. System queues are built in. You can't modify or delete system queues. You can create and modify custom queues.", "smithy.api#jsonName" => "type"}))
    Queue.type = Types::Queue
