    QueueTransition.add_member(:source_queue, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceQueue', traits: {"smithy.api#documentation" => "The queue that the job was on before the transition.", "smithy.api#jsonName" => "sourceQueue"}))
    QueueTransition.add_member(:timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'Timestamp', traits: {"smithy.api#documentation" => "The time, in Unix epoch format, that the job moved from the source queue to the destination queue.", "smithy.api#jsonName" => "timestamp"}))
