    Rectangle.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin2max2147483647, location_name: 'Height', traits: {"smithy.api#documentation" => "Height of rectangle in pixels. Specify only even numbers.", "smithy.api#jsonName" => "height"}))
    Rectangle.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin2max2147483647, location_name: 'Width', traits: {"smithy.api#documentation" => "Width of rectangle in pixels. Specify only even numbers.", "smithy.api#jsonName" => "width"}))
    Rectangle.add_member(:x, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'X', traits: {"smithy.api#documentation" => "The distance, in pixels, between the rectangle and the left edge of the video frame. Specify only even numbers.", "smithy.api#jsonName" => "x"}))
    Rectangle.add_member(:y, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Y', traits: {"smithy.api#documentation" => "The distance, in pixels, between the rectangle and the top edge of the video frame. Specify only even numbers.", "smithy.api#jsonName" => "y"}))
    Rectangle.type = Types::Rectangle
    RemixSettings.add_member(:audio_description_audio_channel, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max64, location_name: 'AudioDescriptionAudioChannel', traits: {"smithy.api#documentation" => "Optionally specify the channel in your input that contains your audio description audio signal. MediaConvert mixes your audio signal across all output channels, while reducing their volume according to your data stream. When you specify an audio description audio channel, you must also specify an audio description data channel. For more information about audio description signals, see the BBC WHP 198 and 051 white papers.", "smithy.api#jsonName" => "audioDescriptionAudioChannel"}))
    RemixSettings.add_member(:audio_description_data_channel, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max64, location_name: 'AudioDescriptionDataChannel', traits: {"smithy.api#documentation" => "Optionally specify the channel in your input that contains your audio description data stream. MediaConvert mixes your audio signal across all output channels, while reducing their volume according to your data stream. When you specify an audio description data channel, you must also specify an audio description audio channel. For more information about audio description signals, see the BBC WHP 198 and 051 white papers.", "smithy.api#jsonName" => "audioDescriptionDataChannel"}))
    RemixSettings.add_member(:channel_mapping, Smithy::Schema::Shapes::ShapeRef.new(shape: ChannelMapping, location_name: 'ChannelMapping', traits: {"smithy.api#documentation" => "Channel mapping contains the group of fields that hold the remixing value for each channel, in dB. Specify remix values to indicate how much of the content from your input audio channel you want in your output audio channels. Each instance of the InputChannels or InputChannelsFineTune array specifies these values for one output channel. Use one instance of this array for each output channel. In the console, each array corresponds to a column in the graphical depiction of the mapping matrix. The rows of the graphical matrix correspond to input channels. Valid values are within the range from -60 (mute) through 6. A setting of 0 passes the input channel unchanged to the output channel (no attenuation or amplification). Use InputChannels or InputChannelsFineTune to specify your remix values. Don't use both.", "smithy.api#jsonName" => "channelMapping"}))
    RemixSettings.add_member(:channels_in, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max64, location_name: 'ChannelsIn', traits: {"smithy.api#documentation" => "Specify the number of audio channels from your input that you want to use in your output. With remixing, you might combine or split the data in these channels, so the number of channels in your final output might be different. If you are doing both input channel mapping and output channel mapping, the number of output channels in your input mapping must be the same as the number of input channels in your output mapping.", "smithy.api#jsonName" => "channelsIn"}))
    RemixSettings.add_member(:channels_out, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max64, location_name: 'ChannelsOut', traits: {"smithy.api#documentation" => "Specify the number of channels in this output after remixing. Valid values: 1, 2, 4, 6, 8... 64. (1 and even numbers to 64.) If you are doing both input channel mapping and output channel mapping, the number of output channels in your input mapping must be the same as the number of input channels in your output mapping.", "smithy.api#jsonName" => "channelsOut"}))
    RemixSettings.type = Types::RemixSettings
    RemoveRubyReserveAttributes.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    RemoveRubyReserveAttributes.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
