    RenewalType.add_member(:expire, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EXPIRE', traits: {"smithy.api#enumValue" => "EXPIRE"}))
    RequiredFlag.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    RequiredFlag.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    ReservationPlan.add_member(:commitment, Smithy::Schema::Shapes::ShapeRef.new(shape: Commitment, location_name: 'Commitment', traits: {"smithy.api#documentation" => "The length of the term of your reserved queue pricing plan commitment.", "smithy.api#jsonName" => "commitment"}))
    ReservationPlan.add_member(:expires_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'ExpiresAt', traits: {"smithy.api#documentation" => "The timestamp in epoch seconds for when the current pricing plan term for this reserved queue expires.", "smithy.api#jsonName" => "expiresAt"}))
    ReservationPlan.add_member(:purchased_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'PurchasedAt', traits: {"smithy.api#documentation" => "The timestamp in epoch seconds for when you set up the current pricing plan for this reserved queue.", "smithy.api#jsonName" => "purchasedAt"}))
    ReservationPlan.add_member(:renewal_type, Smithy::Schema::Shapes::ShapeRef.new(shape: RenewalType, location_name: 'RenewalType', traits: {"smithy.api#documentation" => "Specifies whether the term of your reserved queue pricing plan is automatically extended (AUTO_RENEW) or expires (EXPIRE) at the end of the term.", "smithy.api#jsonName" => "renewalType"}))
    ReservationPlan.add_member(:reserved_slots, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ReservedSlots', traits: {"smithy.api#documentation" => "Specifies the number of reserved transcode slots (RTS) for this queue. The number of RTS determines how many jobs the queue can process in parallel; each RTS can process one job at a time. When you increase this number, you extend your existing commitment with a new 12-month commitment for a larger number of RTS. The new commitment begins when you purchase the additional capacity. You can't decrease the number of RTS in your reserved queue.", "smithy.api#jsonName" => "reservedSlots"}))
    ReservationPlan.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ReservationPlanStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "Specifies whether the pricing plan for your reserved queue is ACTIVE or EXPIRED.", "smithy.api#jsonName" => "status"}))
    ReservationPlan.type = Types::ReservationPlan
    ReservationPlanSettings.add_member(:commitment, Smithy::Schema::Shapes::ShapeRef.new(shape: Commitment, location_name: 'Commitment', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "The length of the term of your reserved queue pricing plan commitment.", "smithy.api#jsonName" => "commitment", "smithy.api#required" => {}}))
    ReservationPlanSettings.add_member(:renewal_type, Smithy::Schema::Shapes::ShapeRef.new(shape: RenewalType, location_name: 'RenewalType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "Specifies whether the term of your reserved queue pricing plan is automatically extended (AUTO_RENEW) or expires (EXPIRE) at the end of the term. When your term is auto renewed, you extend your commitment by 12 months from the auto renew date. You can cancel this commitment.", "smithy.api#jsonName" => "renewalType", "smithy.api#required" => {}}))
    ReservationPlanSettings.add_member(:reserved_slots, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ReservedSlots', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "Specifies the number of reserved transcode slots (RTS) for this queue. The number of RTS determines how many jobs the queue can process in parallel; each RTS can process one job at a time. You can't decrease the number of RTS in your reserved queue. You can increase the number of RTS by extending your existing commitment with a new 12-month commitment for the larger number. The new commitment begins when you purchase the additional capacity. You can't cancel your commitment or revert to your original commitment after you increase the capacity.", "smithy.api#jsonName" => "reservedSlots", "smithy.api#required" => {}}))
    ReservationPlanSettings.type = Types::ReservationPlanSettings
