    UpdateJobTemplateRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#documentation" => "The name of the job template you are modifying", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    UpdateJobTemplateRequest.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative50max50, location_name: 'Priority', traits: {"smithy.api#documentation" => "Specify the relative priority for this job. In any given queue, the service begins processing the job with the highest value first. When more than one job has the same priority, the service begins processing the job that you submitted first. If you don't specify a priority, the service uses the default value 0.", "smithy.api#jsonName" => "priority"}))
    UpdateJobTemplateRequest.add_member(:queue, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Queue', traits: {"smithy.api#documentation" => "The new queue for the job template, if you are changing it.", "smithy.api#jsonName" => "queue"}))
    UpdateJobTemplateRequest.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: JobTemplateSettings, location_name: 'Settings', traits: {"smithy.api#documentation" => "JobTemplateSettings contains all the transcode settings saved in the template that will be applied to jobs created from it.", "smithy.api#jsonName" => "settings"}))
    UpdateJobTemplateRequest.add_member(:status_update_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusUpdateInterval, location_name: 'StatusUpdateInterval', traits: {"smithy.api#documentation" => "Specify how often MediaConvert sends STATUS_UPDATE events to Amazon CloudWatch Events. Set the interval, in seconds, between status updates. MediaConvert sends an update at this interval from the time the service begins processing your job to the time it completes the transcode or encounters an error.", "smithy.api#jsonName" => "statusUpdateInterval"}))
