    UpdateQueueRequest.add_member(:concurrent_jobs, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ConcurrentJobs', traits: {"smithy.api#documentation" => "Specify the maximum number of jobs your queue can process concurrently. For on-demand queues, the value you enter is constrained by your service quotas for Maximum concurrent jobs, per on-demand queue and Maximum concurrent jobs, per account. For reserved queues, update your reservation plan instead in order to increase your yearly commitment.", "smithy.api#jsonName" => "concurrentJobs"}))
