    UpdateQueueRequest.add_member(:reservation_plan_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ReservationPlanSettings, location_name: 'ReservationPlanSettings', traits: {"smithy.api#documentation" => "The new details of your pricing plan for your reserved queue. When you set up a new pricing plan to replace an expired one, you enter into another 12-month commitment. When you add capacity to your queue by increasing the number of RTS, you extend the term of your commitment to 12 months from when you add capacity. After you make these commitments, you can't cancel them.", "smithy.api#jsonName" => "reservationPlanSettings"}))
    UpdateQueueRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "Pause or activate a queue by changing its status between ACTIVE and PAUSED. If you pause a queue, jobs in that queue won't begin. Jobs that are running when you pause the queue continue to run until they finish or result in an error.", "smithy.api#jsonName" => "status"}))
    UpdateQueueRequest.type = Types::UpdateQueueRequest
    UpdateQueueResponse.add_member(:queue, Smithy::Schema::Shapes::ShapeRef.new(shape: Queue, location_name: 'Queue', traits: {"smithy.api#documentation" => "You can use queues to manage the resources that are available to your AWS account for running multiple transcoding jobs at the same time. If you don't specify a queue, the service sends all jobs through the default queue. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/working-with-queues.html.", "smithy.api#jsonName" => "queue"}))
