    VchipAction.add_member(:strip, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STRIP', traits: {"smithy.api#enumValue" => "STRIP"}))
