    VideoCodec.add_member(:gif, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'GIF', traits: {"smithy.api#enumValue" => "GIF"}))
