    VideoCodec.add_member(:h_265, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'H_265', traits: {"smithy.api#enumValue" => "H_265"}))
