    VideoCodec.add_member(:passthrough, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PASSTHROUGH', traits: {"smithy.api#enumValue" => "PASSTHROUGH"}))
