    VideoCodec.add_member(:vp8, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'VP8', traits: {"smithy.api#enumValue" => "VP8"}))
    VideoCodec.add_member(:vp9, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'VP9', traits: {"smithy.api#enumValue" => "VP9"}))
