    VideoCodecSettings.add_member(:av1_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1Settings, location_name: 'Av1Settings', traits: {"smithy.api#documentation" => "Required when you set Codec, under VideoDescription>CodecSettings to the value AV1.", "smithy.api#jsonName" => "av1Settings"}))
    VideoCodecSettings.add_member(:avc_intra_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AvcIntraSettings, location_name: 'AvcIntraSettings', traits: {"smithy.api#documentation" => "Required when you choose AVC-Intra for your output video codec. For more information about the AVC-Intra settings, see the relevant specification. For detailed information about SD and HD in AVC-Intra, see https://ieeexplore.ieee.org/document/7290936. For information about 4K/2K in AVC-Intra, see https://pro-av.panasonic.net/en/avc-ultra/AVC-ULTRAoverview.pdf.", "smithy.api#jsonName" => "avcIntraSettings"}))
    VideoCodecSettings.add_member(:codec, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoCodec, location_name: 'Codec', traits: {"smithy.api#documentation" => "Specifies the video codec. This must be equal to one of the enum values defined by the object VideoCodec. To passthrough the video stream of your input without any video encoding: Choose Passthrough. More information about passthrough codec support and job settings requirements, see: https://docs.aws.amazon.com/mediaconvert/latest/ug/video-passthrough-feature-restrictions.html", "smithy.api#jsonName" => "codec"}))
    VideoCodecSettings.add_member(:frame_capture_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: FrameCaptureSettings, location_name: 'FrameCaptureSettings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value FRAME_CAPTURE.", "smithy.api#jsonName" => "frameCaptureSettings"}))
    VideoCodecSettings.add_member(:gif_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: GifSettings, location_name: 'GifSettings', traits: {"smithy.api#documentation" => "Required when you set (Codec) under (VideoDescription)>(CodecSettings) to the value GIF", "smithy.api#jsonName" => "gifSettings"}))
    VideoCodecSettings.add_member(:h264_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: H264Settings, location_name: 'H264Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value H_264.", "smithy.api#jsonName" => "h264Settings"}))
    VideoCodecSettings.add_member(:h265_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: H265Settings, location_name: 'H265Settings', traits: {"smithy.api#documentation" => "Settings for H265 codec", "smithy.api#jsonName" => "h265Settings"}))
    VideoCodecSettings.add_member(:mpeg2_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2Settings, location_name: 'Mpeg2Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value MPEG2.", "smithy.api#jsonName" => "mpeg2Settings"}))
    VideoCodecSettings.add_member(:prores_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ProresSettings, location_name: 'ProresSettings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value PRORES.", "smithy.api#jsonName" => "proresSettings"}))
    VideoCodecSettings.add_member(:uncompressed_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: UncompressedSettings, location_name: 'UncompressedSettings', traits: {"smithy.api#documentation" => "Required when you set Codec, under VideoDescription>CodecSettings to the value UNCOMPRESSED.", "smithy.api#jsonName" => "uncompressedSettings"}))
    VideoCodecSettings.add_member(:vc3_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Vc3Settings, location_name: 'Vc3Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value VC3", "smithy.api#jsonName" => "vc3Settings"}))
    VideoCodecSettings.add_member(:vp8_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp8Settings, location_name: 'Vp8Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value VP8.", "smithy.api#jsonName" => "vp8Settings"}))
    VideoCodecSettings.add_member(:vp9_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp9Settings, location_name: 'Vp9Settings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value VP9.", "smithy.api#jsonName" => "vp9Settings"}))
    VideoCodecSettings.add_member(:xavc_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: XavcSettings, location_name: 'XavcSettings', traits: {"smithy.api#documentation" => "Required when you set Codec to the value XAVC.", "smithy.api#jsonName" => "xavcSettings"}))
    VideoCodecSettings.type = Types::VideoCodecSettings
    VideoDescription.add_member(:afd_signaling, Smithy::Schema::Shapes::ShapeRef.new(shape: AfdSignaling, location_name: 'AfdSignaling', traits: {"smithy.api#documentation" => "This setting only applies to H.264, H.265, and MPEG2 outputs. Use Insert AFD signaling to specify whether the service includes AFD values in the output video data and what those values are. * Choose None to remove all AFD values from this output. * Choose Fixed to ignore input AFD values and instead encode the value specified in the job. * Choose Auto to calculate output AFD values based on the input AFD scaler data.", "smithy.api#jsonName" => "afdSignaling"}))
    VideoDescription.add_member(:anti_alias, Smithy::Schema::Shapes::ShapeRef.new(shape: AntiAlias, location_name: 'AntiAlias', traits: {"smithy.api#documentation" => "The anti-alias filter is automatically applied to all outputs. The service no longer accepts the value DISABLED for AntiAlias. If you specify that in your job, the service will ignore the setting.", "smithy.api#jsonName" => "antiAlias"}))
    VideoDescription.add_member(:chroma_position_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ChromaPositionMode, location_name: 'ChromaPositionMode', traits: {"smithy.api#documentation" => "Specify the chroma sample positioning metadata for your H.264 or H.265 output. To have MediaConvert automatically determine chroma positioning: We recommend that you keep the default value, Auto. To specify center positioning: Choose Force center. To specify top left positioning: Choose Force top left.", "smithy.api#jsonName" => "chromaPositionMode"}))
    VideoDescription.add_member(:codec_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoCodecSettings, location_name: 'CodecSettings', traits: {"smithy.api#documentation" => "Video codec settings contains the group of settings related to video encoding. The settings in this group vary depending on the value that you choose for Video codec. For each codec enum that you choose, define the corresponding settings object. The following lists the codec enum, settings object pairs. * AV1, Av1Settings * AVC_INTRA, AvcIntraSettings * FRAME_CAPTURE, FrameCaptureSettings * GIF, GifSettings * H_264, H264Settings * H_265, H265Settings * MPEG2, Mpeg2Settings * PRORES, ProresSettings * UNCOMPRESSED, UncompressedSettings * VC3, Vc3Settings * VP8, Vp8Settings * VP9, Vp9Settings * XAVC, XavcSettings", "smithy.api#jsonName" => "codecSettings"}))
    VideoDescription.add_member(:color_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorMetadata, location_name: 'ColorMetadata', traits: {"smithy.api#documentation" => "Choose Insert for this setting to include color metadata in this output. Choose Ignore to exclude color metadata from this output. If you don't specify a value, the service sets this to Insert by default.", "smithy.api#jsonName" => "colorMetadata"}))
    VideoDescription.add_member(:crop, Smithy::Schema::Shapes::ShapeRef.new(shape: Rectangle, location_name: 'Crop', traits: {"smithy.api#documentation" => "Use Cropping selection to specify the video area that the service will include in the output video frame.", "smithy.api#jsonName" => "crop"}))
    VideoDescription.add_member(:drop_frame_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: DropFrameTimecode, location_name: 'DropFrameTimecode', traits: {"smithy.api#documentation" => "Applies only to 29.97 fps outputs. When this feature is enabled, the service will use drop-frame timecode on outputs. If it is not possible to use drop-frame timecode, the system will fall back to non-drop-frame. This setting is enabled by default when Timecode insertion or Timecode track is enabled.", "smithy.api#jsonName" => "dropFrameTimecode"}))
    VideoDescription.add_member(:fixed_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max15, location_name: 'FixedAfd', traits: {"smithy.api#documentation" => "Applies only if you set AFD Signaling to Fixed. Use Fixed to specify a four-bit AFD value which the service will write on all frames of this video output.", "smithy.api#jsonName" => "fixedAfd"}))
    VideoDescription.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8192, location_name: 'Height', traits: {"smithy.api#documentation" => "Use Height to define the video resolution height, in pixels, for this output. To use the same resolution as your input: Leave both Width and Height blank. To evenly scale from your input resolution: Leave Height blank and enter a value for Width. For example, if your input is 1920x1080 and you set Width to 1280, your output will be 1280x720.", "smithy.api#jsonName" => "height"}))
    VideoDescription.add_member(:position, Smithy::Schema::Shapes::ShapeRef.new(shape: Rectangle, location_name: 'Position', traits: {"smithy.api#documentation" => "Use Selection placement to define the video area in your output frame. The area outside of the rectangle that you specify here is black.", "smithy.api#jsonName" => "position"}))
    VideoDescription.add_member(:respond_to_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: RespondToAfd, location_name: 'RespondToAfd', traits: {"smithy.api#documentation" => "Use Respond to AFD to specify how the service changes the video itself in response to AFD values in the input. * Choose Respond to clip the input video frame according to the AFD value, input display aspect ratio, and output display aspect ratio. * Choose Passthrough to include the input AFD values. Do not choose this when AfdSignaling is set to NONE. A preferred implementation of this workflow is to set RespondToAfd to and set AfdSignaling to AUTO. * Choose None to remove all input AFD values from this output.", "smithy.api#jsonName" => "respondToAfd"}))
    VideoDescription.add_member(:scaling_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingBehavior, location_name: 'ScalingBehavior', traits: {"smithy.api#documentation" => "Specify the video Scaling behavior when your output has a different resolution than your input. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/video-scaling.html", "smithy.api#jsonName" => "scalingBehavior"}))
    VideoDescription.add_member(:sharpness, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max100, location_name: 'Sharpness', traits: {"smithy.api#documentation" => "Use Sharpness setting to specify the strength of anti-aliasing. This setting changes the width of the anti-alias filter kernel used for scaling. Sharpness only applies if your output resolution is different from your input resolution. 0 is the softest setting, 100 the sharpest, and 50 recommended for most content.", "smithy.api#jsonName" => "sharpness"}))
    VideoDescription.add_member(:timecode_insertion, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoTimecodeInsertion, location_name: 'TimecodeInsertion', traits: {"smithy.api#documentation" => "Applies only to H.264, H.265, MPEG2, and ProRes outputs. Only enable Timecode insertion when the input frame rate is identical to the output frame rate. To include timecodes in this output, set Timecode insertion to PIC_TIMING_SEI. To leave them out, set it to DISABLED. Default is DISABLED. When the service inserts timecodes in an output, by default, it uses any embedded timecodes from the input. If none are present, the service will set the timecode for the first output frame to zero. To change this default behavior, adjust the settings under Timecode configuration. In the console, these settings are located under Job > Job settings > Timecode configuration. Note - Timecode source under input settings does not affect the timecodes that are inserted in the output. Source under Job settings > Timecode configuration does.", "smithy.api#jsonName" => "timecodeInsertion"}))
    VideoDescription.add_member(:timecode_track, Smithy::Schema::Shapes::ShapeRef.new(shape: TimecodeTrack, location_name: 'TimecodeTrack', traits: {"smithy.api#documentation" => "To include a timecode track in your MP4 output: Choose Enabled. MediaConvert writes the timecode track in the Null Media Header box (NMHD), without any timecode text formatting information. You can also specify dropframe or non-dropframe timecode under the Drop Frame Timecode setting. To not include a timecode track: Keep the default value, Disabled.", "smithy.api#jsonName" => "timecodeTrack"}))
    VideoDescription.add_member(:video_preprocessors, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoPreprocessor, location_name: 'VideoPreprocessors', traits: {"smithy.api#documentation" => "Find additional transcoding features under Preprocessors. Enable the features at each output individually. These features are disabled by default.", "smithy.api#jsonName" => "videoPreprocessors"}))
    VideoDescription.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin32max8192, location_name: 'Width', traits: {"smithy.api#documentation" => "Use Width to define the video resolution width, in pixels, for this output. To use the same resolution as your input: Leave both Width and Height blank. To evenly scale from your input resolution: Leave Width blank and enter a value for Height. For example, if your input is 1920x1080 and you set Height to 720, your output will be 1280x720.", "smithy.api#jsonName" => "width"}))
    VideoDescription.type = Types::VideoDescription
    VideoDetail.add_member(:height_in_px, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'HeightInPx', traits: {"smithy.api#documentation" => "Height in pixels for the output", "smithy.api#jsonName" => "heightInPx"}))
    VideoDetail.add_member(:width_in_px, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'WidthInPx', traits: {"smithy.api#documentation" => "Width in pixels for the output", "smithy.api#jsonName" => "widthInPx"}))
    VideoDetail.type = Types::VideoDetail
    VideoOverlay.add_member(:crop, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayCrop, location_name: 'Crop', traits: {"smithy.api#documentation" => "Specify a rectangle of content to crop and use from your video overlay's input video. When you do, MediaConvert uses the cropped dimensions that you specify under X offset, Y offset, Width, and Height.", "smithy.api#jsonName" => "crop"}))
    VideoOverlay.add_member(:end_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092, location_name: 'EndTimecode', traits: {"smithy.api#documentation" => "Enter the end timecode in the base input video for this overlay. Your overlay will be active through this frame. To display your video overlay for the duration of the base input video: Leave blank. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS isthe second, and FF is the frame number. When entering this value, take into account your choice for the base input video's timecode source. For example, if you have embedded timecodes that start at 01:00:00:00 and you want your overlay to end ten minutes into the video, enter 01:10:00:00.", "smithy.api#jsonName" => "endTimecode"}))
    VideoOverlay.add_member(:initial_position, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayPosition, location_name: 'InitialPosition', traits: {"smithy.api#documentation" => "Specify the Initial position of your video overlay. To specify the Initial position of your video overlay, including distance from the left or top edge of the base input video's frame, or size: Enter a value for X position, Y position, Width, or Height. To use the full frame of the base input video: Leave blank.", "smithy.api#jsonName" => "initialPosition"}))
    VideoOverlay.add_member(:input, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayInput, location_name: 'Input', traits: {"smithy.api#documentation" => "Input settings for Video overlay. You can include one or more video overlays in sequence at different times that you specify.", "smithy.api#jsonName" => "input"}))
    VideoOverlay.add_member(:playback, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayPlayBackMode, location_name: 'Playback', traits: {"smithy.api#documentation" => "Specify whether your video overlay repeats or plays only once. To repeat your video overlay on a loop: Keep the default value, Repeat. Your overlay will repeat for the duration of the base input video. To playback your video overlay only once: Choose Once. With either option, you can end playback at a time that you specify by entering a value for End timecode.", "smithy.api#jsonName" => "playback"}))
    VideoOverlay.add_member(:start_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092, location_name: 'StartTimecode', traits: {"smithy.api#documentation" => "Enter the start timecode in the base input video for this overlay. Your overlay will be active starting with this frame. To display your video overlay starting at the beginning of the base input video: Leave blank. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When entering this value, take into account your choice for the base input video's timecode source. For example, if you have embedded timecodes that start at 01:00:00:00 and you want your overlay to begin five minutes into the video, enter 01:05:00:00.", "smithy.api#jsonName" => "startTimecode"}))
    VideoOverlay.add_member(:transitions, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofvideooverlaytransition, location_name: 'Transitions', traits: {"smithy.api#documentation" => "Specify one or more transitions for your video overlay. Use Transitions to reposition or resize your overlay over time. To use the same position and size for the duration of your video overlay: Leave blank. To specify a Transition: Enter a value for Start timecode, End Timecode, X Position, Y Position, Width, or Height.", "smithy.api#jsonName" => "transitions"}))
    VideoOverlay.type = Types::VideoOverlay
    VideoOverlayCrop.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Height', traits: {"smithy.api#documentation" => "Specify the height of the video overlay cropping rectangle. To use the same height as your overlay input video: Keep blank, or enter 0. To specify a different height for the cropping rectangle: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 100 and choose Pixels, the cropping rectangle will be 100 pixels high. When you enter 10, choose Percentage, and your overlay input video is 1920x1080, the cropping rectangle will be 108 pixels high.", "smithy.api#jsonName" => "height"}))
    VideoOverlayCrop.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayUnit, location_name: 'Unit', traits: {"smithy.api#documentation" => "Specify the Unit type to use when you enter a value for X position, Y position, Width, or Height. You can choose Pixels or Percentage. Leave blank to use the default value, Pixels.", "smithy.api#jsonName" => "unit"}))
    VideoOverlayCrop.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Width', traits: {"smithy.api#documentation" => "Specify the width of the video overlay cropping rectangle. To use the same width as your overlay input video: Keep blank, or enter 0. To specify a different width for the cropping rectangle: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 100 and choose Pixels, the cropping rectangle will be 100 pixels wide. When you enter 10, choose Percentage, and your overlay input video is 1920x1080, the cropping rectangle will be 192 pixels wide.", "smithy.api#jsonName" => "width"}))
    VideoOverlayCrop.add_member(:x, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'X', traits: {"smithy.api#documentation" => "Specify the distance between the cropping rectangle and the left edge of your overlay video's frame. To position the cropping rectangle along the left edge: Keep blank, or enter 0. To position the cropping rectangle to the right, relative to the left edge of your overlay video's frame: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 10 and choose Pixels, the cropping rectangle will be positioned 10 pixels from the left edge of the overlay video's frame. When you enter 10, choose Percentage, and your overlay input video is 1920x1080, the cropping rectangle will be positioned 192 pixels from the left edge of the overlay video's frame.", "smithy.api#jsonName" => "x"}))
    VideoOverlayCrop.add_member(:y, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'Y', traits: {"smithy.api#documentation" => "Specify the distance between the cropping rectangle and the top edge of your overlay video's frame. To position the cropping rectangle along the top edge: Keep blank, or enter 0. To position the cropping rectangle down, relative to the top edge of your overlay video's frame: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 10 and choose Pixels, the cropping rectangle will be positioned 10 pixels from the top edge of the overlay video's frame. When you enter 10, choose Percentage, and your overlay input video is 1920x1080, the cropping rectangle will be positioned 108 pixels from the top edge of the overlay video's frame.", "smithy.api#jsonName" => "y"}))
    VideoOverlayCrop.type = Types::VideoOverlayCrop
    VideoOverlayInput.add_member(:file_input, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpatterns3https, location_name: 'FileInput', traits: {"smithy.api#documentation" => "Specify the input file S3, HTTP, or HTTPS URL for your video overlay.\nTo specify one or more Transitions for your base input video instead: Leave blank.", "smithy.api#jsonName" => "fileInput"}))
    VideoOverlayInput.add_member(:input_clippings, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofvideooverlayinputclipping, location_name: 'InputClippings', traits: {"smithy.api#documentation" => "Specify one or more clips to use from your video overlay. When you include an input clip, you must also specify its start timecode, end timecode, or both start and end timecode.", "smithy.api#jsonName" => "inputClippings"}))
    VideoOverlayInput.add_member(:timecode_source, Smithy::Schema::Shapes::ShapeRef.new(shape: InputTimecodeSource, location_name: 'TimecodeSource', traits: {"smithy.api#documentation" => "Specify the timecode source for your video overlay input clips. To use the timecode present in your video overlay: Choose Embedded. To use a zerobased timecode: Choose Start at 0. To choose a timecode: Choose Specified start. When you do, enter the starting timecode in Start timecode. If you don't specify a value for Timecode source, MediaConvert uses Embedded by default.", "smithy.api#jsonName" => "timecodeSource"}))
    VideoOverlayInput.add_member(:timecode_start, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin11max11pattern01d20305d205d, location_name: 'TimecodeStart', traits: {"smithy.api#documentation" => "Specify the starting timecode for this video overlay. To use this setting, you must set Timecode source to Specified start.", "smithy.api#jsonName" => "timecodeStart"}))
    VideoOverlayInput.type = Types::VideoOverlayInput
    VideoOverlayInputClipping.add_member(:end_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092090909, location_name: 'EndTimecode', traits: {"smithy.api#documentation" => "Specify the timecode of the last frame to include in your video overlay's clip. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When entering this value, take into account your choice for Timecode source.", "smithy.api#jsonName" => "endTimecode"}))
    VideoOverlayInputClipping.add_member(:start_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092090909, location_name: 'StartTimecode', traits: {"smithy.api#documentation" => "Specify the timecode of the first frame to include in your video overlay's clip. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When entering this value, take into account your choice for Timecode source.", "smithy.api#jsonName" => "startTimecode"}))
    VideoOverlayInputClipping.type = Types::VideoOverlayInputClipping
    VideoOverlayPlayBackMode.add_member(:once, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ONCE', traits: {"smithy.api#enumValue" => "ONCE"}))
    VideoOverlayPlayBackMode.add_member(:repeat, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'REPEAT', traits: {"smithy.api#enumValue" => "REPEAT"}))
    VideoOverlayPosition.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative1max2147483647, location_name: 'Height', traits: {"smithy.api#documentation" => "To scale your video overlay to the same height as the base input video: Leave blank. To scale the height of your video overlay to a different height: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 360 and choose Pixels, your video overlay will be rendered with a height of 360. When you enter 50, choose Percentage, and your overlay's source has a height of 1080, your video overlay will be rendered with a height of 540. To scale your overlay to a specific height while automatically maintaining its original aspect ratio, enter a value for Height and leave Width blank.", "smithy.api#jsonName" => "height"}))
    VideoOverlayPosition.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayUnit, location_name: 'Unit', traits: {"smithy.api#documentation" => "Specify the Unit type to use when you enter a value for X position, Y position, Width, or Height. You can choose Pixels or Percentage. Leave blank to use the default value, Pixels.", "smithy.api#jsonName" => "unit"}))
    VideoOverlayPosition.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative1max2147483647, location_name: 'Width', traits: {"smithy.api#documentation" => "To scale your video overlay to the same width as the base input video: Leave blank. To scale the width of your video overlay to a different width: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 640 and choose Pixels, your video overlay will scale to a height of 640 pixels. When you enter 50, choose Percentage, and your overlay's source has a width of 1920, your video overlay will scale to a width of 960. To scale your overlay to a specific width while automatically maintaining its original aspect ratio, enter a value for Width and leave Height blank.", "smithy.api#jsonName" => "width"}))
    VideoOverlayPosition.add_member(:x_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'XPosition', traits: {"smithy.api#documentation" => "To position the left edge of your video overlay along the left edge of the base input video's frame: Keep blank, or enter 0. To position the left edge of your video overlay to the right, relative to the left edge of the base input video's frame: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 10 and choose Pixels, your video overlay will be positioned 10 pixels from the left edge of the base input video's frame. When you enter 10, choose Percentage, and your base input video is 1920x1080, your video overlay will be positioned 192 pixels from the left edge of the base input video's frame.", "smithy.api#jsonName" => "xPosition"}))
    VideoOverlayPosition.add_member(:y_position, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'YPosition', traits: {"smithy.api#documentation" => "To position the top edge of your video overlay along the top edge of the base input video's frame: Keep blank, or enter 0. To position the top edge of your video overlay down, relative to the top edge of the base input video's frame: Enter an integer representing the Unit type that you choose, either Pixels or Percentage. For example, when you enter 10 and choose Pixels, your video overlay will be positioned 10 pixels from the top edge of the base input video's frame. When you enter 10, choose Percentage, and your underlying video is 1920x1080, your video overlay will be positioned 108 pixels from the top edge of the base input video's frame.", "smithy.api#jsonName" => "yPosition"}))
    VideoOverlayPosition.type = Types::VideoOverlayPosition
    VideoOverlayTransition.add_member(:end_position, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoOverlayPosition, location_name: 'EndPosition', traits: {"smithy.api#documentation" => "Specify the ending position for this transition, relative to the base input video's frame. Your video overlay will move smoothly to this position, beginning at this transition's Start timecode and ending at this transition's End timecode.", "smithy.api#jsonName" => "endPosition"}))
    VideoOverlayTransition.add_member(:end_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092, location_name: 'EndTimecode', traits: {"smithy.api#documentation" => "Specify the timecode for when this transition ends. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When entering this value, take into account your choice for Timecode source.", "smithy.api#jsonName" => "endTimecode"}))
    VideoOverlayTransition.add_member(:start_timecode, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringpattern010920405090509092, location_name: 'StartTimecode', traits: {"smithy.api#documentation" => "Specify the timecode for when this transition begins. Use the format HH:MM:SS:FF or HH:MM:SS;FF, where HH is the hour, MM is the minute, SS is the second, and FF is the frame number. When entering this value, take into account your choice for Timecode source.", "smithy.api#jsonName" => "startTimecode"}))
    VideoOverlayTransition.type = Types::VideoOverlayTransition
    VideoOverlayUnit.add_member(:pixels, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PIXELS', traits: {"smithy.api#enumValue" => "PIXELS"}))
    VideoOverlayUnit.add_member(:percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PERCENTAGE', traits: {"smithy.api#enumValue" => "PERCENTAGE"}))
    VideoPreprocessor.add_member(:color_corrector, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorCorrector, location_name: 'ColorCorrector', traits: {"smithy.api#documentation" => "Use these settings to convert the color space or to modify properties such as hue and contrast for this output. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/converting-the-color-space.html.", "smithy.api#jsonName" => "colorCorrector"}))
    VideoPreprocessor.add_member(:deinterlacer, Smithy::Schema::Shapes::ShapeRef.new(shape: Deinterlacer, location_name: 'Deinterlacer', traits: {"smithy.api#documentation" => "Use the deinterlacer to produce smoother motion and a clearer picture. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/working-with-scan-type.html.", "smithy.api#jsonName" => "deinterlacer"}))
    VideoPreprocessor.add_member(:dolby_vision, Smithy::Schema::Shapes::ShapeRef.new(shape: DolbyVision, location_name: 'DolbyVision', traits: {"smithy.api#documentation" => "Enable Dolby Vision feature to produce Dolby Vision compatible video output.", "smithy.api#jsonName" => "dolbyVision"}))
    VideoPreprocessor.add_member(:hdr10_plus, Smithy::Schema::Shapes::ShapeRef.new(shape: Hdr10Plus, location_name: 'Hdr10Plus', traits: {"smithy.api#documentation" => "Enable HDR10+ analysis and metadata injection. Compatible with HEVC only.", "smithy.api#jsonName" => "hdr10Plus"}))
    VideoPreprocessor.add_member(:image_inserter, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageInserter, location_name: 'ImageInserter', traits: {"smithy.api#documentation" => "Enable the Image inserter feature to include a graphic overlay on your video. Enable or disable this feature for each output individually. This setting is disabled by default.", "smithy.api#jsonName" => "imageInserter"}))
    VideoPreprocessor.add_member(:noise_reducer, Smithy::Schema::Shapes::ShapeRef.new(shape: NoiseReducer, location_name: 'NoiseReducer', traits: {"smithy.api#documentation" => "Enable the Noise reducer feature to remove noise from your video output if necessary. Enable or disable this feature for each output individually. This setting is disabled by default. When you enable Noise reducer, you must also select a value for Noise reducer filter. For AVC outputs, when you include Noise reducer, you cannot include the Bandwidth reduction filter.", "smithy.api#jsonName" => "noiseReducer"}))
    VideoPreprocessor.add_member(:partner_watermarking, Smithy::Schema::Shapes::ShapeRef.new(shape: PartnerWatermarking, location_name: 'PartnerWatermarking', traits: {"smithy.api#documentation" => "If you work with a third party video watermarking partner, use the group of settings that correspond with your watermarking partner to include watermarks in your output.", "smithy.api#jsonName" => "partnerWatermarking"}))
    VideoPreprocessor.add_member(:timecode_burnin, Smithy::Schema::Shapes::ShapeRef.new(shape: TimecodeBurnin, location_name: 'TimecodeBurnin', traits: {"smithy.api#documentation" => "Settings for burning the output timecode and specified prefix into the output.", "smithy.api#jsonName" => "timecodeBurnin"}))
    VideoPreprocessor.type = Types::VideoPreprocessor
    VideoProperties.add_member(:bit_depth, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'BitDepth', traits: {"smithy.api#documentation" => "The bit depth of the video track.", "smithy.api#jsonName" => "bitDepth"}))
    VideoProperties.add_member(:bit_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'BitRate', traits: {"smithy.api#documentation" => "The bit rate of the video track, in bits per second.", "smithy.api#jsonName" => "bitRate"}))
    VideoProperties.add_member(:color_primaries, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorPrimaries, location_name: 'ColorPrimaries', traits: {"smithy.api#documentation" => "The color space color primaries of the video track.", "smithy.api#jsonName" => "colorPrimaries"}))
    VideoProperties.add_member(:frame_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: FrameRate, location_name: 'FrameRate', traits: {"smithy.api#documentation" => "The frame rate of the video or audio track.", "smithy.api#jsonName" => "frameRate"}))
    VideoProperties.add_member(:height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Height', traits: {"smithy.api#documentation" => "The height of the video track, in pixels.", "smithy.api#jsonName" => "height"}))
    VideoProperties.add_member(:matrix_coefficients, Smithy::Schema::Shapes::ShapeRef.new(shape: MatrixCoefficients, location_name: 'MatrixCoefficients', traits: {"smithy.api#documentation" => "The color space matrix coefficients of the video track.", "smithy.api#jsonName" => "matrixCoefficients"}))
    VideoProperties.add_member(:transfer_characteristics, Smithy::Schema::Shapes::ShapeRef.new(shape: TransferCharacteristics, location_name: 'TransferCharacteristics', traits: {"smithy.api#documentation" => "The color space transfer characteristics of the video track.", "smithy.api#jsonName" => "transferCharacteristics"}))
    VideoProperties.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Width', traits: {"smithy.api#documentation" => "The width of the video track, in pixels.", "smithy.api#jsonName" => "width"}))
    VideoProperties.type = Types::VideoProperties
    VideoSelector.add_member(:alpha_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: AlphaBehavior, location_name: 'AlphaBehavior', traits: {"smithy.api#documentation" => "Ignore this setting unless this input is a QuickTime animation with an alpha channel. Use this setting to create separate Key and Fill outputs. In each output, specify which part of the input MediaConvert uses. Leave this setting at the default value DISCARD to delete the alpha channel and preserve the video. Set it to REMAP_TO_LUMA to delete the video and map the alpha channel to the luma channel of your outputs.", "smithy.api#jsonName" => "alphaBehavior"}))
    VideoSelector.add_member(:color_space, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorSpace, location_name: 'ColorSpace', traits: {"smithy.api#documentation" => "If your input video has accurate color space metadata, or if you don't know about color space: Keep the default value, Follow. MediaConvert will automatically detect your input color space. If your input video has metadata indicating the wrong color space, or has missing metadata: Specify the accurate color space here. If your input video is HDR 10 and the SMPTE ST 2086 Mastering Display Color Volume static metadata isn't present in your video stream, or if that metadata is present but not accurate: Choose Force HDR 10. Specify correct values in the input HDR 10 metadata settings. For more information about HDR jobs, see https://docs.aws.amazon.com/console/mediaconvert/hdr. When you specify an input color space, MediaConvert uses the following color space metadata, which includes color primaries, transfer characteristics, and matrix coefficients:\n * HDR 10: BT.2020, PQ, BT.2020 non-constant\n * HLG 2020: BT.2020, HLG, BT.2020 non-constant\n * P3DCI (Theater): DCIP3, SMPTE 428M, BT.709\n * P3D65 (SDR): Display P3, sRGB, BT.709\n * P3D65 (HDR): Display P3, PQ, BT.709", "smithy.api#jsonName" => "colorSpace"}))
    VideoSelector.add_member(:color_space_usage, Smithy::Schema::Shapes::ShapeRef.new(shape: ColorSpaceUsage, location_name: 'ColorSpaceUsage', traits: {"smithy.api#documentation" => "There are two sources for color metadata, the input file and the job input settings Color space and HDR master display information settings. The Color space usage setting determines which takes precedence. Choose Force to use color metadata from the input job settings. If you don't specify values for those settings, the service defaults to using metadata from your input. FALLBACK - Choose Fallback to use color metadata from the source when it is present. If there's no color metadata in your input file, the service defaults to using values you specify in the input settings.", "smithy.api#jsonName" => "colorSpaceUsage"}))
    VideoSelector.add_member(:embedded_timecode_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EmbeddedTimecodeOverride, location_name: 'EmbeddedTimecodeOverride', traits: {"smithy.api#documentation" => "Set Embedded timecode override to Use MDPM when your AVCHD input contains timecode tag data in the Modified Digital Video Pack Metadata. When you do, we recommend you also set Timecode source to Embedded. Leave Embedded timecode override blank, or set to None, when your input does not contain MDPM timecode.", "smithy.api#jsonName" => "embeddedTimecodeOverride"}))
    VideoSelector.add_member(:hdr10_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: Hdr10Metadata, location_name: 'Hdr10Metadata', traits: {"smithy.api#documentation" => "Use these settings to provide HDR 10 metadata that is missing or inaccurate in your input video. Appropriate values vary depending on the input video and must be provided by a color grader. The color grader generates these values during the HDR 10 mastering process. The valid range for each of these settings is 0 to 50,000. Each increment represents 0.00002 in CIE1931 color coordinate. Related settings - When you specify these values, you must also set Color space to HDR 10. To specify whether the the values you specify here take precedence over the values in the metadata of your input file, set Color space usage. To specify whether color metadata is included in an output, set Color metadata. For more information about MediaConvert HDR jobs, see https://docs.aws.amazon.com/console/mediaconvert/hdr.", "smithy.api#jsonName" => "hdr10Metadata"}))
    VideoSelector.add_member(:max_luminance, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'MaxLuminance', traits: {"smithy.api#documentation" => "Specify the maximum mastering display luminance. Enter an integer from 0 to 2147483647, in units of 0.0001 nits. For example, enter 10000000 for 1000 nits.", "smithy.api#jsonName" => "maxLuminance"}))
    VideoSelector.add_member(:pad_video, Smithy::Schema::Shapes::ShapeRef.new(shape: PadVideo, location_name: 'PadVideo', traits: {"smithy.api#documentation" => "Use this setting if your input has video and audio durations that don't align, and your output or player has strict alignment requirements. Examples: Input audio track has a delayed start. Input video track ends before audio ends. When you set Pad video to Black, MediaConvert generates black video frames so that output video and audio durations match. Black video frames are added at the beginning or end, depending on your input. To keep the default behavior and not generate black video, set Pad video to Disabled or leave blank.", "smithy.api#jsonName" => "padVideo"}))
    VideoSelector.add_member(:pid, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'Pid', traits: {"smithy.api#documentation" => "Use PID to select specific video data from an input file. Specify this value as an integer; the system automatically converts it to the hexidecimal value. For example, 257 selects PID 0x101. A PID, or packet identifier, is an identifier for a set of data in an MPEG-2 transport stream container.", "smithy.api#jsonName" => "pid"}))
    VideoSelector.add_member(:program_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative2147483648max2147483647, location_name: 'ProgramNumber', traits: {"smithy.api#documentation" => "Selects a specific program from within a multi-program transport stream. Note that Quad 4K is not currently supported.", "smithy.api#jsonName" => "programNumber"}))
    VideoSelector.add_member(:rotate, Smithy::Schema::Shapes::ShapeRef.new(shape: InputRotate, location_name: 'Rotate', traits: {"smithy.api#documentation" => "Use Rotate to specify how the service rotates your video. You can choose automatic rotation or specify a rotation. You can specify a clockwise rotation of 0, 90, 180, or 270 degrees. If your input video container is .mov or .mp4 and your input has rotation metadata, you can choose Automatic to have the service rotate your video according to the rotation specified in the metadata. The rotation must be within one degree of 90, 180, or 270 degrees. If the rotation metadata specifies any other rotation, the service will default to no rotation. By default, the service does no rotation, even if your input video has rotation metadata. The service doesn't pass through rotation metadata.", "smithy.api#jsonName" => "rotate"}))
    VideoSelector.add_member(:sample_range, Smithy::Schema::Shapes::ShapeRef.new(shape: InputSampleRange, location_name: 'SampleRange', traits: {"smithy.api#documentation" => "If the sample range metadata in your input video is accurate, or if you don't know about sample range, keep the default value, Follow, for this setting. When you do, the service automatically detects your input sample range. If your input video has metadata indicating the wrong sample range, specify the accurate sample range here. When you do, MediaConvert ignores any sample range information in the input metadata. Regardless of whether MediaConvert uses the input sample range or the sample range that you specify, MediaConvert uses the sample range for transcoding and also writes it to the output metadata.", "smithy.api#jsonName" => "sampleRange"}))
    VideoSelector.type = Types::VideoSelector
    VideoTimecodeInsertion.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    VideoTimecodeInsertion.add_member(:pic_timing_sei, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PIC_TIMING_SEI', traits: {"smithy.api#enumValue" => "PIC_TIMING_SEI"}))
    VorbisSettings.add_member(:channels, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2, location_name: 'Channels', traits: {"smithy.api#documentation" => "Optional. Specify the number of channels in this output audio track. Choosing Mono on the console gives you 1 output channel; choosing Stereo gives you 2. In the API, valid values are 1 and 2. The default value is 2.", "smithy.api#jsonName" => "channels"}))
    VorbisSettings.add_member(:sample_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin22050max48000, location_name: 'SampleRate', traits: {"smithy.api#documentation" => "Optional. Specify the audio sample rate in Hz. Valid values are 22050, 32000, 44100, and 48000. The default value is 48000.", "smithy.api#jsonName" => "sampleRate"}))
    VorbisSettings.add_member(:vbr_quality, Smithy::Schema::Shapes::ShapeRef.new(shape: Integerminnegative1max10, location_name: 'VbrQuality', traits: {"smithy.api#documentation" => "Optional. Specify the variable audio quality of this Vorbis output from -1 (lowest quality, ~45 kbit/s) to 10 (highest quality, ~500 kbit/s). The default value is 4 (~128 kbit/s). Values 5 and 6 are approximately 160 and 192 kbit/s, respectively.", "smithy.api#jsonName" => "vbrQuality"}))
    VorbisSettings.type = Types::VorbisSettings
    Vp8FramerateControl.add_member(:initialize_from_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INITIALIZE_FROM_SOURCE', traits: {"smithy.api#enumValue" => "INITIALIZE_FROM_SOURCE"}))
    Vp8FramerateControl.add_member(:specified, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFIED', traits: {"smithy.api#enumValue" => "SPECIFIED"}))
    Vp8FramerateConversionAlgorithm.add_member(:duplicate_drop, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DUPLICATE_DROP', traits: {"smithy.api#enumValue" => "DUPLICATE_DROP"}))
    Vp8FramerateConversionAlgorithm.add_member(:interpolate, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTERPOLATE', traits: {"smithy.api#enumValue" => "INTERPOLATE"}))
    Vp8FramerateConversionAlgorithm.add_member(:frameformer, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FRAMEFORMER', traits: {"smithy.api#enumValue" => "FRAMEFORMER"}))
    Vp8FramerateConversionAlgorithm.add_member(:maintain_frame_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MAINTAIN_FRAME_COUNT', traits: {"smithy.api#enumValue" => "MAINTAIN_FRAME_COUNT"}))
    Vp8ParControl.add_member(:initialize_from_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INITIALIZE_FROM_SOURCE', traits: {"smithy.api#enumValue" => "INITIALIZE_FROM_SOURCE"}))
    Vp8ParControl.add_member(:specified, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFIED', traits: {"smithy.api#enumValue" => "SPECIFIED"}))
    Vp8QualityTuningLevel.add_member(:multi_pass, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MULTI_PASS', traits: {"smithy.api#enumValue" => "MULTI_PASS"}))
    Vp8QualityTuningLevel.add_member(:multi_pass_hq, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MULTI_PASS_HQ', traits: {"smithy.api#enumValue" => "MULTI_PASS_HQ"}))
    Vp8RateControlMode.add_member(:vbr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'VBR', traits: {"smithy.api#enumValue" => "VBR"}))
    Vp8Settings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1000max1152000000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Target bitrate in bits/second. For example, enter five megabits per second as 5000000.", "smithy.api#jsonName" => "bitrate"}))
    Vp8Settings.add_member(:framerate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp8FramerateControl, location_name: 'FramerateControl', traits: {"smithy.api#documentation" => "If you are using the console, use the Framerate setting to specify the frame rate for this output. If you want to keep the same frame rate as the input video, choose Follow source. If you want to do frame rate conversion, choose a frame rate from the dropdown list or choose Custom. The framerates shown in the dropdown list are decimal approximations of fractions. If you choose Custom, specify your frame rate as a fraction.", "smithy.api#jsonName" => "framerateControl"}))
    Vp8Settings.add_member(:framerate_conversion_algorithm, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp8FramerateConversionAlgorithm, location_name: 'FramerateConversionAlgorithm', traits: {"smithy.api#documentation" => "Choose the method that you want MediaConvert to use when increasing or decreasing your video's frame rate. For numerically simple conversions, such as 60 fps to 30 fps: We recommend that you keep the default value, Drop duplicate. For numerically complex conversions, to avoid stutter: Choose Interpolate. This results in a smooth picture, but might introduce undesirable video artifacts. For complex frame rate conversions, especially if your source video has already been converted from its original cadence: Choose FrameFormer to do motion-compensated interpolation. FrameFormer uses the best conversion method frame by frame. Note that using FrameFormer increases the transcoding time and incurs a significant add-on cost. When you choose FrameFormer, your input video resolution must be at least 128x96. To create an output with the same number of frames as your input: Choose Maintain frame count. When you do, MediaConvert will not drop, interpolate, add, or otherwise change the frame count from your input to your output. Note that since the frame count is maintained, the duration of your output will become shorter at higher frame rates and longer at lower frame rates.", "smithy.api#jsonName" => "framerateConversionAlgorithm"}))
    Vp8Settings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'FramerateDenominator', traits: {"smithy.api#documentation" => "When you use the API for transcode jobs that use frame rate conversion, specify the frame rate as a fraction. For example, 24000 / 1001 = 23.976 fps. Use FramerateDenominator to specify the denominator of this fraction. In this example, use 1001 for the value of FramerateDenominator. When you use the console for transcode jobs that use frame rate conversion, provide the value as a decimal number for Framerate. In this example, specify 23.976.", "smithy.api#jsonName" => "framerateDenominator"}))
    Vp8Settings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'FramerateNumerator', traits: {"smithy.api#documentation" => "When you use the API for transcode jobs that use frame rate conversion, specify the frame rate as a fraction. For example, 24000 / 1001 = 23.976 fps. Use FramerateNumerator to specify the numerator of this fraction. In this example, use 24000 for the value of FramerateNumerator. When you use the console for transcode jobs that use frame rate conversion, provide the value as a decimal number for Framerate. In this example, specify 23.976.", "smithy.api#jsonName" => "framerateNumerator"}))
    Vp8Settings.add_member(:gop_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0, location_name: 'GopSize', traits: {"smithy.api#documentation" => "GOP Length (keyframe interval) in frames. Must be greater than zero.", "smithy.api#jsonName" => "gopSize"}))
    Vp8Settings.add_member(:hrd_buffer_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max47185920, location_name: 'HrdBufferSize', traits: {"smithy.api#documentation" => "Optional. Size of buffer (HRD buffer model) in bits. For example, enter five megabits as 5000000.", "smithy.api#jsonName" => "hrdBufferSize"}))
    Vp8Settings.add_member(:max_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1000max1152000000, location_name: 'MaxBitrate', traits: {"smithy.api#documentation" => "Ignore this setting unless you set qualityTuningLevel to MULTI_PASS. Optional. Specify the maximum bitrate in bits/second. For example, enter five megabits per second as 5000000. The default behavior uses twice the target bitrate as the maximum bitrate.", "smithy.api#jsonName" => "maxBitrate"}))
    Vp8Settings.add_member(:par_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp8ParControl, location_name: 'ParControl', traits: {"smithy.api#documentation" => "Optional. Specify how the service determines the pixel aspect ratio (PAR) for this output. The default behavior, Follow source, uses the PAR from your input video for your output. To specify a different PAR in the console, choose any value other than Follow source. When you choose SPECIFIED for this setting, you must also specify values for the parNumerator and parDenominator settings.", "smithy.api#jsonName" => "parControl"}))
    Vp8Settings.add_member(:par_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'ParDenominator', traits: {"smithy.api#documentation" => "Required when you set Pixel aspect ratio to SPECIFIED. On the console, this corresponds to any value other than Follow source. When you specify an output pixel aspect ratio (PAR) that is different from your input video PAR, provide your output PAR as a ratio. For example, for D1/DV NTSC widescreen, you would specify the ratio 40:33. In this example, the value for parDenominator is 33.", "smithy.api#jsonName" => "parDenominator"}))
    Vp8Settings.add_member(:par_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max2147483647, location_name: 'ParNumerator', traits: {"smithy.api#documentation" => "Required when you set Pixel aspect ratio to SPECIFIED. On the console, this corresponds to any value other than Follow source. When you specify an output pixel aspect ratio (PAR) that is different from your input video PAR, provide your output PAR as a ratio. For example, for D1/DV NTSC widescreen, you would specify the ratio 40:33. In this example, the value for parNumerator is 40.", "smithy.api#jsonName" => "parNumerator"}))
    Vp8Settings.add_member(:quality_tuning_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp8QualityTuningLevel, location_name: 'QualityTuningLevel', traits: {"smithy.api#documentation" => "Optional. Use Quality tuning level to choose how you want to trade off encoding speed for output video quality. The default behavior is faster, lower quality, multi-pass encoding.", "smithy.api#jsonName" => "qualityTuningLevel"}))
    Vp8Settings.add_member(:rate_control_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Vp8RateControlMode, location_name: 'RateControlMode', traits: {"smithy.api#documentation" => "With the VP8 codec, you can use only the variable bitrate (VBR) rate control mode.", "smithy.api#jsonName" => "rateControlMode"}))
