    WavSettings.add_member(:channels, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max64, location_name: 'Channels', traits: {"smithy.api#documentation" => "Specify the number of channels in this output audio track. Valid values are 1 and even numbers up to 64. For example, 1, 2, 4, 6, and so on, up to 64.", "smithy.api#jsonName" => "channels"}))
    WavSettings.add_member(:format, Smithy::Schema::Shapes::ShapeRef.new(shape: WavFormat, location_name: 'Format', traits: {"smithy.api#documentation" => "Specify the file format for your wave audio output. To use a RIFF wave format: Keep the default value, RIFF. If your output audio is likely to exceed 4GB in file size, or if you otherwise need the extended support of the RF64 format: Choose RF64. If your player only supports the extensible wave format: Choose Extensible.", "smithy.api#jsonName" => "format"}))
