    XavcHdProfileSettings.add_member(:flicker_adaptive_quantization, Smithy::Schema::Shapes::ShapeRef.new(shape: XavcFlickerAdaptiveQuantization, location_name: 'FlickerAdaptiveQuantization', traits: {"smithy.api#documentation" => "The best way to set up adaptive quantization is to keep the default value, Auto, for the setting Adaptive quantization. When you do so, MediaConvert automatically applies the best types of quantization for your video content. Include this setting in your JSON job specification only when you choose to change the default value for Adaptive quantization. Enable this setting to have the encoder reduce I-frame pop. I-frame pop appears as a visual flicker that can arise when the encoder saves bits by copying some macroblocks many times from frame to frame, and then refreshes them at the I-frame. When you enable this setting, the encoder updates these macroblocks slightly more often to smooth out the flicker. This setting is disabled by default. Related setting: In addition to enabling this setting, you must also set Adaptive quantization to a value other than Off or Auto. Use Adaptive quantization to adjust the degree of smoothing that Flicker adaptive quantization provides.", "smithy.api#jsonName" => "flickerAdaptiveQuantization"}))
    XavcHdProfileSettings.add_member(:gop_b_reference, Smithy::Schema::Shapes::ShapeRef.new(shape: XavcGopBReference, location_name: 'GopBReference', traits: {"smithy.api#documentation" => "Specify whether the encoder uses B-frames as reference frames for other pictures in the same GOP. Choose Allow to allow the encoder to use B-frames as reference frames. Choose Don't allow to prevent the encoder from using B-frames as reference frames.", "smithy.api#jsonName" => "gopBReference"}))
    XavcHdProfileSettings.add_member(:gop_closed_cadence, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max2147483647, location_name: 'GopClosedCadence', traits: {"smithy.api#documentation" => "Frequency of closed GOPs. In streaming applications, it is recommended that this be set to 1 so a decoder joining mid-stream will receive an IDR frame as quickly as possible. Setting this value to 0 will break output segmenting.", "smithy.api#jsonName" => "gopClosedCadence"}))
    XavcHdProfileSettings.add_member(:hrd_buffer_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max1152000000, location_name: 'HrdBufferSize', traits: {"smithy.api#documentation" => "Specify the size of the buffer that MediaConvert uses in the HRD buffer model for this output. Specify this value in bits; for example, enter five megabits as 5000000. When you don't set this value, or you set it to zero, MediaConvert calculates the default by doubling the bitrate of this output point.", "smithy.api#jsonName" => "hrdBufferSize"}))
    XavcHdProfileSettings.add_member(:interlace_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: XavcInterlaceMode, location_name: 'InterlaceMode', traits: {"smithy.api#documentation" => "Choose the scan line type for the output. Keep the default value, Progressive to create a progressive output, regardless of the scan type of your input. Use Top field first or Bottom field first to create an output that's interlaced with the same field polarity throughout. Use Follow, default top or Follow, default bottom to produce outputs with the same field polarity as the source. For jobs that have multiple inputs, the output field polarity might change over the course of the output. Follow behavior depends on the input scan type. If the source is interlaced, the output will be interlaced with the same polarity as the source. If the source is progressive, the output will be interlaced with top field bottom field first, depending on which of the Follow options you choose.", "smithy.api#jsonName" => "interlaceMode"}))
    XavcHdProfileSettings.add_member(:quality_tuning_level, Smithy::Schema::Shapes::ShapeRef.new(shape: XavcHdProfileQualityTuningLevel, location_name: 'QualityTuningLevel', traits: {"smithy.api#documentation" => "Optional. Use Quality tuning level to choose how you want to trade off encoding speed for output video quality. The default behavior is faster, lower quality, single-pass encoding.", "smithy.api#jsonName" => "qualityTuningLevel"}))
    XavcHdProfileSettings.add_member(:slices, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin4max12, location_name: 'Slices', traits: {"smithy.api#documentation" => "Number of slices per picture. Must be less than or equal to the number of macroblock rows for progressive pictures, and less than or equal to half the number of macroblock rows for interlaced pictures.", "smithy.api#jsonName" => "slices"}))
    XavcHdProfileSettings.add_member(:telecine, Smithy::Schema::Shapes::ShapeRef.new(shape: XavcHdProfileTelecine, location_name: 'Telecine', traits: {"smithy.api#documentation" => "Ignore this setting unless you set Frame rate (framerateNumerator divided by framerateDenominator) to 29.970. If your input framerate is 23.976, choose Hard. Otherwise, keep the default value None. For more information, see https://docs.aws.amazon.com/mediaconvert/latest/ug/working-with-telecine-and-inverse-telecine.html.", "smithy.api#jsonName" => "telecine"}))
    XavcHdProfileSettings.type = Types::XavcHdProfileSettings
    XavcHdProfileTelecine.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
    XavcHdProfileTelecine.add_member(:hard, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HARD', traits: {"smithy.api#enumValue" => "HARD"}))
    XavcInterlaceMode.add_member(:progressive, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROGRESSIVE', traits: {"smithy.api#enumValue" => "PROGRESSIVE"}))
    XavcInterlaceMode.add_member(:top_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TOP_FIELD', traits: {"smithy.api#enumValue" => "TOP_FIELD"}))
    XavcInterlaceMode.add_member(:bottom_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BOTTOM_FIELD', traits: {"smithy.api#enumValue" => "BOTTOM_FIELD"}))
