    XavcInterlaceMode.add_member(:follow_bottom_field, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FOLLOW_BOTTOM_FIELD', traits: {"smithy.api#enumValue" => "FOLLOW_BOTTOM_FIELD"}))
